const W=[{id:"T01",title:"Dai, Milkman & Riis · 2014 · The fresh-start effect",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Three archival datasets showed increases in goal initiation around calendar landmarks, including diet searches, university gym visits, and commitment contracts.",limitation:"Observational initiation measures do not establish causation, sustained change, or the effect of declaring an arbitrary date a beginning."},{id:"T02",title:"Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"Among 165 online adults, 25.61% chose a March 20 reminder when framed as spring’s beginning versus 7.23% when framed as the third Thursday.",limitation:"This contrast measured reminder selection, not actual action or lasting change. A personally declared starting day is an ODA adaptation."},{id:"T03",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"Across 94 independent tests with 8,461 participants, specific if–then plans improved goal attainment on average: d = 0.65, 95% CI [0.60, 0.70].",limitation:"Varied settings and older methods limit generalization. The effect is not a 65% success increase, and this brief ODA planner was not tested."},{id:"T04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"A meta-analysis of 21 articles and 24 effects, involving 15,907 participants, found a modest average goal-attainment benefit: g = 0.336, 95% CI [0.229, 0.443].",limitation:"Results varied, with possible publication bias. Two large online samples dominate the participant total. Imagery does not attract outcomes, and ODA’s exercise was not tested."},{id:"T05",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Across 138 randomized studies with 19,951 participants, progress-monitoring interventions improved goal attainment on average: d = 0.40, 95% CI [0.32, 0.48].",limitation:"Goals and methods varied. Physical recording and reporting were associated with larger effects in moderator analyses; public disclosure is not necessary and this ODA ledger was not tested."},{id:"T06",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 volunteers. Among 39 good-fitting curves, the model estimated 18–254 days to 95% of each automaticity asymptote, with a median of 66.",limitation:"These were modeled estimates, not observed completion dates. Self-reported everyday health behaviors do not establish a universal timeline or a two-missed-opportunity threshold."},{id:"T07",title:"Singh et al. · 2024 · Time to form a habit",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"A review of 20 health-behavior studies with 2,601 participants found highly variable formation-time estimates. Only four studies supplied timing estimates; individual estimates ranged from 4 to 335 days.",limitation:"Eleven studies had high bias risk. Timing definitions differed. Pre–post habit-strength change is not a controlled treatment effect or a personal deadline."},{id:"T08",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"This review describes how repeating responses in recurring contexts can make behavior cue-driven, while deliberate goals and habits can work together.",limitation:"An integrative narrative review, not a new trial or pooled effect. It does not show that object placement removes motivation needs or that every complex goal becomes automatic."},{id:"T09",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’s theory identifies personal accomplishment, watching others, encouragement, and bodily states as sources of expectations about performing a particular behavior, with emphasis on personal mastery.",limitation:"A theory integrating earlier research, not a new trial. It does not prove that every small act raises confidence or establishes broad capability."},{id:"T11",title:"Scullin et al. · 2018 · Bedtime task-list writing",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"In one laboratory night, 57 healthy adults aged 18–30 wrote future tasks or completed activities on paper for five minutes. Mean sleep-onset latency was 15.82 versus 25.09 minutes.",limitation:"Another writing task was the comparator. No significant increase in total sleep or long-term insomnia benefit was established. Spoken suggestions and ODA’s brief review were not tested."},{id:"T12",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and exam procrastination",url:"https://doi.org/10.1016/j.paid.2010.01.029",type:"research",finding:"Among 119 first-year students, greater self-forgiveness for procrastinating before one midterm was associated with less procrastination before the next.",limitation:"Observational measurements in one course do not establish causation. The abstract does not verify an effect coefficient or a benefit from a scripted sentence."},{id:"T15",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Study 1 randomized 84 German undergraduates. The combined exercise group scheduled more hours than two controls; the planned contrast was significant, while the overall condition test was p = .057.",limitation:"Scheduled hours were an intention measure, not hours worked or completed projects. The study does not validate ODA’s short action and next-day review."},{id:"T17",title:"James Clear · The two-minute rule",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Clear suggests shrinking a new behavior to a brief entry action. This is practitioner guidance for choosing an approachable start.",limitation:"The precise two-minute dose is not established as optimal by controlled research. Preparation is not the same as completing a useful unit of the intended behavior."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’s theory identifies personal accomplishment, watching others, encouragement, and bodily states as sources of expectations about performing a particular behavior, with emphasis on personal mastery.",limitation:"A theory integrating earlier research, not a new trial. It does not prove that every small act raises confidence or establishes broad capability."},{id:"habits",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 volunteers. Among 39 good-fitting curves, the model estimated 18–254 days to 95% of each automaticity asymptote, with a median of 66.",limitation:"These were modeled estimates, not observed completion dates. Self-reported everyday health behaviors do not establish a universal timeline or a two-missed-opportunity threshold."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP",url:"https://woopmylife.org/en/home",type:"technique",finding:"WOOP combines a wish, desired outcome, inner obstacle, and if–then plan. Related research supports planning on average, with varied results.",limitation:"The developer’s site is not an independent evaluation. MCII findings do not validate every version of the method or make external constraints a mindset failure."}],l=[{schemaVersion:2,revision:2,id:"turning-day-1",courseId:"turning-day",locale:"en",title:"Still waiting for Monday? Make one real start",goal:"Take one useful unit toward a chosen direction, then schedule a next opportunity.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"What keeps landing on next Monday’s list instead of today’s life?",reason:{id:"turning-day-1-reason",label:"What deserves two minutes, and what can wait?",kind:"text",maxLength:160,optional:!0,suggestions:["Make room for creativity","Practice before another week passes","Protect time for what matters"]},why:{id:"turning-day-1-why",label:"What deserves two minutes, and what can wait?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A date can influence a starting choice without showing follow-through. In one experiment, the same March date attracted more reminder choices when called spring’s beginning. The study did not show whether people acted on those reminders.","Use the opening for one small act in your chosen direction. Draw an object, write a usable sentence, or read a needed paragraph. Choosing a date is preparation. Do the act, record it, and name your next cue. Carry this experiment through the course."],example:{title:"Dana’s first drawing",text:"Dana keeps postponing drawing until Monday. On Wednesday, after tea at her kitchen table, she sketches the mug for two minutes. The handle looks crooked. She records one sketch, then chooses tomorrow’s tea as her next cue. Naming Wednesday a beginning helped her choose; it did not improve her drawing."}},move:{invitation:"Choose drawing, writing, or reading only if it serves your direction.",instructions:["Check the example fits your direction before filling a blank plan.","Try your chosen act, then record it here."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Use a smaller object or adapted tools","Dictate one sentence if typing is difficult","Use accessible text or read aloud"],observation:["The sketch I finished","The usable sentence I wrote","The paragraph I read"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Use a smaller object or adapted tools",observation:"The sketch I finished",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"After my next meal",place:"At my usual work surface",fallback:"Dictate one sentence if typing is difficult",observation:"The usable sentence I wrote",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Use accessible text or read aloud",observation:"The paragraph I read",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"My available time or tools change",fallbackHint:"Use a smaller object or adapted tools",observationHint:"The sketch I finished",requiresChoice:!0},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Choose a safe task. Adapt or pause if health, care, or access needs take priority."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-1-decision",scenario:"Dana has two free minutes and paper at her kitchen table. She wants to draw but usually waits for Monday.",question:"Which move fits these facts?",options:[{id:"draw-now",text:"Sketch the nearby mug now, record the sketch, and choose another feasible opportunity tomorrow.",feedback:"This uses an available opening for actual drawing. The sketch can be rough. Record the unit you completed, then give the same experiment its next cue."},{id:"schedule-course",text:"Use the two minutes to schedule a full drawing course for next week.",feedback:"A course might help later, but Dana already has enough time and materials for one sketch. Scheduling makes a plan; drawing tests her chosen direction today."},{id:"choose-supplies",text:"Compare beginner drawing supplies, then decide which object will be easiest to draw.",feedback:"Suitable tools matter when they are missing. Dana already has paper and a usable object. More selection uses this opening without producing a drawing attempt."}],bestOptionId:"draw-now"}},carry:{takeaway:"A beginning becomes evidence when you do one useful unit.",followUp:{questionId:"turning-day-1-return",question:"Did your useful unit happen when your chosen cue arrived?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"A reminder is not an attempt",paragraphs:["Dai, Milkman, and Riis studied fresh starts through three archival datasets in 2014 [T01]. Diet searches, university gym attendance, and new commitment contracts increased around some calendar landmarks. These are different initiation measures. They do not establish that the landmark caused the change or that participants sustained their goals.","In a later experiment, 165 online adults chose between dates for a goal reminder [T02]. For March 20, 25.61% chose the reminder when the date was called spring’s beginning. The figure was 7.23% when it was called the third Thursday. That contrast concerns selecting a reminder. It does not tell us who acted afterward.","Calling today your beginning is an optional ODA framing device. The course does not claim that naming an arbitrary date reproduces these findings. Your record starts with what you actually do."]},{heading:"Give the opening a behavior",paragraphs:["An if–then plan connects a recognizable situation with a response chosen beforehand. Gollwitzer and Sheeran reviewed 94 independent tests with 8,461 participants [T03]. Such plans improved goal attainment on average across those settings. Different tasks, populations, and research methods make that average a poor personal forecast. This short ODA lesson was not tested in the review.","For this experiment, choose a useful unit that serves your direction. “After tea at the kitchen table, sketch one object” names a cue, a place, and an act. Putting out paper is preparation. Making a sketch is drawing practice. Either can matter, but record the one you actually did.","Your direction can serve care, recovery, connection, or learning. If the available setting cannot support a safe act, choose a feasible later opening or support. A calendar label cannot remove a real constraint."]}],sourceIds:["T01","T02","T03"]}},{schemaVersion:2,revision:2,id:"turning-day-2",courseId:"turning-day",locale:"en",title:"Your plan meets the couch. Prepare for it",goal:"Use one feasible response to a likely obstacle in your existing experiment.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Where could your good plan collide with your actual afternoon?",reason:{id:"turning-day-2-reason",label:"What stopped your last try, and what can change?",kind:"text",maxLength:160,optional:!0,suggestions:["Cue arrived while I was working","Needed recovery after my shift","A tool was unavailable"]},why:{id:"turning-day-2-why",label:"What stopped your last try, and what can change?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep your useful unit. Check what might block it. A reaction you can answer differs from missing childcare, equipment, safe space, or capacity. Change an infeasible plan rather than treating every barrier as a problem inside you.","Link an obstacle or opportunity to a feasible response: “After taking off my work coat, I sketch one object at the table.” Studies support specific plans on average, with varied results. Writing is preparation. Test your response, then record whether it was available and used."],example:{title:"Dana’s after-work cue",text:"Dana’s shifts end at different times, so 6 p.m. rarely fits her drawing plan. She chooses taking off her work coat as the cue. At the kitchen table, she sketches her keys before turning on a show. She finishes one rough sketch; on the following late shift, she needs rest instead."}},move:{invitation:"Keep your saved action and minimum. Change one observed obstacle or opportunity.",instructions:["Keep any cue that fits; edit If blocked for the barrier you saw.","No previous attempt? Choose a feasible opening for your same act."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After taking off my work coat","When my planned break begins","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use tomorrow’s afternoon break","Rest; use tomorrow’s available work break","Rest; read after tomorrow’s meal"],observation:["Whether the cue and sketch happened","Whether the cue and sentence happened","Whether the cue and reading happened"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After taking off my work coat",place:"At my kitchen table",fallback:"Rest; use tomorrow’s afternoon break",observation:"Whether the cue and sketch happened",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"When my planned break begins",place:"At my usual work surface",fallback:"Rest; use tomorrow’s available work break",observation:"Whether the cue and sentence happened",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Rest; read after tomorrow’s meal",observation:"Whether the cue and reading happened",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After taking off my work coat",placeHint:"At my kitchen table",obstacleHint:"I need recovery after a shift",fallbackHint:"Rest; use tomorrow’s afternoon break",observationHint:"Whether the cue and sketch happened"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Do not push through exhaustion, danger, or missing access. Choose rest, support, or another opportunity."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-2-workday-cue-decision",scenario:"Dana wants brief sketches on ordinary workdays. Her shifts change, so 6 p.m. often falls during work. Taking off her coat happens at home, where two minutes are usually available.",question:"Which plan fits workdays with less daily rescheduling?",options:[{id:"days-off-session",text:"Choose short sessions on days off, accepting fewer workday chances while protecting her energy.",feedback:"Days-off practice can protect recovery and may suit a different aim. Dana wants brief workday opportunities; the homecoming event offers them without having to predict each shift ending."},{id:"coat-cue",text:"After taking off her coat, sketch one object; choose rest or another feasible opening when exhausted.",feedback:"This uses a recognizable event and preserves recovery. Dana can test the same drawing unit without pretending the clock or a stronger reminder controls her shifts."},{id:"shift-calendar-alert",text:"Check her shift calendar daily and set a sketch alert thirty minutes after the expected finish.",feedback:"This can work when finish times hold. Changing shifts add alert upkeep and uncertainty. The homecoming event already signals an available setting; test it while keeping rest an option."}],bestOptionId:"coat-cue"}},carry:{takeaway:"Plan for the conditions you have, then test the response.",followUp:{questionId:"turning-day-2-return",question:"Did your cue occur, and was your planned response actually possible?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"An obstacle is not always inside you",paragraphs:["Mental contrasting pairs a desired outcome with the obstacle to reaching it. Adding an if–then response is often called MCII. Wang and colleagues reviewed 21 articles with 24 independent effects and 15,907 participants [T04]. They found a modest average benefit for goal attainment, with differences across studies and possible publication bias.","This approach can clarify that a wish needs adjustment. It does not establish that imagining an outcome attracts it, that every obstacle is an emotion, or that pushing harder is always appropriate. External conditions belong in the feasibility check. Money, disability access, workload, and care responsibilities cannot be reduced to reluctance.","ODA’s adaptation asks you to keep your chosen direction while testing one response. The response might be a smaller unit, a different opportunity, or a practical request. Record whether it was possible before judging whether it worked."]},{heading:"A planning result is still a plan",paragraphs:["In one primary time-management study, 84 German undergraduates were randomized to three conditions [T15]. The combined mental-contrasting and planning group scheduled more hours than the controls. The planned contrast was significant, while the overall condition test was p = .057. Scheduled hours were the outcome. The study did not establish how many hours participants actually worked.","Across a broader review, specific if–then plans improved goal attainment on average [T03]. There is no single tested timer length or universal daily dose across those experiments. ODA’s short response trial and next-day return are educational adaptations, not the original research protocol.","A useful observation separates three questions: did the cue appear, was the response available, and did you use it? If the obstacle never occurred, the fallback remains untested. If the response was impossible, change the conditions or the plan."]}],sourceIds:["T03","T04","T15"]}},{schemaVersion:2,revision:2,id:"turning-day-3",courseId:"turning-day",locale:"en",title:"“I never follow through” needs a fact check",goal:"Complete one useful unit of your existing experiment and describe exactly what that attempt proves.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Did one rough attempt become another verdict about your whole life?",reason:{id:"turning-day-3-never-fact-check-reason",label:"Which part of your “never” claim does the last attempt support or contradict?",kind:"text",maxLength:160,optional:!0,suggestions:["One act happened; skill needs work","Cue missed; ability still untested","No attempt recorded yet"]},why:{id:"turning-day-3-why",label:"What would one honest practice unit serve this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Belief about doing a particular task differs from your worth. One theory gives personal accomplishment an important role in that belief. It does not establish that every tiny act raises confidence or proves broad ability.","Return to your same unit. Describe the act precisely: “I drew one object; the outline needs work.” An imperfect attempt can meet your minimum while revealing a skill gap. Two minutes is a practical starting estimate, not an optimal dose established by research. Confidence can stay unchanged; record the act anyway."],example:{title:"Dana’s crooked handle",text:"After taking off her coat, Dana sketches one mug at the kitchen table. The handle looks crooked again, and she feels no more confident. Her note says, “One mug drawn; handle proportions need practice.” She chooses the same unit for her next available afternoon. One drawing does not prove she can design a poster."}},move:{invitation:"Keep your saved act and cue. Record its output and one limitation.",instructions:["Keep your action and minimum.","Under What will you look for, name output and a remaining limitation."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","At my next available break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Ask for help with the handle","Mark the fact needing a check","Mark the point needing an explanation"],observation:["Sketch output and one skill gap","Sentence output and one unchecked fact","Paragraph read and one unclear point"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Ask for help with the handle",observation:"Sketch output and one skill gap",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next available break",place:"At my usual work surface",fallback:"Mark the fact needing a check",observation:"Sentence output and one unchecked fact",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Mark the point needing an explanation",observation:"Paragraph read and one unclear point",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"One part of the output needs help",fallbackHint:"Ask for help with the handle",observationHint:"Sketch output and one skill gap"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Choose safe practice within your capacity. A poor result can call for support, adaptation, or a pause."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-3-specific-record-decision",scenario:"Dana finished her promised mug sketch. Its handle is crooked, and she feels no more confident. She is choosing what to record.",question:"Which record best guides the next practice?",options:[{id:"repeat-before-assessing",text:"Record the finished sketch and repeat the same mug unchanged before deciding which detail needs practice.",feedback:"Repetition can help when the practice target is unclear. Dana can already name the crooked handle. Include that detail now so the next attempt can test a specific skill."},{id:"specific-evidence",text:"Record one completed mug sketch and the crooked handle, then choose the next practice opportunity.",feedback:"This names both the act and its limitation. Dana met the sketch minimum without proving broad drawing ability or requiring a confidence change. The next attempt can address the handle."},{id:"cue-reliability-from-once",text:"Record the finished sketch and keep this cue for next week because it worked today.",feedback:"Keeping a promising cue is reasonable as a trial. One completed attempt does not establish a reliable routine. Record the handle issue and test the cue again under the next conditions."}],bestOptionId:"specific-evidence"}},carry:{takeaway:"Name the behavior precisely. Let the remaining skill gap guide practice.",followUp:{questionId:"turning-day-3-return",question:"What did your finished unit show, and what still needs work?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"Task belief is a specific expectation",paragraphs:["Bandura’s 1977 article describes self-efficacy as an expectation about carrying out a particular behavior [T09]. It identifies personal accomplishments, observing others, encouragement, and physiological states as information for that expectation. The theory emphasizes personal mastery. It is not a trial establishing that every small action creates confidence or that mastery always outranks other support in every setting.","For this course, that distinction keeps the record useful. A completed sketch shows that you made that sketch under those conditions. It may reveal something about your tools, cue, or current skill. It does not measure your worth or establish that you can complete every future project.","If your work reveals missing knowledge, the next move can include instruction or help. If capacity or safety changes, adapt or pause. This is ordinary personal-growth practice, not treatment for intense anxiety or a test of character."]},{heading:"Small enough is not the same as complete",paragraphs:["James Clear’s two-minute rule is practitioner guidance, not a controlled finding that two minutes is optimal [T17]. A short entry can make a task approachable, but putting out a pencil is preparation. Drawing an object is drawing practice. Choose the minimum that actually serves your direction, and record preparation honestly when that is the appropriate act.","Progress monitoring improved goal attainment on average in Harkin and colleagues’ review of 138 randomized studies [T05]. Goals and methods varied. Physically recording progress was associated with larger effects in moderator analyses, but that does not validate ODA’s precise note format or require public sharing.","A short record can hold output and limitation together: one usable sentence written, but one fact still needs checking. Do not enlarge the claim because the step felt good or erase it because it felt disappointing. Choose the next unit from the evidence available."]}],sourceIds:["T09","T05","T17"]}},{schemaVersion:2,revision:2,id:"turning-day-4",courseId:"turning-day",locale:"en",title:"Stop making your next step hard to find",goal:"Test one setup change at the cue for your continuing useful-unit experiment.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Was the tool you needed hidden while the distraction sat within reach?",reason:{id:"turning-day-4-reason",label:"Which setup demand can you remove without losing access?",kind:"text",maxLength:160,optional:!0,suggestions:["Find my tools at the cue","Keep needed contact available","Use a private record"]},why:{id:"turning-day-4-why",label:"Which setup demand can you remove without losing access?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A cue includes an action’s setting, not just a phone reminder. Research describes how repeating a response in recurring contexts can make it more cue-driven. Preparing a needed item can reduce setup demands; it cannot remove effort or guarantee you remember.","Check your experiment’s last record. If finding tools was the obstacle, place them at your cue, then test your unit there. Keep necessary calls, care alerts, and accessibility tools available. Record privately if you prefer. Moving an object is setup; doing the unit tests it."],example:{title:"Dana keeps the phone reachable",text:"Dana’s last drawing opportunity disappeared while she searched for paper. She places a scrap pad and pencil beside her tea mug, then sketches the spoon after tea. Her phone stays reachable for family calls. She records one sketch privately. The setup worked this time; tomorrow’s shift may need a different cue."}},move:{invitation:"Keep your saved act, cue, and place. Test one setup change.",instructions:["Under What will you look for, name one material or access change.","Test your same minimum with that setup."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","When my planned break begins","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Use an accessible backup pencil","Use my accessible backup writing tool","Open an accessible copy of the text"],observation:["Which pencil placement helped the sketch","Which document access change helped writing","Which text access change helped reading"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Use an accessible backup pencil",observation:"Which pencil placement helped the sketch",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"When my planned break begins",place:"At my usual work surface",fallback:"Use my accessible backup writing tool",observation:"Which document access change helped writing",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Open an accessible copy of the text",observation:"Which text access change helped reading",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"Materials are hard to find or reach",fallbackHint:"Use an accessible backup pencil",observationHint:"Which pencil placement helped the sketch"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Keep emergency, care, and accessibility contact available when changing your setup."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"Which setup change did you test, and what did you actually do?"},judgment:{primary:{id:"turning-day-4-decision",scenario:"Dana lost a drawing opportunity searching for paper. She needs her phone reachable for family calls and prefers keeping her progress private.",question:"Which move fits these facts?",options:[{id:"mute-nonessential-alerts",text:"Mute nonessential alerts while keeping family calls, then rely on remembering where the paper is stored.",feedback:"This preserves needed contact and may reduce interruptions. It leaves the observed missing-materials problem unchanged. Put the drawing materials at the tea cue, then test the same sketch."},{id:"ready-tools",text:"Place paper beside her tea mug, preserve family calls, and test one sketch with a private record.",feedback:"This targets the observed setup problem without requiring disclosure or cutting off contact. Testing a sketch shows whether the ready tools helped at this particular opportunity."},{id:"private-reminder-first",text:"Set a private drawing reminder after tea and leave her paper in its usual storage place.",feedback:"A reminder may help with noticing the cue. Dana already notices tea, but cannot find the paper. Test the tool placement first, then consider a reminder if noticing becomes the problem."}],bestOptionId:"ready-tools"}},carry:{takeaway:"Test the setup against the real act. Keep privacy and necessary access.",followUp:{questionId:"turning-day-4-return",question:"Did the setup change help you use your cue and do the unit?",observationPrompt:"Which setup change helped or failed to help your saved act?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"Context helps without doing the work for you",paragraphs:["Wood and Rünger’s review describes how repeated responses in recurring contexts can become cue-driven [T08]. Deliberate goals and habits can work together. This is an integrative review, not a trial proving that one particular object placement works for everyone. It does not establish a finite willpower battery or show that preparation removes executive difficulty.","Lally and colleagues followed everyday health behaviors for 84 days [T06]. Repetition in a consistent context accompanied increases in self-reported automaticity. There was no randomized no-practice control. This cannot supply a guaranteed timeline or prove the exact effect of placing a pencil near a mug.","ODA asks you to test a small environmental change because your last record identified a setup demand. Keep the action, cue, and minimum recognizable. That lets the next observation answer a practical question: were the needed materials available, and did you use them?"]},{heading:"Private recording is a full route",paragraphs:["Harkin and colleagues reviewed 138 randomized studies of progress monitoring [T05]. Monitoring interventions improved goal attainment on average. Physical recording and reporting were associated with larger effects in moderator analyses. Those comparisons do not prove that one friend is enough, that public disclosure is necessary, or that a private learner has chosen an inferior route.","A supportive check-in can be offered if you want it. You choose the person, the information, and the occasion. A factual private note remains a complete option here. There is no requirement to expose a goal, seek applause, or invite pressure from someone who is unsafe.","Likewise, changing phone placement must preserve necessary contact and accessibility. Target the observed hurdle: an item out of reach, a document difficult to find, or a nonessential alert. Record setup as setup, then observe what happened when you tried the same useful unit."]}],sourceIds:["T08","T05","T06"]}},{schemaVersion:2,revision:2,id:"turning-day-5",courseId:"turning-day",locale:"en",title:"Tonight, record the facts behind “I failed”",goal:"Review your experiment’s actual attempt and save one feasible next opportunity without rewriting its history.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Calling today a failure? What does the record actually show?",reason:{id:"turning-day-5-reason",label:"What does your record show needs a change?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep preparation and practice separate","Learn from a missed opening","Leave tomorrow in the plan"]},why:{id:"turning-day-5-why",label:"What does your record show needs a change?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Put today’s act in the record and tomorrow’s intention in the plan. Research supports checking progress on average; a prepared tool does not show the practice happened. Preserve the minimum you committed to.","Name the act or gap in your experiment’s latest attempt, then choose one next opportunity. A study linked self-forgiveness with less later exam procrastination, without showing causation or validating a kind sentence. Review without blaming yourself or inventing success. If late review increases worry, choose an earlier slot."],example:{title:"Dana’s paper was ready",text:"Dana put paper beside her mug but stayed late at work. Her evening tea cue happened, and she did not draw. Before winding down, she records setup separately and drawing not yet. Tomorrow’s sketch after tea stays a plan. The review is brief; she still feels disappointed."}},move:{invitation:"Review your saved attempt. Keep the act; adjust one condition the record identifies.",instructions:["Record the actual attempt before editing its next occurrence.","Keep the action and minimum; change only the condition that did not fit."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At my next earlier tea break","At my next earlier work break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use tomorrow’s earlier tea break","Rest; use tomorrow’s earlier work break","Rest; read after tomorrow’s earlier meal"],observation:["Sketch output at the revised cue","Sentence output at the revised cue","Reading done at the revised cue"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"At my next earlier tea break",place:"At my kitchen table",fallback:"Rest; use tomorrow’s earlier tea break",observation:"Sketch output at the revised cue",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next earlier work break",place:"At my usual work surface",fallback:"Rest; use tomorrow’s earlier work break",observation:"Sentence output at the revised cue",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Rest; read after tomorrow’s earlier meal",observation:"Reading done at the revised cue",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"At my next earlier tea break",placeHint:"At my kitchen table",obstacleHint:"Late work leaves too little capacity",fallbackHint:"Rest; use tomorrow’s earlier tea break",observationHint:"Sketch output at the revised cue"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"If review increases worry or wakefulness, stop. Choose an earlier review slot or rest."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-5-decision",scenario:"Dana did not draw her one-sketch minimum after late work. She had set out paper. Tomorrow has an earlier tea break; a longer weekend session is also possible.",question:"Which move fits these facts?",options:[{id:"same-cue-new-alert",text:"Record drawing not yet, keep the evening cue, and add an alert for that same time.",feedback:"This keeps the record honest. An alert addresses noticing, but Dana’s difficulty was late-work capacity. The earlier tea break lets her test the same minimum in a more feasible slot."},{id:"honest-change",text:"Record setup separately, report drawing not yet, and choose an earlier feasible cue for the same minimum.",feedback:"This preserves the promised minimum and reports what happened. Tomorrow’s intention stays a plan. Dana can change the cue without pretending setup was drawing or condemning the whole day."},{id:"weekend-session",text:"Record drawing not yet and move the experiment to a longer session on the weekend.",feedback:"A weekend session is a valid choice if it fits better. Here an earlier break is available tomorrow. Trying the same minimum there tests a smaller change before changing both timing and size."}],bestOptionId:"honest-change"}},carry:{takeaway:"Keep the past record honest. Change the next opportunity when the facts call for it.",followUp:{questionId:"turning-day-5-return",question:"Did the revised opportunity fit better, and what did you actually do?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"A fair review preserves responsibility",paragraphs:["Wohl and colleagues followed 119 first-year students around two midterms [T12]. Greater self-forgiveness for earlier procrastination was associated with less procrastination before the next exam. This was observational research in one course. It does not establish that forgiveness caused the change, that a scripted sentence changes behavior, or that self-criticism always produces avoidance.","You do not have to feel forgiving to make an accurate record. “I prepared the paper, but did not draw because work ran late” states two distinct facts. “Tomorrow I will draw after my first tea” states a plan. Preserve those categories even when the original attempt felt disappointing.","Progress monitoring has broader experimental support on average [T05], but ODA’s exact receipt and review flow have not been evaluated by that review. The purpose here is practical: choose the next condition from the information available, without turning a plan into proof."]},{heading:"The bedtime list finding has a narrow boundary",paragraphs:["Scullin and colleagues analyzed 57 healthy adults aged 18–30 during one laboratory night [T11]. Participants wrote with pen and paper for five minutes about future tasks or completed activities. The future-task group fell asleep sooner on average: 15.82 versus 25.09 minutes. The comparison was another writing task, not no writing. The study did not establish significantly more total sleep.","This result does not validate spoken suggestions, imagining tomorrow, or reviewing successes as sleep treatments. The five-minute paper task was a separate protocol. ODA’s short factual review and action plan are not that tested intervention. They do not promise sleep or require bedtime writing.","If review increases worry or keeps you awake, stop and choose an earlier opportunity. Rest can be the appropriate next step. Persistent sleep difficulties warrant professional assessment without waiting for this course to end. Keep the same useful-unit experiment; no new bedtime ritual is needed."]}],sourceIds:["T05","T12","T11"]}},{schemaVersion:2,revision:2,id:"turning-day-6",courseId:"turning-day",locale:"en",title:"Missed days? Build a week that fits",goal:"Use your existing records to choose a realistic next week for the same experiment, including safe pauses.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"What do your records reveal about the week you actually have?",reason:{id:"turning-day-6-reason",label:"Is this unit serving your direction at a workable cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the part that fits","Change the cue instead of compensating","Make room for recovery"]},why:{id:"turning-day-6-why",label:"Is this unit serving your direction at a workable cost?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Compare planned opportunities, actual attempts, and useful output from your same experiment. A week tests fit; it does not complete a habit. The often-quoted 18–254 days came from modeled estimates in a study observing people for only 84 days.","Keep or shrink the unit, change its cue, or pause. One missed opportunity did not materially disrupt the process studied; no two-miss cutoff was established. Save one feasible next opportunity. ODA schedules its next-day return. Preserve the history, including gaps."],example:{title:"Dana’s week has gaps",text:"Dana planned five sketch opportunities and completed three. Both gaps followed late shifts. At Sunday tea, she keeps the one-object minimum and moves only the late-shift cue to Monday’s afternoon break. She saves that opportunity; ODA schedules Tuesday’s return. Three rough sketches remain three sketches, with two honest gaps."}},move:{invitation:"Keep your saved unit and workable cue. Adjust only the condition that blocked you.",instructions:["No record yet? Choose a first feasible trial.","Save the next opportunity; ODA schedules a return the following day."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At my next afternoon tea break","At my next available work break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use the next afternoon break","Use tomorrow’s reserved work break","Read after the next available meal"],observation:["Sketch output and cue availability","Sentence output and cue availability","Reading done and cue availability"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"At my next afternoon tea break",place:"At my kitchen table",fallback:"Rest; use the next afternoon break",observation:"Sketch output and cue availability",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next available work break",place:"At my usual work surface",fallback:"Use tomorrow’s reserved work break",observation:"Sentence output and cue availability",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Read after the next available meal",observation:"Reading done and cue availability",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"At my next afternoon tea break",placeHint:"At my kitchen table",obstacleHint:"Late shifts block this practice slot",fallbackHint:"Rest; use the next afternoon break",observationHint:"Sketch output and cue availability"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Illness, exhaustion, care, or unsafe conditions can require consecutive pauses. Resume only when feasible."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-6-observed-fit-decision",scenario:"Dana planned five sketches and made three. Both gaps followed late shifts. The one-object minimum worked at other opportunities.",question:"Which move fits these facts?",options:[{id:"shrink-before-moving",text:"Keep the late-shift cue, shrink each sketch to one outline, and compare the next week honestly.",feedback:"A smaller sketch could help if size were the barrier. Her existing minimum worked at other openings. First test a more available cue rather than changing the scope that already fit."},{id:"adjust-week",text:"Keep the one-object minimum, change the late-shift cue, and preserve all five opportunity records.",feedback:"This responds to the pattern while keeping the history honest. Dana can test another feasible cue. The three sketches count as output, not proof of a finished habit."},{id:"compensate-output",text:"Keep the late-shift cue and draw extra objects on free days to recover the missed output.",feedback:"Extra drawing may serve her goal if she chooses it, but it leaves the known cue conflict untouched. Fix the late-shift opportunity before adding compensatory load."}],bestOptionId:"adjust-week"}},carry:{takeaway:"Use the record to build the next week, including rest and safe pauses.",followUp:{questionId:"turning-day-6-return",question:"Did your chosen adjustment make the next opportunity workable?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"The habit number was modeled",paragraphs:["Lally and colleagues observed 96 volunteers for 84 days [T06]. Of those, 82 supplied adequate data, 62 had fitted curves, and 39 had good fits. Within those 39 curves, the estimated time to 95% of each person’s automaticity asymptote ranged from 18 to 254 days, with a median of 66. The 254-day endpoint was a model estimate extending beyond observation, not an observed finish.","The study relied on self-reports of everyday health behaviors and had no randomized control. One missed opportunity did not materially disrupt the examined process. That finding does not establish a threshold where two misses destroy a habit or make consecutive pauses a character failure.","This course’s week is a feasibility trial. Your drawing, learning, care, or recovery action may differ from the studied behaviors. Use actual opportunities and output to judge fit, without treating a streak as a validated transformation measure."]},{heading:"Consolidate the experiment you already have",paragraphs:["A 2024 review covered 20 health-behavior habit studies with 2,601 participants [T07]. Only four studies supplied formation-time estimates, and eleven studies had high bias risk. Different definitions and methods limit a single timetable. Pre–post changes in habit strength do not establish a controlled treatment effect or tell you when your chosen behavior will become automatic.","Progress-monitoring interventions improved goal attainment on average across 138 randomized studies [T05]. Here, use your existing records instead of adding another ritual. Count the opportunities you actually planned, attempts you reported, and useful units produced separately. A missing report stays unknown until you say what happened.","Choose whether the experiment still serves your direction. Repeat a workable unit, change one observed problem, seek support, rest, or stop. Saving one next opportunity books its next-day ODA return. A weekly comparison is an optional private calendar choice, not a second booking here. Learning completion is separate from carrying out the plan."]}],sourceIds:["T06","T07","T05"]}}],D=[{id:"1676475382103-54041209cf6c",alt:"Woman writing notes in a notebook beside a coffee cup"},{id:"1740815897057-a93a8cf98a70",alt:"Woman walking along a tree-lined path in a park"},{id:"1758854486305-eb7621f1e2e4",alt:"Person working at a table beside a large arched window"},{id:"1756312177615-e153c9db507d",alt:"Woman talking on the phone in a kitchen"},{id:"1768219565623-501f93ae384b",alt:"Desk lit by a lamp in the evening"},{id:"1529651737248-dad5e287768e",alt:"Pen resting on a planner calendar"}],d=[0,1,1,1,1,1],C={id:"turning-day",title:"Still waiting for Monday? Make one real start",subtitle:"Six lessons. Try one useful change, learn what blocks it, and build a week that fits.",description:"Take one useful step toward a life direction you choose. Carry the same experiment through six lessons: a first act, an obstacle response, a precise record, a tested setup, an honest review, and a workable next week.",scope:"Personal growth training for adults. It is not therapy, diagnosis or treatment, and it does not promise that your life will change in a single day. Do not stop any treatment or medication without talking to your doctor. If you are dealing with intense anxiety, low mood or distress that makes daily life hard, please see a health professional; if you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"A tested or paused change, a factual record, and a feasible next date.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Sunbeams falling across a path between trees"},lessons:l.map((e,t)=>{const a=e.judgment.primary,n=a.options.find(i=>i.id===a.bestOptionId),c=a.options.filter(i=>i.id!==a.bestOptionId);return c.splice(d[t],0,n),{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,practice:[...e.move.instructions,"Return here and record what actually happened."].slice(0,3),reflection:e.direction.reason.label,question:`${a.scenario} ${a.question}`,options:c.map(i=>i.text),correct:d[t],feedback:n.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:e.idea.example,photo:D[t]}})},J=Object.freeze(Object.defineProperty({__proto__:null,COURSE:C,SOURCES:W,TURNING_DAY_LESSONS_V2:l},Symbol.toStringTag,{value:"Module"})),P=[{id:"P01",title:"Steel · 2007 · Correlates and theory of procrastination",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"691 correlations from 216 works linked procrastination with task aversiveness, lower self-control, and lower self-efficacy. Work intention r = -0.03, with an interval spanning zero.",limitation:"Predominantly student, correlational evidence. These are not causes or individual diagnoses; older prevalence estimates are not current representative rates."},{id:"P02",title:"Sirois & Pychyl · 2013 · Short-term mood regulation",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"A theoretical account describes escaping unpleasant task feelings in the present at a cost to the future self.",limitation:"Narrative review with no new pooled effect. It does not explain every delay or establish that naming a feeling changes behavior."},{id:"P03",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Across 94 independent tests, specific if-then plans improved goal attainment on average. Historical standardized effect d = 0.65.",limitation:"Varied older studies, not a 65 percent success gain or procrastination-specific effect. ODA's short task exercise was not tested."},{id:"P04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with planning",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"21 articles and 24 effects showed a small-to-medium average goal-attainment benefit from mental contrasting with if-then plans.",limitation:"Heterogeneity and publication-bias signals limit the magnitude. The brief ODA adaptation is untested; infeasible goals may need disengagement."},{id:"P05",title:"Rozental et al. · 2018 · Controlled procrastination interventions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2018.01588/full",type:"research",finding:"12 studies with 718 participants found a modest average reduction in self-reported procrastination against inactive controls.",limitation:"Mostly students, varied methods, quality concerns, and few studies per treatment. Tentative findings do not establish ODA efficacy or a universal treatment ranking."},{id:"P07",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 first-year students assessed before two midterms showed an association between more self-forgiveness and less later exam procrastination.",limitation:"One observational course cohort. No causal script effect or completed repair was established; initial recruitment and attrition figures remain unverified."},{id:"P08",title:"Han & Kim · 2023 · Self-compassion intervention review",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"Across 56 randomized trials, self-compassion interventions showed qualified small-to-medium immediate benefits on distress measures.",limitation:"High overall bias risk, heterogeneous programs, and limited active comparisons. No evidence here that a single sentence treats anxiety or reduces procrastination."},{id:"P09",title:"Zhou et al. · 2026 · Planning and willingness to initiate",url:"https://pubmed.ncbi.nlm.nih.gov/41601124/",type:"research",finding:"A randomized study of 81 undergraduates reported lower task aversiveness and greater willingness to act with MCII versus positive thinking.",limitation:"One private Chinese university and short follow-up. The abstract does not verify objective completion, daily-start percentages, attrition, or preregistration status."},{id:"P10",title:"Oettingen et al. · 2015 · Time-management planning procedure",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"An academic MCII exercise combined outcome, obstacle, response, time/location, rehearsal, and a weekly calendar. Intended activity hours were measured.",limitation:"Study 1 randomized 84 German undergraduates. Scheduling was the outcome, not completed work; the adult ODA task adaptation changes the procedure."},{id:"P11",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 students compared self-chosen breaks with 24/6 and 12/3 schedules. Fixed schedules had subjective benefits; no significant task-completion difference was reported.",limitation:"One small self-study day; abstract-only access. Nonsignificance does not prove equal output, lasting procrastination reduction, or optimal 25/5 timing."},{id:"P12",title:"Albulescu et al. · 2022 · Micro-breaks review",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"Short breaks showed clearer average benefits for fatigue and vigor than for overall performance across 22 samples.",limitation:"Heterogeneous tasks and break activities. No optimal 25/5 schedule or reliable demanding-task performance boost was established."},{id:"P13",title:"Harkin et al. · 2016 · Progress monitoring meta-analysis",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Monitoring interventions improved goal attainment on average across 138 randomized studies.",limitation:"Varied goals and methods. Recording/reporting moderators do not prove each format causally; public sharing and a two-minute weekly schedule are not required."},{id:"P15",title:"Psychological Science · 2026 · Deadline-paper retraction",url:"https://journals.sagepub.com/doi/full/10.1177/09567976261488042",type:"guidance",finding:"The September 2 notice retracts Ariely and Wertenbroch's 2002 deadline paper after concerns about data reliability and authenticity.",limitation:"Retracted results cannot support a technique. The notice does not establish that every personal checkpoint or deadline is ineffective."},{id:"procrastination-pomodoro",title:"Cirillo · Pomodoro Technique provenance",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"The developer's account describes a timer routine commonly taught with 25-minute work blocks and short breaks.",limitation:"Practitioner provenance, not independent efficacy evidence. The exact timing and ODA routine are not established by this developer account."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Across 94 independent tests, specific if-then plans improved goal attainment on average. Historical standardized effect d = 0.65.",limitation:"Varied older studies, not a 65 percent success gain or procrastination-specific effect. ODA's short task exercise was not tested."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 first-year students assessed before two midterms showed an association between more self-forgiveness and less later exam procrastination.",limitation:"One observational course cohort. No causal script effect or completed repair was established; initial recruitment and attrition figures remain unverified."},{id:"procrastination-pomodoro-breaks",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 students compared self-chosen breaks with 24/6 and 12/3 schedules. Fixed schedules had subjective benefits; no significant task-completion difference was reported.",limitation:"One small self-study day; abstract-only access. Nonsignificance does not prove equal output, lasting procrastination reduction, or optimal 25/5 timing."},{id:"P18",title:"Breines & Chen · 2012 · Compassionate writing and repair motivation",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"In Experiment 2, compassionate writing increased reported motivation to make amends and avoid repetition in undergraduates.",limitation:"100 recruited, 91 analyzed. Completed repair, lasting change, and procrastination reduction were not measured; ODA adds a separate behavioral repair."}],h=[{schemaVersion:2,revision:2,id:"procrastination-1",courseId:"procrastination",locale:"en",title:"That delayed task is costing you",goal:"Take one useful step on a delayed task after checking whether the delay is avoidable.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"That expense report is still waiting. What will another delay cost?",reason:{id:"procrastination-1-delay-cost-reason",label:"What did your last delay cost, and was waiting necessary?",kind:"text",maxLength:160,optional:!0,suggestions:["Needed information was unavailable","Avoided the entry; work piled up","Rest or urgent care came first"]},why:{id:"procrastination-1-why",label:"What does this task serve, or what does delay cost?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Procrastination means delaying an intended action even though you expect the delay to make things worse. Rest, a higher priority, or missing resources can justify waiting. Check which situation you are in before calling yourself lazy.","One explanation is that avoiding an unpleasant task trades relief now for costs later. It is a model, not the explanation for every delay. Name the feeling or practical barrier. If a safe, useful move is available, do one unit while the discomfort is still here. Relief is optional; useful action is the test."],example:{title:"Sofia's receipt",text:"At 3 p.m., Sofia has been avoiding her expense report because two receipts are missing. She checks the missing-receipt rule, then enters one receipt she does have. The embarrassment stays. She records the entry and the unanswered question. The report remains unfinished, but she has stopped treating all of it as blocked."}},move:{invitation:"Choose an entry, sentence, or inquiry that fits your delayed task.",instructions:["Check whether waiting protects a real need.","Choose a matching example only if it fits your task."],prompts:[{id:"procrastination-1-0",label:"Which part is uncomfortable or genuinely blocked?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Enter one receipt in my report","Write one useful task sentence","Ask about one rule blocking my task"],minimum:["Enter one available receipt","Write one usable sentence","Send one specific rule question"],cue:["After my next work break","After I clear the dinner plate","When an unclear rule stops my task"],place:["At my work desk","At the kitchen table","In the relevant safe message thread"],minutes:[2,5,1],fallback:["Use an available receipt first","Draft a rough sentence; flag uncertainty","Ask another available information contact if needed"],observation:["What I actually entered","The sentence I wrote; what remains unclear","The rule question sent and any reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Enter one receipt in my report",minimum:"Enter one available receipt",cue:"After my next work break",place:"At my work desk",fallback:"Use an available receipt first",observation:"What I actually entered",minutes:2},{action:"Write one useful task sentence",minimum:"Write one usable sentence",cue:"After I clear the dinner plate",place:"At the kitchen table",fallback:"Draft a rough sentence; flag uncertainty",observation:"The sentence I wrote; what remains unclear",minutes:2},{action:"Ask about one rule blocking my task",minimum:"Send one specific rule question",cue:"When an unclear rule stops my task",place:"In the relevant safe message thread",fallback:"Ask another available information contact if needed",observation:"The rule question sent and any reply",minutes:2,kind:"support"}]},suggested:{action:"Enter one receipt in my report",minimum:"Enter one available receipt",minutes:2,cueHint:"After my next work break",placeHint:"At my work desk",obstacleHint:"Missing information or an urge to avoid",fallbackHint:"Use an available receipt first",observationHint:"What I actually entered",requiresChoice:!0},stopRule:"Do not delay urgent health, safety, or contractual obligations as an experiment.",accessibleAlternative:"Use assistive tools, ask for information, or choose support when the task is blocked."},result:{question:"Did you do your chosen useful unit?",observationPrompt:"What did you do, and what remained blocked?"},judgment:{primary:{id:"procrastination-1-decision",scenario:"Sofia has two free minutes and the report template. Two receipts are missing, but the policy allows available entries.",question:"Which move addresses the delay?",options:[{id:"procrastination-1-sort",text:"Sort every receipt into date order so the later report session will be easier.",feedback:"Sorting could help later. Here, the available entries can already be made. Enter one now and identify the missing-receipt rule without waiting for complete organization."},{id:"procrastination-1-enter",text:"Check the missing-receipt rule, then enter one available receipt while the embarrassment remains.",feedback:"This addresses uncertainty and produces task output in the available window. The remaining embarrassment does not cancel the entry. Record what changed and what still needs information."},{id:"procrastination-1-wait",text:"Choose a longer session tomorrow so she can finish the report in one sitting.",feedback:"A longer session may be needed for completion. It does not address today's available start. Use the current window for one entry, then schedule the remaining work."}],bestOptionId:"procrastination-1-enter"}},carry:{takeaway:"Name the barrier, check the need, then make one useful move.",followUp:{questionId:"procrastination-1-return",question:"Was discomfort the barrier, or did something practical remain unavailable?",observationPrompt:"What did you do, and what remained blocked?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Delay is not a personality verdict",paragraphs:["Steel's 2007 review collected 691 correlations from 216 works. Finding tasks unpleasant was associated with procrastination, as were lower self-control and lower confidence in doing the task. Those associations do not establish what causes your delay. Much of the research involved students. Its older prevalence estimates are not current representative rates. [P01]","The association with intention to work was negative 0.03, with an interval spanning zero. That near-zero average does not show that everybody has enough desire, time, support, or resources. Inspect your actual task instead: is there an available action, a competing responsibility, a needed accommodation, or a reason to stop? Choose the next move from those facts, not from a label about your character."]},{heading:"Relief now, cost later",paragraphs:["Sirois and Pychyl describe a mood-repair account: an unpleasant task can prompt avoidance, avoidance can offer immediate emotional relief, and the future person inherits the unfinished work. Their 2013 paper is a theoretical narrative review, not a randomized test of this loop or a treatment. It does not show that noticing a feeling outperforms practical planning. [P02]","Naming the feeling and pairing it with one task unit is an ODA adaptation. You do not have to write a confession or feel calmer afterward. Keep your experiment on an ordinary, safe task. If information is missing, a specific inquiry may be the useful action. If rest, protection, or an urgent responsibility comes first, record that choice honestly. Later lessons improve this same task plan using your actual attempts; they do not ask you to find a fresh failure each day."]}],sourceIds:["P01","P02"]}},{schemaVersion:2,revision:2,id:"procrastination-2",courseId:"procrastination",locale:"en",title:"Stop preparing. Make one useful dent.",goal:"Create one usable unit on the same task, with a stopping point that fits your time.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another session getting ready? Leave one usable piece of the task behind.",reason:{id:"procrastination-2-preparation-output-reason",label:"What did your last preparation produce, and what useful piece is still missing?",kind:"text",maxLength:160,optional:!0,suggestions:["Materials ready, no sentence written","A real missing instruction","One entry made; next still missing"]},why:{id:"procrastination-2-why",label:"What would one usable piece free you to do?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep the task you chose. Define a move with a verb and an output: enter one receipt, translate one sentence, or answer one required question. Opening a file prepares work; adding a usable unit performs it. Preparation can be necessary. Name it honestly when that is your actual move.","A specific plan links an available start to a chosen behavior. Research supports that general strategy, not a magic two-minute dose. Choose a size that fits your window and stop there if needed. Starting may leave the task unpleasant. Record the output rather than requiring a better mood."],example:{title:"Sofia's next entry",text:"After Tuesday's coffee break, Sofia has five minutes for the same report. She considers redesigning her receipt folders, then enters one more receipt instead. A category is unclear, so she flags it for a question. She stops at her chosen limit. Two entries now exist; the report still needs work."}},move:{invitation:"Keep your saved task and unit. Make output within your available time.",instructions:["Keep the action; adjust its minimum only when you choose a different unit.","Match the fallback and output note to that unit."],prompts:[],suggestions:{action:["Enter one receipt in my report","Translate one sentence of my document","Answer one required task question"],minimum:["Enter one available receipt","Translate one rough sentence","Write one usable answer"],cue:["After my next work break","At my next reserved task slot","After I clear the dinner plate"],place:["At my work desk","At my accessible work surface","At the kitchen table"],minutes:[2,5,10],fallback:["Leave folders unchanged; enter the next receipt","Flag one uncertain term; finish the sentence","Write the known part; ask what’s missing"],observation:["The entry made; any unclear category","The translated sentence and uncertain term","The answer written and missing detail"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Enter one receipt in my report",minimum:"Enter one available receipt",cue:"After my next work break",place:"At my work desk",fallback:"Leave folders unchanged; enter the next receipt",observation:"The entry made; any unclear category",minutes:2},{action:"Translate one sentence of my document",minimum:"Translate one rough sentence",cue:"At my next reserved task slot",place:"At my accessible work surface",fallback:"Flag one uncertain term; finish the sentence",observation:"The translated sentence and uncertain term",minutes:2},{action:"Answer one required task question",minimum:"Write one usable answer",cue:"After I clear the dinner plate",place:"At the kitchen table",fallback:"Write the known part; ask what’s missing",observation:"The answer written and missing detail",minutes:2}]},suggested:{action:"Enter one receipt in my report",minimum:"Enter one available receipt",minutes:2,cueHint:"After my next work break",placeHint:"At my work desk",obstacleHint:"I keep improving setup instead of producing",fallbackHint:"Leave folders unchanged; enter the next receipt",observationHint:"The entry made; any unclear category"},stopRule:"Stop for urgent responsibilities or an unsafe task. Keep required contact available.",accessibleAlternative:"Dictate, type, use assistive tools, or request a specific missing resource."},result:{question:"Did you produce your chosen usable unit?",observationPrompt:"What output exists now, and what was preparation?"},judgment:{primary:{id:"procrastination-2-decision",scenario:"Kevin has two minutes before an appointment. His contract file is ready, and he knows which sentence starts section one.",question:"Which start uses the available window?",options:[{id:"procrastination-2-timer",text:"Compare two timer settings and choose one that could support the whole translation.",feedback:"A timer can help organize a later session, but comparing settings produces no translation here. The file and sentence are ready. Use this window for one rough translated sentence."},{id:"procrastination-2-outline",text:"Outline the full translation sequence so the remaining contract feels less confusing later.",feedback:"An outline may matter when the route is unclear. Kevin already knows the next sentence. Planning the whole sequence would replace an available output with more preparation."},{id:"procrastination-2-unit",text:"Translate the first sentence, mark one uncertain term, and stop for his appointment.",feedback:"This makes a usable draft and names the uncertainty without pretending the contract is finished. He can stop on time and bring the marked term to the next session."}],bestOptionId:"procrastination-2-unit"}},carry:{takeaway:"A small start counts as task progress when it contains usable work.",followUp:{questionId:"procrastination-2-return",question:"Did your minimum produce useful work, or did preparation take its place?",observationPrompt:"What output exists now, and what was preparation?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"A cue is useful; two minutes is a choice",paragraphs:["Gollwitzer and Sheeran's 2006 meta-analysis combined 94 independent tests of if-then plans. These plans specify a recognizable situation and a response selected in advance. Goal attainment improved on average across varied settings. The historical standardized effect of 0.65 is not a 65 percent gain in success and does not predict your result. [P03]","This lesson borrows the cue-to-action structure for an ordinary task. Its short duration and one-unit minimum are design choices, not an optimized research dose. A unit must still serve the task. Reading an instruction can be preparation when writing is the goal; a sentence drafted is writing. Either can be appropriate, but keep the labels distinct. Stop at the time you actually have. You can judge whether to expand later from output, access, and obligations rather than from whether the start felt easy."]},{heading:"Timed blocks are optional",paragraphs:["Biwer and colleagues compared self-chosen breaks with 24-minute study blocks followed by six-minute breaks and 12-minute blocks followed by three-minute breaks. The 87 students studied during one self-study day. Fixed schedules had subjective benefits such as less fatigue and distraction. No statistically significant task-completion difference was reported; this is not proof of equal output. [P11]","A broader review of breaks lasting no more than ten minutes found clearer benefits for fatigue and vigor than for overall performance. It does not establish an optimal 25/5 schedule. [P12] If you choose a timer, use an interval that fits your circumstances and compare actual work with fatigue. A timer running is not the work itself. Keep urgent and accessibility communication available, and take needed breaks. You do not need a special timer, purchase, or the full Pomodoro routine to try this lesson."]}],sourceIds:["P03","P11","P12"]}},{schemaVersion:2,revision:2,id:"procrastination-3",courseId:"procrastination",locale:"en",title:"Catch the moment you leave the task",goal:"Test one obstacle response on your existing task and record whether it was needed.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your phone wins after the file opens? Plan for that exact moment.",reason:{id:"procrastination-3-switch-cost-reason",label:"What did switching away give you last time, and what did it cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Needed contact interrupted the task","Quick relief; sentence stayed unwritten","Missing detail needed an inquiry"]},why:{id:"procrastination-3-why",label:"What would staying with this task protect?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Use your last task record. Locate the moment work became something else: reaching for your phone after opening the report, or stopping at an unclear entry. A response tied to that moment is more testable than “try harder.” Connect it to the same useful unit you chose before.","Research on pairing a desired outcome with an obstacle and an if-then response shows modest average benefits. It does not promise execution. Match the response to the barrier. Distraction may need a changed setup; missing information needs an inquiry. Care, illness, and unsafe work need accommodation or support."],example:{title:"Sofia's phone cue",text:"At Wednesday's report slot, Sofia opens the file and reaches for her phone. Her plan says to put it face down and enter one receipt first. She does that, then answers a necessary message. She records one entry and that the obstacle appeared. The phone still distracted her later in the session."}},move:{invitation:"Keep your saved task and minimum. Test the response to your observed barrier.",instructions:["Edit If blocked to answer the barrier you actually saw.","No record yet? Choose one recognizable switching or missing-information moment."],prompts:[],suggestions:{action:["Enter one receipt before checking messages","Write one sentence before switching tabs","Resolve one missing detail with a question"],minimum:["Enter one available receipt","Write one usable sentence","Send one specific question"],cue:["When I reach for my phone","When I reach for another tab","When an unclear entry stops me"],place:["At my work desk","At my accessible work surface","In the relevant safe message thread"],minutes:[2,5,1],fallback:["Put phone face down; keep urgent contact","Leave extra tabs closed; draft the sentence","Send the question through another available channel"],observation:["Obstacle appearance, response used, and entry made","Switching cue, response used, and sentence written","The unclear detail and question actually sent"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Enter one receipt before checking messages",minimum:"Enter one available receipt",cue:"When I reach for my phone",place:"At my work desk",fallback:"Put phone face down; keep urgent contact",observation:"Obstacle appearance, response used, and entry made",minutes:2},{action:"Write one sentence before switching tabs",minimum:"Write one usable sentence",cue:"When I reach for another tab",place:"At my accessible work surface",fallback:"Leave extra tabs closed; draft the sentence",observation:"Switching cue, response used, and sentence written",minutes:2},{action:"Resolve one missing detail with a question",minimum:"Send one specific question",cue:"When an unclear entry stops me",place:"In the relevant safe message thread",fallback:"Send the question through another available channel",observation:"The unclear detail and question actually sent",minutes:2}]},suggested:{action:"Enter one receipt before checking messages",minimum:"Enter one available receipt",minutes:2,cueHint:"When I reach for my phone",placeHint:"At my work desk",obstacleHint:"I reach for nonurgent messages during work",fallbackHint:"Put phone face down; keep urgent contact",observationHint:"Obstacle appearance, response used, and entry made"},stopRule:"Keep urgent or accessibility contact available. Choose support for unsafe or inaccessible conditions.",accessibleAlternative:"Use an accessible reminder, ask for a resource, or rehearse as labeled preparation."},result:{question:"Did you use the response and do your minimum?",observationPrompt:"Did the obstacle appear, and what did you actually do?"},judgment:{primary:{id:"procrastination-3-decision",scenario:"Grace reaches for her phone after opening her thesis document. She has the first paper and a rough-sentence minimum. No urgent contact is expected.",question:"Which response fits this obstacle?",options:[{id:"procrastination-3-response",text:"Put the phone aside, write one rough sentence about the paper, then check needed messages.",feedback:"This targets the observed moment with the existing useful minimum. It preserves needed contact afterward. Record whether she caught the cue and what sentence she actually produced."},{id:"procrastination-3-later",text:"Schedule a longer weekend session so a distraction today will matter less to the chapter.",feedback:"More weekend time could help overall, but it leaves the present switching cue unchanged. Test a feasible response at this moment before adding a larger session."},{id:"procrastination-3-inspire",text:"Read the thesis goal again and picture the finished chapter before deciding what to write.",feedback:"Recalling the goal can give direction. Grace also needs a response to the phone cue and an actual sentence. Reflection alone would not test that response today."}],bestOptionId:"procrastination-3-response"}},carry:{takeaway:"Give the observed obstacle a feasible response, then test it against useful output.",followUp:{questionId:"procrastination-3-return",question:"Did you notice the obstacle in time, and was your response available?",observationPrompt:"Did the obstacle appear, and what did you actually do?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"What obstacle planning actually adds",paragraphs:["Mental contrasting with implementation intentions pairs a desired outcome with an obstacle and a planned response. Wang and colleagues pooled 21 articles with 24 independent effects and found a small-to-medium average benefit for goal attainment. Results varied and showed publication-bias signals. The approach can also help someone disengage from an infeasible goal; it is not a demand to overcome every barrier. [P04]","Oettingen and colleagues' 2015 academic exercise asked students to consider an important concern, imagine its outcome and obstacle, choose a response, include time and location, rehearse it, and make a weekly calendar. Intended activity hours were the outcome, not completed work. [P10] Your brief adult task plan changes that procedure. The record here asks about actual output. Do not treat imagining, rehearsing, planning, and doing as interchangeable forms of progress, or assume one plan has been shown better than five."]},{heading:"Willingness is not a verified start",paragraphs:["Zhou and colleagues’ recent randomized study involved 81 undergraduates at one private Chinese university. Its accessible abstract reports lower task aversiveness and greater willingness to act after the planning strategy, compared with positive thinking. The trial measured willingness to begin, not verified task starts or completion. Do not treat willingness as execution. [P09]","Positive thoughts are not automatically useless, and an obstacle need not be an inner flaw. This experiment starts with your reported switching moment or practical barrier. A useful response is one you can recognize and carry out in the actual setting. If the obstacle never appears, its response remains untested rather than failed. If it appears and the response is unavailable, change the setup, size, or support. Keep the same task and direction while changing the condition your record identified."]}],sourceIds:["P04","P10","P09"]}},{schemaVersion:2,revision:2,id:"procrastination-4",courseId:"procrastination",locale:"en",title:"Missed it? Repair what you can.",goal:"Choose one feasible repair, task return, or support step without promising what you cannot deliver.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Deadline passed? An honest update tells the waiting person what happens next.",reason:{id:"procrastination-4-owed-repair-reason",label:"What is yours to repair, and what would another silence or promise cost?",kind:"text",maxLength:160,optional:!0,suggestions:["An update is owed","No update owed; return to work","Unsafe contact; seek support"]},why:{id:"procrastination-4-why",label:"What responsibility or boundary needs attention now?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep your task record honest. If someone is waiting, check whether an update or repair is owed. Name what’s unfinished and what you can deliver. Kindness does not change the deadline, erase the impact, or justify promises beyond your capacity.","In one experiment, compassionate writing increased reported motivation to repair a mistake. Completed repair was not measured. Use that distinction here: a fair sentence is preparation; sending an update or doing a task unit is action. Choose one act as your minimum and record any additional acts separately. Forgiveness is not a required feeling."],example:{title:"Sofia's honest update",text:"Thursday morning, Sofia’s report is overdue. She writes, “I delayed it; I can face the part I owe.” She chooses one repair: send finance an honest update with her missing-receipt question and remaining scope. Finance has not replied. She records the sent update. Receipt entry remains a separate next action, not a completed repair."}},move:{invitation:"Keep your task context. Choose one owed repair, useful return, or safe support step.",instructions:["Check what is actually yours to repair before choosing an act.","Make one act the minimum; log extra acts separately."],prompts:[],suggestions:{action:["Send a feasible revised task update","Write one usable unit on my task","Request help breaking down my delayed task"],minimum:["Send one honest scope and timing update","Write one usable task sentence","Send one task-breakdown request"],cue:["At my next safe work pause","At my next reserved task slot","At my next agreed support check-in"],place:["In the appropriate work message thread","At my accessible work surface","In a safe support message thread"],minutes:[5,2,10],fallback:["Send current facts without promising uncertain timing","Draft the known part; flag one missing detail","Ask another trusted person if unavailable"],observation:["The update sent and any reply","The task sentence I actually wrote","The task-breakdown request sent and any reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Send a feasible revised task update",minimum:"Send one honest scope and timing update",cue:"At my next safe work pause",place:"In the appropriate work message thread",fallback:"Send current facts without promising uncertain timing",observation:"The update sent and any reply",minutes:5},{action:"Write one usable unit on my task",minimum:"Write one usable task sentence",cue:"At my next reserved task slot",place:"At my accessible work surface",fallback:"Draft the known part; flag one missing detail",observation:"The task sentence I actually wrote",minutes:2},{action:"Request help breaking down my delayed task",minimum:"Send one task-breakdown request",cue:"At my next agreed support check-in",place:"In a safe support message thread",fallback:"Ask another trusted person if unavailable",observation:"The task-breakdown request sent and any reply",minutes:2,kind:"support"}]},suggested:{action:"Send a feasible revised task update",minimum:"Send one honest scope and timing update",minutes:5,cueHint:"At my next safe work pause",placeHint:"In the appropriate work message thread",obstacleHint:"I am tempted to stay silent or overpromise",fallbackHint:"Send current facts without promising uncertain timing",observationHint:"The update sent and any reply",requiresChoice:!0},stopRule:"Choose an ordinary lapse. Do not blame yourself for someone else’s harm. If contact is unsafe, pause and seek support.",accessibleAlternative:"Use a safe message, assisted communication, or support instead of unsafe contact."},result:{question:"Did you carry out the one repair or return you chose?",observationPrompt:"What one act happened, and what remains unfinished?"},judgment:{primary:{id:"procrastination-4-capacity-repair-decision",scenario:"Daniel missed a promised draft. The team needs an update. He can deliver one section today, but the whole draft needs more time.",question:"Which response fits his current capacity?",options:[{id:"procrastination-4-finish",text:"Finish the available section first and wait to update the team until the draft looks reassuring.",feedback:"Producing the section matters, but the team is already waiting and needs current information. Send an honest scope and timing update now, then make the section."},{id:"procrastination-4-revise-first",text:"Request a revised whole-draft deadline now and postpone the available section until that schedule is agreed.",feedback:"Renegotiating may be necessary, but the team can receive current information and a useful section today. Propose realistic remaining timing while delivering the available part, unless their needs require waiting."},{id:"procrastination-4-repair",text:"Acknowledge the missed promise, propose feasible scope and timing, then produce the section he can deliver.",feedback:"This faces the impact without adding an impossible promise. The update and section are concrete acts. Agreement is still the team's choice, so record their response honestly."}],bestOptionId:"procrastination-4-repair"}},carry:{takeaway:"A fair sentence supports repair. The repair is the behavior you actually carry out.",followUp:{questionId:"procrastination-4-chosen-act-return",question:"Did your chosen repair, return, or support step fit your actual capacity?",observationPrompt:"What did you do, and what still needs a response?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Kindness and repair are different outcomes",paragraphs:["Breines and Chen's 2012 experiment asked undergraduates to describe a recent action they considered wrong and write to themselves with kindness and understanding. Of 100 recruits, 91 were analyzed. The compassionate-writing group reported more motivation to make amends and avoid repetition than the comparison groups. The experiment did not establish that participants completed apologies or repairs, or reduced procrastination over time. [P18]","This lesson uses a shorter fair sentence for an ordinary delayed task and adds a separately chosen behavioral step. That is an ODA adaptation, not the studied exercise. You can choose a safe update, correct an error, produce an agreed unit, request accommodation, or stop an unsuitable plan. The factual record names which act happened. Keep responsibility proportionate to what you actually did. You do not owe contact, reconciliation, or an apology for being harmed."]},{heading:"What the forgiveness evidence cannot promise",paragraphs:["Wohl, Pychyl, and Bennett studied 119 first-year students in one psychology course. Students were assessed immediately before each of two midterm exams. Greater self-forgiveness was associated with less procrastination before the second exam. This observational association does not prove forgiveness caused the change or establish that a particular script helps someone return to a task. [P07]","Self-forgiveness and self-compassion are related but distinct. Han and Kim's review of 56 randomized self-compassion trials found qualified distress benefits, with high overall risk of bias. It does not validate a single sentence as treatment or show that it makes your next task start easier. [P08] You can try a fair description while still feeling regret or frustration. The useful test remains whether your next commitment fits reality and whether a repair or return actually occurs. No emotional transformation is required."]}],sourceIds:["P18","P07","P08"]}},{schemaVersion:2,revision:2,id:"procrastination-5",courseId:"procrastination",locale:"en",title:"Starts keep falling through? Fix next week’s slot.",goal:"Keep one useful task plan, change one observed barrier, and schedule the next feasible attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Some starts worked; others did not? Use your records to choose next week's plan.",reason:{id:"procrastination-5-reason",label:"Does this task still deserve its cost this week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep a commitment moving","Change a plan that keeps failing","Get help with a recurring problem"]},why:{id:"procrastination-5-why",label:"Does this task still deserve its cost this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Use your saved task, direction, minimum, and attempts. Checking progress can help people reach goals on average. Distinguish a plan from an attempt, and an attempt from usable work. Blank history means unknown, not failure or success.","Keep what helped and change one condition that blocked you. A personal checkpoint can remain an experiment. Changing an owed deadline requires communication and agreement. Save your next useful unit; ODA schedules its next-day return. If no helpful cue is known, choose a first feasible trial. Get support alongside practice when delay causes persistent harm."],example:{title:"Sofia's next week",text:"On Friday, Sofia reviews the same report: three receipt entries, one unanswered query, and one planned slot she did not use. Work breaks gave her access; late evenings did not. She books Monday's next entry after her break and checks who still needs an update. The report remains unfinished. Her next plan uses the record."}},move:{invitation:"Keep your saved task and any cue that worked. Change the observed blocked condition.",instructions:["No helpful cue recorded? Name one first feasible opening.","Save the next unit; ODA schedules a return the following day."],prompts:[],suggestions:{action:["Enter one receipt in my report","Write one usable unit on my task","Request help changing my unavailable work slot"],minimum:["Enter one available receipt","Write one usable task sentence","Send one scheduling support request"],cue:["After my next available work break","At my next reserved writing slot","At my next agreed scheduling check-in"],place:["At my work desk","At my accessible work surface","In a safe support message thread"],minutes:[2,5,10],fallback:["Use tomorrow’s available work break instead","Use tomorrow’s reserved writing slot instead","Ask another trusted contact if unavailable"],observation:["The entry made and whether access fit","The sentence written and whether the slot fit","The scheduling support request and any reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Enter one receipt in my report",minimum:"Enter one available receipt",cue:"After my next available work break",place:"At my work desk",fallback:"Use tomorrow’s available work break instead",observation:"The entry made and whether access fit",minutes:2},{action:"Write one usable unit on my task",minimum:"Write one usable task sentence",cue:"At my next reserved writing slot",place:"At my accessible work surface",fallback:"Use tomorrow’s reserved writing slot instead",observation:"The sentence written and whether the slot fit",minutes:2},{action:"Request help changing my unavailable work slot",minimum:"Send one scheduling support request",cue:"At my next agreed scheduling check-in",place:"In a safe support message thread",fallback:"Ask another trusted contact if unavailable",observation:"The scheduling support request and any reply",minutes:2,kind:"support"}]},suggested:{action:"Enter one receipt in my report",minimum:"Enter one available receipt",minutes:2,cueHint:"After my next available work break",placeHint:"At my work desk",obstacleHint:"My proposed work slot may be unavailable",fallbackHint:"Use tomorrow’s available work break instead",observationHint:"The entry made and whether access fit"},stopRule:"Seek support now if delay harms your life. Urgent duties need appropriate action.",accessibleAlternative:"Choose assisted work, a support request, a feasible boundary, or a pause."},result:{question:"Did you carry out your next chosen unit?",observationPrompt:"What useful output or support action actually happened?"},judgment:{primary:{id:"procrastination-5-decision",scenario:"Nadia produced essay sentences on Tuesday, missed an unavailable Thursday slot, and found an agreed friend review useful. The application deadline remains fixed.",question:"What should next week preserve or change?",options:[{id:"procrastination-5-more",text:"Add daily personal checkpoints so every planned start has a nearer consequence and a clear target.",feedback:"More checkpoints could add structure, but the record identifies an unavailable Thursday slot. Preserve the useful review and change that slot before adding pressure to every day."},{id:"procrastination-5-adjust",text:"Keep the friend review, change Thursday's cue, and compare actual starts and essay output next week.",feedback:"This uses the observed fit while keeping the real deadline visible. The next record should show both attempts and useful writing. Communicate with others if any agreed commitment changes."},{id:"procrastination-5-remove",text:"Remove personal checkpoints and use only the final deadline while the evidence for deadlines remains uncertain.",feedback:"Uncertain general evidence does not erase Nadia's observed helpful review. Keep it as a chosen experiment rather than a proven cure, and address the schedule barrier directly."}],bestOptionId:"procrastination-5-adjust"}},carry:{takeaway:"Keep the useful condition, change the blocked one, and bring back honest output.",followUp:{questionId:"procrastination-5-work-or-support-return",question:"Did your next work or support step happen at the chosen opening?",observationPrompt:"What work or support request happened, and did the cue fit?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Use a record, not a tool collection",paragraphs:["Harkin and colleagues combined 138 randomized studies of progress monitoring across diverse goals. Monitoring interventions improved goal attainment on average. Recording and reporting were associated with larger effects in moderator analyses, but those associations do not prove every sharing format causes improvement. Public disclosure is not required. This plan books one next-day ODA return. A weekly comparison is optional in your private calendar; it is not a second saved appointment here. [P13]","Use your own dated attempts to answer a narrow question: did the chosen cue, minimum, and response allow useful work? One completed unit does not mean the whole task is complete. An unencountered obstacle leaves its response untested. Keep gaps in the history visible. For next week, retain the condition that fit and change the barrier your record identifies. If the task no longer serves your responsibilities or direction, consider renegotiating, pausing, or stopping rather than adding another technique."]},{heading:"Support and deadlines need honest limits",paragraphs:["Rozental and colleagues' controlled review included 12 studies and 718 participants, largely students. Psychological interventions reduced self-reported procrastination on average against inactive controls, but study quality, varied methods, and few studies per treatment make the findings tentative. Its results do not establish that ODA works or that every format requires professional delivery. Seek assessment or support when the impact warrants it, alongside this experiment. [P05]","The classic Ariely and Wertenbroch self-imposed-deadline paper was retracted in September 2026 after concerns about data reliability and authenticity. Its results cannot validate a technique. The notice does not establish that every checkpoint fails. [P15] A personal reminder can remain a voluntary experiment. An employer, client, or academic deadline is an actual commitment: communicate and seek agreement before changing it. Do not substitute self-imposed pressure for urgent health, safety, legal, or contractual action."]}],sourceIds:["P13","P05","P15"]}}],O={id:"procrastination",title:"Still putting it off? Make one useful dent.",subtitle:"One delayed task. Five lessons to start useful work, face the barrier, and return with an honest plan.",description:"Stop turning a delayed task into a verdict about yourself. Try useful work, record the barrier, and repair or revise what your week needs.",scope:"Skills training for everyday procrastination; it is not therapy. If procrastination comes with intense anxiety, long-lasting low mood or attention difficulties and clearly affects your life, you can get support from a professional.",outcome:"A useful task unit, a barrier response, and a feasible next date.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Woman working on a laptop at a desk surrounded by plants"},lessons:[{id:"procrastination-1",schemaVersion:2,title:"That delayed task is costing you",minutes:6,goal:"Take one useful step on a delayed task after checking whether the delay is avoidable.",reading:["Procrastination means delaying an intended action even though you expect the delay to make things worse. Rest, a higher priority, or missing resources can justify waiting. Check which situation you are in before calling yourself lazy.","One explanation is that avoiding an unpleasant task trades relief now for costs later. It is a model, not the explanation for every delay. Name the feeling or practical barrier. If a safe, useful move is available, do one unit while the discomfort is still here. Relief is optional; useful action is the test."],practice:["Check whether waiting protects a real need.","Choose a matching example only if it fits your task.","Return here and record what actually happened."],reflection:"What did your last delay cost, and was waiting necessary?",question:"Sofia has two free minutes and the report template. Two receipts are missing, but the policy allows available entries. Which move addresses the delay?",options:["Sort every receipt into date order so the later report session will be easier.","Check the missing-receipt rule, then enter one available receipt while the embarrassment remains.","Choose a longer session tomorrow so she can finish the report in one sitting."],correct:1,feedback:"This addresses uncertainty and produces task output in the available window. The remaining embarrassment does not cancel the entry. Record what changed and what still needs information.",takeaway:"Name the barrier, check the need, then make one useful move.",sources:["P01","P02"],deeper:[{heading:"Delay is not a personality verdict",paragraphs:["Steel's 2007 review collected 691 correlations from 216 works. Finding tasks unpleasant was associated with procrastination, as were lower self-control and lower confidence in doing the task. Those associations do not establish what causes your delay. Much of the research involved students. Its older prevalence estimates are not current representative rates. [P01]","The association with intention to work was negative 0.03, with an interval spanning zero. That near-zero average does not show that everybody has enough desire, time, support, or resources. Inspect your actual task instead: is there an available action, a competing responsibility, a needed accommodation, or a reason to stop? Choose the next move from those facts, not from a label about your character."]},{heading:"Relief now, cost later",paragraphs:["Sirois and Pychyl describe a mood-repair account: an unpleasant task can prompt avoidance, avoidance can offer immediate emotional relief, and the future person inherits the unfinished work. Their 2013 paper is a theoretical narrative review, not a randomized test of this loop or a treatment. It does not show that noticing a feeling outperforms practical planning. [P02]","Naming the feeling and pairing it with one task unit is an ODA adaptation. You do not have to write a confession or feel calmer afterward. Keep your experiment on an ordinary, safe task. If information is missing, a specific inquiry may be the useful action. If rest, protection, or an urgent responsibility comes first, record that choice honestly. Later lessons improve this same task plan using your actual attempts; they do not ask you to find a fresh failure each day."]}],example:{title:"Sofia's receipt",text:"At 3 p.m., Sofia has been avoiding her expense report because two receipts are missing. She checks the missing-receipt rule, then enters one receipt she does have. The embarrassment stays. She records the entry and the unanswered question. The report remains unfinished, but she has stopped treating all of it as blocked."},photo:{id:"1552360708-ebcdf76845ac",alt:"Woman sitting by a window, deep in thought"}},{id:"procrastination-2",schemaVersion:2,title:"Stop preparing. Make one useful dent.",minutes:6,goal:"Create one usable unit on the same task, with a stopping point that fits your time.",reading:["Keep the task you chose. Define a move with a verb and an output: enter one receipt, translate one sentence, or answer one required question. Opening a file prepares work; adding a usable unit performs it. Preparation can be necessary. Name it honestly when that is your actual move.","A specific plan links an available start to a chosen behavior. Research supports that general strategy, not a magic two-minute dose. Choose a size that fits your window and stop there if needed. Starting may leave the task unpleasant. Record the output rather than requiring a better mood."],practice:["Keep the action; adjust its minimum only when you choose a different unit.","Match the fallback and output note to that unit.","Return here and record what actually happened."],reflection:"What did your last preparation produce, and what useful piece is still missing?",question:"Kevin has two minutes before an appointment. His contract file is ready, and he knows which sentence starts section one. Which start uses the available window?",options:["Compare two timer settings and choose one that could support the whole translation.","Outline the full translation sequence so the remaining contract feels less confusing later.","Translate the first sentence, mark one uncertain term, and stop for his appointment."],correct:2,feedback:"This makes a usable draft and names the uncertainty without pretending the contract is finished. He can stop on time and bring the marked term to the next session.",takeaway:"A small start counts as task progress when it contains usable work.",sources:["P03","P11","P12"],deeper:[{heading:"A cue is useful; two minutes is a choice",paragraphs:["Gollwitzer and Sheeran's 2006 meta-analysis combined 94 independent tests of if-then plans. These plans specify a recognizable situation and a response selected in advance. Goal attainment improved on average across varied settings. The historical standardized effect of 0.65 is not a 65 percent gain in success and does not predict your result. [P03]","This lesson borrows the cue-to-action structure for an ordinary task. Its short duration and one-unit minimum are design choices, not an optimized research dose. A unit must still serve the task. Reading an instruction can be preparation when writing is the goal; a sentence drafted is writing. Either can be appropriate, but keep the labels distinct. Stop at the time you actually have. You can judge whether to expand later from output, access, and obligations rather than from whether the start felt easy."]},{heading:"Timed blocks are optional",paragraphs:["Biwer and colleagues compared self-chosen breaks with 24-minute study blocks followed by six-minute breaks and 12-minute blocks followed by three-minute breaks. The 87 students studied during one self-study day. Fixed schedules had subjective benefits such as less fatigue and distraction. No statistically significant task-completion difference was reported; this is not proof of equal output. [P11]","A broader review of breaks lasting no more than ten minutes found clearer benefits for fatigue and vigor than for overall performance. It does not establish an optimal 25/5 schedule. [P12] If you choose a timer, use an interval that fits your circumstances and compare actual work with fatigue. A timer running is not the work itself. Keep urgent and accessibility communication available, and take needed breaks. You do not need a special timer, purchase, or the full Pomodoro routine to try this lesson."]}],example:{title:"Sofia's next entry",text:"After Tuesday's coffee break, Sofia has five minutes for the same report. She considers redesigning her receipt folders, then enters one more receipt instead. A category is unclear, so she flags it for a question. She stops at her chosen limit. Two entries now exist; the report still needs work."},photo:{id:"1448387473223-5c37445527e7",alt:"A foot stepping onto the first stair"}},{id:"procrastination-3",schemaVersion:2,title:"Catch the moment you leave the task",minutes:6,goal:"Test one obstacle response on your existing task and record whether it was needed.",reading:["Use your last task record. Locate the moment work became something else: reaching for your phone after opening the report, or stopping at an unclear entry. A response tied to that moment is more testable than “try harder.” Connect it to the same useful unit you chose before.","Research on pairing a desired outcome with an obstacle and an if-then response shows modest average benefits. It does not promise execution. Match the response to the barrier. Distraction may need a changed setup; missing information needs an inquiry. Care, illness, and unsafe work need accommodation or support."],practice:["Edit If blocked to answer the barrier you actually saw.","No record yet? Choose one recognizable switching or missing-information moment.","Return here and record what actually happened."],reflection:"What did switching away give you last time, and what did it cost?",question:"Grace reaches for her phone after opening her thesis document. She has the first paper and a rough-sentence minimum. No urgent contact is expected. Which response fits this obstacle?",options:["Put the phone aside, write one rough sentence about the paper, then check needed messages.","Schedule a longer weekend session so a distraction today will matter less to the chapter.","Read the thesis goal again and picture the finished chapter before deciding what to write."],correct:0,feedback:"This targets the observed moment with the existing useful minimum. It preserves needed contact afterward. Record whether she caught the cue and what sentence she actually produced.",takeaway:"Give the observed obstacle a feasible response, then test it against useful output.",sources:["P04","P10","P09"],deeper:[{heading:"What obstacle planning actually adds",paragraphs:["Mental contrasting with implementation intentions pairs a desired outcome with an obstacle and a planned response. Wang and colleagues pooled 21 articles with 24 independent effects and found a small-to-medium average benefit for goal attainment. Results varied and showed publication-bias signals. The approach can also help someone disengage from an infeasible goal; it is not a demand to overcome every barrier. [P04]","Oettingen and colleagues' 2015 academic exercise asked students to consider an important concern, imagine its outcome and obstacle, choose a response, include time and location, rehearse it, and make a weekly calendar. Intended activity hours were the outcome, not completed work. [P10] Your brief adult task plan changes that procedure. The record here asks about actual output. Do not treat imagining, rehearsing, planning, and doing as interchangeable forms of progress, or assume one plan has been shown better than five."]},{heading:"Willingness is not a verified start",paragraphs:["Zhou and colleagues’ recent randomized study involved 81 undergraduates at one private Chinese university. Its accessible abstract reports lower task aversiveness and greater willingness to act after the planning strategy, compared with positive thinking. The trial measured willingness to begin, not verified task starts or completion. Do not treat willingness as execution. [P09]","Positive thoughts are not automatically useless, and an obstacle need not be an inner flaw. This experiment starts with your reported switching moment or practical barrier. A useful response is one you can recognize and carry out in the actual setting. If the obstacle never appears, its response remains untested rather than failed. If it appears and the response is unavailable, change the setup, size, or support. Keep the same task and direction while changing the condition your record identified."]}],example:{title:"Sofia's phone cue",text:"At Wednesday's report slot, Sofia opens the file and reaches for her phone. Her plan says to put it face down and enter one receipt first. She does that, then answers a necessary message. She records one entry and that the obstacle appeared. The phone still distracted her later in the session."},photo:{id:"1553044020-8c90843adf96",alt:"Yellow sticky notes and a pen"}},{id:"procrastination-4",schemaVersion:2,title:"Missed it? Repair what you can.",minutes:6,goal:"Choose one feasible repair, task return, or support step without promising what you cannot deliver.",reading:["Keep your task record honest. If someone is waiting, check whether an update or repair is owed. Name what’s unfinished and what you can deliver. Kindness does not change the deadline, erase the impact, or justify promises beyond your capacity.","In one experiment, compassionate writing increased reported motivation to repair a mistake. Completed repair was not measured. Use that distinction here: a fair sentence is preparation; sending an update or doing a task unit is action. Choose one act as your minimum and record any additional acts separately. Forgiveness is not a required feeling."],practice:["Check what is actually yours to repair before choosing an act.","Make one act the minimum; log extra acts separately.","Return here and record what actually happened."],reflection:"What is yours to repair, and what would another silence or promise cost?",question:"Daniel missed a promised draft. The team needs an update. He can deliver one section today, but the whole draft needs more time. Which response fits his current capacity?",options:["Finish the available section first and wait to update the team until the draft looks reassuring.","Request a revised whole-draft deadline now and postpone the available section until that schedule is agreed.","Acknowledge the missed promise, propose feasible scope and timing, then produce the section he can deliver."],correct:2,feedback:"This faces the impact without adding an impossible promise. The update and section are concrete acts. Agreement is still the team's choice, so record their response honestly.",takeaway:"A fair sentence supports repair. The repair is the behavior you actually carry out.",sources:["P18","P07","P08"],deeper:[{heading:"Kindness and repair are different outcomes",paragraphs:["Breines and Chen's 2012 experiment asked undergraduates to describe a recent action they considered wrong and write to themselves with kindness and understanding. Of 100 recruits, 91 were analyzed. The compassionate-writing group reported more motivation to make amends and avoid repetition than the comparison groups. The experiment did not establish that participants completed apologies or repairs, or reduced procrastination over time. [P18]","This lesson uses a shorter fair sentence for an ordinary delayed task and adds a separately chosen behavioral step. That is an ODA adaptation, not the studied exercise. You can choose a safe update, correct an error, produce an agreed unit, request accommodation, or stop an unsuitable plan. The factual record names which act happened. Keep responsibility proportionate to what you actually did. You do not owe contact, reconciliation, or an apology for being harmed."]},{heading:"What the forgiveness evidence cannot promise",paragraphs:["Wohl, Pychyl, and Bennett studied 119 first-year students in one psychology course. Students were assessed immediately before each of two midterm exams. Greater self-forgiveness was associated with less procrastination before the second exam. This observational association does not prove forgiveness caused the change or establish that a particular script helps someone return to a task. [P07]","Self-forgiveness and self-compassion are related but distinct. Han and Kim's review of 56 randomized self-compassion trials found qualified distress benefits, with high overall risk of bias. It does not validate a single sentence as treatment or show that it makes your next task start easier. [P08] You can try a fair description while still feeling regret or frustration. The useful test remains whether your next commitment fits reality and whether a repair or return actually occurs. No emotional transformation is required."]}],example:{title:"Sofia's honest update",text:"Thursday morning, Sofia’s report is overdue. She writes, “I delayed it; I can face the part I owe.” She chooses one repair: send finance an honest update with her missing-receipt question and remaining scope. Finance has not replied. She records the sent update. Receipt entry remains a separate next action, not a completed repair."},photo:{id:"1778958619388-b529cc4e78e8",alt:"Young woman drinking tea by a window"}},{id:"procrastination-5",schemaVersion:2,title:"Starts keep falling through? Fix next week’s slot.",minutes:6,goal:"Keep one useful task plan, change one observed barrier, and schedule the next feasible attempt.",reading:["Use your saved task, direction, minimum, and attempts. Checking progress can help people reach goals on average. Distinguish a plan from an attempt, and an attempt from usable work. Blank history means unknown, not failure or success.","Keep what helped and change one condition that blocked you. A personal checkpoint can remain an experiment. Changing an owed deadline requires communication and agreement. Save your next useful unit; ODA schedules its next-day return. If no helpful cue is known, choose a first feasible trial. Get support alongside practice when delay causes persistent harm."],practice:["No helpful cue recorded? Name one first feasible opening.","Save the next unit; ODA schedules a return the following day.","Return here and record what actually happened."],reflection:"Does this task still deserve its cost this week?",question:"Nadia produced essay sentences on Tuesday, missed an unavailable Thursday slot, and found an agreed friend review useful. The application deadline remains fixed. What should next week preserve or change?",options:["Add daily personal checkpoints so every planned start has a nearer consequence and a clear target.","Keep the friend review, change Thursday's cue, and compare actual starts and essay output next week.","Remove personal checkpoints and use only the final deadline while the evidence for deadlines remains uncertain."],correct:1,feedback:"This uses the observed fit while keeping the real deadline visible. The next record should show both attempts and useful writing. Communicate with others if any agreed commitment changes.",takeaway:"Keep the useful condition, change the blocked one, and bring back honest output.",sources:["P13","P05","P15"],deeper:[{heading:"Use a record, not a tool collection",paragraphs:["Harkin and colleagues combined 138 randomized studies of progress monitoring across diverse goals. Monitoring interventions improved goal attainment on average. Recording and reporting were associated with larger effects in moderator analyses, but those associations do not prove every sharing format causes improvement. Public disclosure is not required. This plan books one next-day ODA return. A weekly comparison is optional in your private calendar; it is not a second saved appointment here. [P13]","Use your own dated attempts to answer a narrow question: did the chosen cue, minimum, and response allow useful work? One completed unit does not mean the whole task is complete. An unencountered obstacle leaves its response untested. Keep gaps in the history visible. For next week, retain the condition that fit and change the barrier your record identifies. If the task no longer serves your responsibilities or direction, consider renegotiating, pausing, or stopping rather than adding another technique."]},{heading:"Support and deadlines need honest limits",paragraphs:["Rozental and colleagues' controlled review included 12 studies and 718 participants, largely students. Psychological interventions reduced self-reported procrastination on average against inactive controls, but study quality, varied methods, and few studies per treatment make the findings tentative. Its results do not establish that ODA works or that every format requires professional delivery. Seek assessment or support when the impact warrants it, alongside this experiment. [P05]","The classic Ariely and Wertenbroch self-imposed-deadline paper was retracted in September 2026 after concerns about data reliability and authenticity. Its results cannot validate a technique. The notice does not establish that every checkpoint fails. [P15] A personal reminder can remain a voluntary experiment. An employer, client, or academic deadline is an actual commitment: communicate and seek agreement before changing it. Do not substitute self-imposed pressure for urgent health, safety, legal, or contractual action."]}],example:{title:"Sofia's next week",text:"On Friday, Sofia reviews the same report: three receipt entries, one unanswered query, and one planned slot she did not use. Work breaks gave her access; late evenings did not. She books Monday's next entry after her break and checks who still needs an update. The report remains unfinished. Her next plan uses the record."},photo:{id:"1506784983877-45594efa4cbe",alt:"Coffee cup resting on an open planner"}}].map((e,t)=>({...e,schemaVersion:2,v2:h[t]}))},Q=Object.freeze(Object.defineProperty({__proto__:null,COURSE:O,LESSONS_V2:h,SOURCES:P},Symbol.toStringTag,{value:"Module"})),R=[{id:"S01",title:"Trauer et al. · 2015 · CBT-I for chronic insomnia",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"Across 20 trials with 1,162 adults, face-to-face multicomponent CBT-I reduced diary sleep-onset time by 19.03 minutes and nighttime wakefulness by 26.00 minutes. Total sleep increased 7.61 minutes, with a confidence interval spanning no difference.",limitation:"Abstract access. Narrow eligibility and inactive comparisons limit transfer. These are end-of-treatment averages, not ODA predictions; an inconclusive total-sleep difference does not negate continuity benefits."},{id:"S03",title:"Furukawa et al. · 2024 · Components of CBT-I",url:"https://jamanetwork.com/journals/jamapsychiatry/fullarticle/2814164?resultClick=1",type:"research",finding:"Component network analysis of 241 trials with 31,452 adults associated stimulus control and sleep restriction with remission benefit. Sleep hygiene alone had an incremental odds ratio of 1.01 (95% CI 0.77–1.32).",limitation:"Component modeling assumes additivity and is not isolated randomization of ingredients. Relaxation’s interval crossed one, so this does not show relaxation harms sleep. ODA is not CBT-I."},{id:"S04",title:"Edinger et al. · 2021 · AASM insomnia treatment guideline",url:"https://doi.org/10.5664/jcsm.8986",type:"guidance",finding:"Recommends multicomponent CBT-I strongly for chronic insomnia and conditionally discourages sleep hygiene as the sole treatment. Some individual components have conditional recommendations.",limitation:"Publisher recommendations accessed. This does not make supportive habit education useless or permit an app to prescribe sleep restriction."},{id:"S05",title:"American College of Physicians · 2016 · Initial insomnia treatment",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Recommends CBT-I as initial treatment for adult chronic insomnia. Delivery can include individual or group care, telephone or web modules, and structured self-help. Medication decisions require discussion with a clinician.",limitation:"Official guideline summary, not a trial. A chronic-insomnia duration definition is not a waiting requirement for assessment, and every digital product is not validated CBT-I."},{id:"S06",title:"NIH/NHLBI · 2022 · Insomnia treatment",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"Describes CBT-I as a multicomponent treatment commonly over six to eight weeks, with in-person, phone, and online delivery. Stimulus control includes going to bed when sleepy and leaving if unable to sleep.",limitation:"Patient guidance, not a trial or permission for self-directed sleep restriction. Five ODA lessons do not reproduce the described treatment."},{id:"S07",title:"Watson et al. · 2015 · Adult sleep-duration consensus",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"For adults ages 18–60, recommends regularly sleeping at least seven hours. Individual need varies, and longer sleep can be appropriate during illness or recovery.",limitation:"Full consensus statement and methods accessed. This is a population recommendation, not an exact personal target. Time in bed is not the same as sleep; health associations do not establish individual causation."},{id:"S08",title:"CDC · 2024 · About sleep",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Sleep duration and quality both matter. Age-based recommendations vary. Regular sleep problems or disorder symptoms warrant care; an optional diary can record sleep, wake, naps, substances, and medications.",limitation:"Public guidance. A diary is not a prerequisite for contacting care, and meeting a duration recommendation does not rule out a sleep disorder."},{id:"S09",title:"Gardiner et al. · 2023 · Caffeine and subsequent sleep",url:"https://www.colegiomedico.cl/wp-content/uploads/2023/07/cafe-y-sueno.pdf",type:"research",finding:"Across 24 studies, caffeine impaired subsequent sleep on average. Objective total sleep was 45.3 minutes shorter (95% CI 29.0–61.5 shorter); amount and timing influenced outcomes.",limitation:"Full review accessed. This is not a prediction for one ordinary drink. Modeled cutoffs are not proven personal safety boundaries; sensitivity and habitual use vary."},{id:"S10",title:"FDA · How much caffeine is too much?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"For most adults, 400 mg daily is not generally associated with negative effects; sensitivity varies. Actual product and serving amounts differ. Gradual reduction can limit withdrawal symptoms.",limitation:"Consumer guidance, not a sleep-neutral allowance or intake target. Pregnancy, breastfeeding, medication, and condition questions require professional advice. Decaf can contain caffeine; update date was not verified."},{id:"S11",title:"NHS · 2024 · Insomnia",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Seek care if changes have not helped or sleep trouble makes daily life hard to cope with. Go to bed when sleepy and avoid driving while sleepy. Shift work, illness, and medicines can contribute.",limitation:"Three months describes persistence, not a waiting requirement. Public habit durations are suggestions, not individualized safe thresholds. This is guidance, not a diagnosis."},{id:"S12",title:"NHS · 2026 · Sleep apnea",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Breathing interruptions, gasping or choking, and excessive daytime sleepiness are reasons for medical evaluation. Symptoms can include frequent waking, loud snoring, headaches, and concentration problems.",limitation:"A symptom list does not diagnose apnea. Living alone or lacking a witness does not prevent assessment. Relaxation does not treat blocked breathing."},{id:"S13",title:"Drake et al. · 2013 · High-dose caffeine timing",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"In 12 healthy sleepers, one 400-mg dose disrupted sleep at zero, three, and six hours before bedtime versus placebo. The AASM summary reports over one hour less measured sleep at six hours.",limitation:"Primary abstract and official AASM summary accessed. Small, high-dose experiment; not a universal six-hour cutoff or prediction for tea. Exact effect confidence interval was unavailable."},{id:"S14",title:"Chang et al. · 2015 · Evening e-reader exposure",url:"https://doi.org/10.1073/pnas.1418490112",type:"research",finding:"Twelve healthy young adults read an iPad or print for four evening hours on five evenings each. E-reader exposure delayed sleep onset and melatonin timing; total sleep within the scheduled opportunity did not differ.",limitation:"Full published report accessed. A prolonged controlled exposure is not a brief phone glance, and this experiment did not test a 30-minute shutdown threshold."},{id:"S15",title:"He et al. · 2020 · Bedtime phone-use pilot",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0228756",type:"research",finding:"A randomized pilot with 38 willing university participants tested avoiding bedtime phone use for 30 minutes, using restrictions, reminders, and nightly checks. Self-reported outcomes favored the intervention.",limitation:"Small, unblinded pilot with exclusions and active adherence support. Results describe four weeks while Methods ambiguously mentions one week. The approximate 12-minute onset improvement is within-group, not the randomized between-group difference."},{id:"S17",title:"National Sleep Foundation · 2025 · Light and sleep",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Suggests daytime outdoor light and dimmer evening light, including practical one-hour outdoor and screen-off periods.",limitation:"Public education without tested minimum doses. A window seat is not established as equivalent to outdoor exposure. Adapt to shifts, access, vision, mobility, and contact needs."},{id:"S19",title:"Stutz et al. · 2019 · Evening exercise and sleep",url:"https://doi.org/10.1007/s40279-018-1015-0",type:"research",finding:"Across 23 studies in healthy adults, evening exercise did not generally worsen sleep. Very vigorous exercise ending within an hour may differ.",limitation:"Abstract access. Moderator findings were sensitive to one study. This does not prove all late exercise harmless or transfer directly to people with insomnia; no universal evening exercise ban follows."},{id:"S20",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"sleep-duration",title:"Watson et al. · 2015 · Adult sleep-duration consensus",url:"https://www.aasm.org/resources/pdf/adultsleepdurationconsensus.pdf",type:"guidance",finding:"For adults ages 18–60, recommends regularly sleeping at least seven hours. Individual need varies, and longer sleep can be appropriate during illness or recovery.",limitation:"Full consensus statement and methods accessed. This is a population recommendation, not an exact personal target. Time in bed is not the same as sleep; health associations do not establish individual causation."},{id:"cdc-sleep",title:"CDC · 2024 · About sleep",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"Sleep duration and quality both matter. Age-based recommendations vary. Regular sleep problems or disorder symptoms warrant care; an optional diary can record sleep, wake, naps, substances, and medications.",limitation:"Public guidance. A diary is not a prerequisite for contacting care, and meeting a duration recommendation does not rule out a sleep disorder."},{id:"sleep-light",title:"National Sleep Foundation · 2025 · Light and sleep",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"Suggests daytime outdoor light and dimmer evening light, including practical one-hour outdoor and screen-off periods.",limitation:"Public education without tested minimum doses. A window seat is not established as equivalent to outdoor exposure. Adapt to shifts, access, vision, mobility, and contact needs."},{id:"sleep-habits",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"caffeine-timing",title:"Drake et al. · 2013 · High-dose caffeine timing",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"In 12 healthy sleepers, one 400-mg dose disrupted sleep at zero, three, and six hours before bedtime versus placebo. The AASM summary reports over one hour less measured sleep at six hours.",limitation:"Primary abstract and official AASM summary accessed. Small, high-dose experiment; not a universal six-hour cutoff or prediction for tea. Exact effect confidence interval was unavailable."},{id:"caffeine-amounts",title:"FDA · How much caffeine is too much?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"For most adults, 400 mg daily is not generally associated with negative effects; sensitivity varies. Actual product and serving amounts differ. Gradual reduction can limit withdrawal symptoms.",limitation:"Consumer guidance, not a sleep-neutral allowance or intake target. Pregnancy, breastfeeding, medication, and condition questions require professional advice. Decaf can contain caffeine; update date was not verified."},{id:"nhs-insomnia",title:"NHS · 2024 · Insomnia",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"Seek care if changes have not helped or sleep trouble makes daily life hard to cope with. Go to bed when sleepy and avoid driving while sleepy. Shift work, illness, and medicines can contribute.",limitation:"Three months describes persistence, not a waiting requirement. Public habit durations are suggestions, not individualized safe thresholds. This is guidance, not a diagnosis."},{id:"insomnia-self-help",title:"Schutte-Rodin et al. · 2008 · Stimulus control guidance",url:"https://aasm.org/resources/clinicalguidelines/040515.pdf",type:"guidance",finding:"Stimulus control responds to perceived sustained wakefulness, encourages a quiet alternative and return when sleepy, and discourages clock watching. Fatigue and sleepiness are distinct.",limitation:"Relevant full protocol accessed. Approximate minutes are not a biological threshold. Older diagnostic and medication guidance is not retained. Adapt nighttime movement with clinical guidance when access or safety is uncertain."},{id:"insomnia-guideline",title:"American College of Physicians · 2016 · Initial insomnia treatment",url:"https://www.acponline.org/acp-newsroom/acp-recommends-cognitive-behavioral-therapy-as-initial-treatment-for-chronic-insomnia",type:"guidance",finding:"Recommends CBT-I as initial treatment for adult chronic insomnia. Delivery can include individual or group care, telephone or web modules, and structured self-help. Medication decisions require discussion with a clinician.",limitation:"Official guideline summary, not a trial. A chronic-insomnia duration definition is not a waiting requirement for assessment, and every digital product is not validated CBT-I."},{id:"cbti-insomnia",title:"Trauer et al. · 2015 · CBT-I for chronic insomnia",url:"https://doi.org/10.7326/M14-2841",type:"research",finding:"Across 20 trials with 1,162 adults, face-to-face multicomponent CBT-I reduced diary sleep-onset time by 19.03 minutes and nighttime wakefulness by 26.00 minutes. Total sleep increased 7.61 minutes, with a confidence interval spanning no difference.",limitation:"Abstract access. Narrow eligibility and inactive comparisons limit transfer. These are end-of-treatment averages, not ODA predictions; an inconclusive total-sleep difference does not negate continuity benefits."},{id:"sleep-apnea",title:"NHS · 2026 · Sleep apnea",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"Breathing interruptions, gasping or choking, and excessive daytime sleepiness are reasons for medical evaluation. Symptoms can include frequent waking, loud snoring, headaches, and concentration problems.",limitation:"A symptom list does not diagnose apnea. Living alone or lacking a witness does not prevent assessment. Relaxation does not treat blocked breathing."},{id:"sleep-cbti-overview",title:"NIH/NHLBI · 2022 · Insomnia treatment",url:"https://www.nhlbi.nih.gov/health/insomnia/treatment",type:"guidance",finding:"Describes CBT-I as a multicomponent treatment commonly over six to eight weeks, with in-person, phone, and online delivery. Stimulus control includes going to bed when sleepy and leaving if unable to sleep.",limitation:"Patient guidance, not a trial or permission for self-directed sleep restriction. Five ODA lessons do not reproduce the described treatment."}],u=[{schemaVersion:2,revision:2,id:"sleep-1",courseId:"sleep",locale:"en",title:"Still scrolling when tomorrow needs you?",goal:"End one optional activity to protect a realistic opportunity for rest.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tomorrow starts while you are still saying “one more.” Choose what ends before your rest opportunity disappears.",reason:{id:"sleep-1-reason",label:"What needs your energy, and what can end earlier?",kind:"text",maxLength:160,optional:!0,suggestions:["Breakfast needs patience; videos can end","Tomorrow’s shift; optional email can wait","Care first; no safe activity to end"]},why:{id:"sleep-1-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["For adults ages 18 to 60, seven hours is a lower sleep recommendation, not an exact target. Seven hours in bed also does not mean seven hours asleep. Plan room for your own need rather than making bedtime another deadline.","Choose one optional activity to end before your intended rest period. Begin winding down, then go to bed when sleepy. Your experiment is the transition you control. Record that separately from sleep or morning energy. Adapt around shifts, care duties, and required contact. If adequate rest keeps being impossible, seek help with the conditions."],example:{title:"Daniel’s stopping point",text:"Daniel wants patience for breakfast with his daughter. At 9:30 p.m., he stops a replay and closes his laptop, leaving room before his early shift. He goes to bed when sleepy. A care call interrupts the evening. In the morning, he records the laptop closure and the interruption. He still feels tired."}},move:{invitation:"Keep your stopping cue. New plan? Name the activity and opening in this video example.",instructions:["Name your rest opportunity and an existing event that starts the transition.","End the named optional activity at that cue; go to bed when sleepy."],prompts:[],suggestions:{action:["Close optional videos after evening cleanup","Put optional work aside after dinner","End group chat after the goodnight message"],minimum:["Close the optional video session","Put one optional work item aside","Send goodnight and end group chat"],cue:["After tonight’s evening cleanup","After my last necessary task","After my planned goodnight message"],place:["On my living-room sofa","Beside my laptop","My accessible rest space"],minutes:[2,1,5],fallback:["Finish essential care, then close optional videos","Keep needed calls available","Ask for help protecting rest"],observation:["What I ended at the cue","Whether care changed the plan","Morning energy, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Close optional videos after evening cleanup",minimum:"Close the optional video session",minutes:2,cueHint:"After tonight’s evening cleanup",placeHint:"On my living-room sofa",obstacleHint:"An essential task or care need interrupts the cue",fallbackHint:"Finish essential care, then close optional videos",observationHint:"What I ended at the cue"},stopRule:"Avoid driving while sleepy. Seek care if sleep trouble affects coping.",accessibleAlternative:"Adapt the cue to shifts, disability, or care; keep necessary contact."},result:{question:"Did you end the activity you chose?",observationPrompt:"What ended, and what changed your available rest time?"},judgment:{primary:{id:"sleep-1-decision",scenario:"Daniel rises at 6 a.m. and usually needs more than seven hours. Optional videos keep him up past midnight.",question:"Which plan protects a useful opportunity?",options:[{id:"sleep-1-short-window",text:"End videos just before eleven, keeping a seven-hour opportunity and checking how he feels tomorrow.",feedback:"That protects some time, but seven hours is a population minimum rather than Daniel’s personal target. His known need asks for an earlier transition, without forcing sleep."},{id:"sleep-1-earlier-transition",text:"End optional videos earlier, start winding down, and record the transition separately from sleep quality.",feedback:"This changes what Daniel controls and leaves room for his known need. Going to bed when sleepy avoids turning a clock time into a demand to fall asleep."},{id:"sleep-1-weekend-recovery",text:"Keep tonight’s videos and arrange extra weekend rest, then revisit the schedule after the busy week.",feedback:"Extra rest may be useful, but this leaves tonight’s avoidable loss of opportunity unchanged. Daniel can protect tonight’s transition while adjusting his wider schedule and obligations."}],bestOptionId:"sleep-1-earlier-transition"}},carry:{takeaway:"Protect the opportunity. Report the transition and the night as different things.",followUp:{questionId:"sleep-1-return",question:"Did your stopping cue leave workable room for rest?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"A floor is not your personal target",paragraphs:["The AASM and Sleep Research Society consensus recommends at least seven hours regularly for adults ages 18 to 60 [S07]. It was developed by experts reviewing research, not by assigning every person a seven-hour night. Much of the health evidence is observational. Associations between short sleep and illness do not show that one short night caused a health problem.","The CDC gives different ranges for older adults: seven to nine hours at ages 61 to 64 and seven to eight at 65 or older [S08]. These remain population guidance. Quality, daytime functioning, illness, and recovery matter alongside duration. Your rest opportunity should allow for your own need and settling time. A recorded laptop closure is evidence of that action. It cannot establish how much you slept or diagnose why you remain tired."]},{heading:"Make room without forcing sleep",paragraphs:["NHS guidance advises going to bed when sleepy and seeking care when sleep difficulties make daily coping hard [S11]. A planning time can begin the transition away from an optional activity. It is not an instruction to lie awake because a calculated bedtime has arrived. A regular schedule can be useful, while shift work, care, disability, and housing may require an individualized arrangement.","This course follows one experiment: protect a workable rest opportunity, record the controllable move, and adjust a condition that actually blocked it. Later lessons offer changes when your record points to screens, caffeine, or wakeful struggle. They do not require collecting a new nightly ritual. If your obligations keep crowding out adequate rest, practical help or clinical advice may matter more than another reminder. Notes are optional and never a requirement before asking for support."]}],sourceIds:["S07","S08","S11"]}},{schemaVersion:2,revision:2,id:"sleep-2",courseId:"sleep",locale:"en",title:"Your phone needs a handover",goal:"Replace one optional screen interval while preserving its real function and necessary contact.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"You put the phone down, then pick it up again. What job did your wind-down leave unfinished?",reason:{id:"sleep-2-reason",label:"What does the screen provide that you still need?",kind:"text",maxLength:160,optional:!0,suggestions:["Connection with friends","An accessible audiobook","Overnight care calls","No need; scrolling reopened"]},why:{id:"sleep-2-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["One small laboratory study tested four hours of evening e-reader use, not a quick phone check. It changed sleep timing, but cannot tell you what one glance costs. A separate bedtime-phone pilot used reminders and nightly checks. A silent phone alone was not the tested program.","Use your rest-opportunity record. If optional screen use delayed your transition, choose a replacement that does the same job: earlier connection, accessible audio, or print reading. Try five offline minutes as a smaller personal experiment, without claiming the studied effect. Keep needed calls reachable. Otherwise, repeat your existing move."],example:{title:"Daniel keeps the connection",text:"Daniel’s record shows late group messages kept reopening his evening. At his wind-down cue, he sends a brief goodnight and uses five minutes of offline audio. Care calls remain audible. One message still tempts him back. He records the offline interval, rather than calling the whole evening screen-free or claiming better sleep."}},move:{invitation:"Keep a named replacement that works. New plan? Edit this offline-audio example if it serves your wind-down need.",instructions:["Change the screen interval only if it blocked your existing move.","Name the replacement, actual stopping cue, and reachable essential-contact channel before saving."],prompts:[],suggestions:{action:["Listen to downloaded audio after ending chat","Read print after sending a goodnight message","Close optional videos after evening cleanup"],minimum:["Listen to downloaded audio for five minutes","Read print for five minutes","Close the optional video session"],cue:["After tonight’s planned goodnight message","After my planned connection time","After evening cleanup, before another optional video"],place:["In my evening chair, care ringer audible","Near my reachable phone","My usual wind-down space"],minutes:[5,2,10],fallback:["End chat; keep care calls and audio","Use accessible offline audio","Read an available print book instead"],observation:["Audio used, minutes, and required access","Whether necessary contact stayed available","What reopened optional screen use"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Listen to downloaded audio after ending chat",minimum:"Listen to downloaded audio for five minutes",minutes:5,cueHint:"After tonight’s planned goodnight message",placeHint:"In my evening chair, care ringer audible",obstacleHint:"Optional chat reopens while my phone provides care access",fallbackHint:"End chat; keep care calls and audio",observationHint:"Audio used, minutes, and required access"},stopRule:"Keep essential contact and safe lighting; stop changes that obstruct care.",accessibleAlternative:"Use accessible audio or another replacement; required screen tools can stay."},result:{question:"Did you use the replacement you chose?",observationPrompt:"What replaced the screen, and what access did you preserve?"},judgment:{primary:{id:"sleep-2-decision",scenario:"Daniel needs overnight care calls. Group chat delayed his stopping cue yesterday. Print and downloaded audio are ready; his care ringer remains audible nearby.",question:"Which change fits both needs?",options:[{id:"sleep-2-dim-only",text:"Keep chatting in bed with the brightness reduced, preserving contact and his familiar evening connection.",feedback:"Lower brightness changes one feature, but the ongoing chat still displaced Daniel’s transition. He needs a stopping cue and a replacement while keeping necessary calls available."},{id:"sleep-2-remove-phone",text:"Read print beside the reachable care phone, leaving group chat open so he can finish replies between pages.",feedback:"This preserves care access and changes the reading format. But leaving chat open keeps the activity that delayed stopping. End optional replies before the replacement while keeping the care ringer available."},{id:"sleep-2-planned-handover",text:"End the chat at his cue, keep care calls audible, and use his offline replacement.",feedback:"This preserves necessary contact while changing the optional activity that delayed rest. Five offline minutes can test feasibility; it does not inherit the effects of a larger researched program."}],bestOptionId:"sleep-2-planned-handover"}},carry:{takeaway:"A workable screen boundary keeps the need and changes the delivery.",followUp:{questionId:"sleep-2-return",question:"Did your replacement serve the need without reopening optional screen use?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"What the device studies actually tested",paragraphs:["Chang and colleagues studied 12 healthy young adults in a controlled inpatient crossover experiment [S14]. Participants read an iPad or print from 6 to 10 p.m., with a short break, on five evenings per condition. E-reader exposure delayed sleep onset and melatonin timing. Total sleep did not differ within the scheduled eight-hour opportunity. That is a prolonged exposure, not evidence that every phone glance causes a particular sleep loss.","He and colleagues randomized 38 willing university participants with poor self-reported sleep [S15]. Their phone restriction included reminders, device restrictions or shutdown, and nightly checks. Results describe four weeks, while Methods ambiguously mentions one week. The trial was small and unblinded. Its roughly 12-minute onset improvement was a within-group change, not the randomized between-group difference. ODA’s voluntary handover, essential-contact exception, and five-minute minimum have not been tested as equivalents."]},{heading:"Light advice needs a real-life fit",paragraphs:["The National Sleep Foundation suggests outdoor daytime light and dimmer evening light [S17]. Its one-hour outdoor and screen-off durations are public recommendations, not verified minimum effective doses. Sitting beside a window may be accessible, but the guidance does not establish equivalence to outdoor exposure. Night shifts, weather, vision, mobility, and care needs also affect which arrangement is practical.","Choose one change that fits the existing rest experiment. If screen use is not delaying your transition, you can keep the move you already chose instead of adding a new cutoff. If light is the relevant issue, select safe lighting or an accessible daytime opportunity. Do not dim a path so far that moving becomes unsafe. Record what changed, whether the replacement met its purpose, and any access problem. A single better or worse morning cannot isolate what caused it."]}],sourceIds:["S14","S15","S17"]}},{schemaVersion:2,revision:2,id:"sleep-3",courseId:"sleep",locale:"en",title:"That late drink may follow you home",goal:"Replace or move one actual caffeine serving when your rest record makes it worth testing.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Falling asleep after coffee does not settle what the late serving costs.",reason:{id:"sleep-3-reason",label:"What makes this late drink worth its possible cost?",kind:"text",maxLength:160,optional:!0,suggestions:["It helps me finish essential work","I fall asleep; quality remains unknown","I haven’t compared mornings without it","No late serving to test"]},why:{id:"sleep-3-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Caffeine’s effect depends on amount, timing, and personal sensitivity. In a small experiment, one 400-milligram dose disrupted sleep even six hours before bed. That was a high dose, not an ordinary-cup prediction or proof that six hours is a safe boundary.","If your rest record points to a late serving, change that one serving: move it earlier, replace it, or reduce gradually. Note the actual product and time. Keep other major habits reasonably steady. The record can inform your next choice, but does not prove causation. If caffeine is irrelevant, continue your existing rest move."],example:{title:"Daniel tests one serving",text:"Daniel notices a large late coffee beside his laptop on two recorded evenings. Today he swaps that serving for his usual caffeine-free drink while finishing essential work. He leaves his morning coffee unchanged. He misses the lift and remains tired tomorrow. He records the substitution and timing before deciding whether to repeat it."}},move:{invitation:"Keep your serving. New plan? Edit this coffee-to-water example for your actual drink.",instructions:["Name the actual product, serving, cue, and replacement before saving this example.","Change only that serving; choose gradual reduction if an abrupt change is unsuitable."],prompts:[],suggestions:{action:["Replace my late coffee with water","Move one caffeine serving earlier","Reduce one habitual serving gradually"],minimum:["Drink water instead of late coffee","Drink one serving earlier","Use my chosen smaller serving"],cue:["When I reach for my evening coffee","Before my usual late break","At my existing drink cue"],place:["At my kitchen counter","At my usual drink station","Beside my work desk"],minutes:[2,1,5],fallback:["Use available water instead of late coffee","Take a suitable rest break","Seek advice on gradual reduction"],observation:["Product, serving, and actual time","Whether the planned serving changed","Morning functioning, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Replace my late coffee with water",minimum:"Drink water instead of late coffee",minutes:2,cueHint:"When I reach for my evening coffee",placeHint:"At my kitchen counter",obstacleHint:"My preferred caffeine-free drink is unavailable",fallbackHint:"Use available water instead of late coffee",observationHint:"Product, serving, and actual time"},stopRule:"Avoid sleepy driving. Keep medicines unchanged; ask a clinician about pregnancy, breastfeeding, or health concerns.",accessibleAlternative:"Use a gradual change or repeat your existing move if caffeine is irrelevant."},result:{question:"Did you change the serving you chose?",observationPrompt:"What drink, amount, and timing did you actually use?"},judgment:{primary:{id:"sleep-3-decision",scenario:"Daniel’s late coffee seems worth testing. He also wants to change meals, screens, and exercise this week.",question:"Which first test is easier to interpret?",options:[{id:"sleep-3-one-serving",text:"Replace the identified late coffee, note its timing, and leave other major habits reasonably steady.",feedback:"One identified change makes the record easier to interpret, though it cannot prove causation. Daniel can review feasibility and morning functioning before adding a different change to the same experiment."},{id:"sleep-3-under-limit",text:"Keep the coffee because his total is below the general daily limit, and record sleep duration.",feedback:"A general daily limit does not guarantee unaffected sleep. Amount, timing, and sensitivity still matter. Recording sleep without changing the identified serving does not test Daniel’s chosen question."},{id:"sleep-3-whole-overhaul",text:"Remove caffeine and shift meals, exercise, and screens together, then keep whatever seems to help.",feedback:"A broader overhaul changes several things at once and may be harder to sustain. Daniel would not know which change was relevant; an abrupt reduction can also need adjustment."}],bestOptionId:"sleep-3-one-serving"}},carry:{takeaway:"Change one relevant serving. A daily limit is not a promise about sleep.",followUp:{questionId:"sleep-3-return",question:"Did the serving change, and is this one change workable to repeat?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Timing does not become a safety cutoff",paragraphs:["The often-cited Drake experiment involved 12 healthy sleepers and one 400-milligram dose on a caffeine day [S13]. It tested zero, three, or six hours before bedtime against placebo, not three high doses each day. The official AASM summary reports more than one hour less measured sleep at six hours. Exact effect confidence intervals were unavailable in the opened primary abstract.","This was a high single dose in a small group of healthy sleepers. It cannot predict the cost of your ordinary coffee or establish a universally safe six-hour cutoff. The useful question is which actual serving is worth changing and whether the change fits the job it does for you. Record the product, amount, and timing alongside your morning observation. One substitution is a practical experiment, not a treatment or proof of causation. Keep the other major habits reasonably steady when feasible."]},{heading:"An actual serving is more useful than a target",paragraphs:["The FDA’s general 400-milligram figure is not a goal and does not guarantee undisturbed sleep [S10]. Product amounts and serving sizes vary. Tea, soda, energy drinks, and some decaf drinks can contribute caffeine. Record your actual product and its label or usual serving rather than treating every household cup as interchangeable. Personal sensitivity and health circumstances can require professional advice.","This course’s substitution is a practical experiment, not a replicated trial dose. If you consume caffeine habitually, a gradual change may be more manageable than abruptly removing every serving. The FDA advises gradual reduction to limit withdrawal symptoms [S10]. Keep the purpose connected to your existing rest opportunity. Report the drink action even if the next night is unchanged. If sleep trouble makes daily coping hard, seek care without waiting for a perfect diary; avoid driving while sleepy [S11]."]}],sourceIds:["S10","S13","S11"]}},{schemaVersion:2,revision:2,id:"sleep-4",courseId:"sleep",locale:"en",title:"Stop making bedtime a contest",goal:"Use a safe quiet alternative if sustained wakefulness becomes a struggle, without watching the clock.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Another clock check, another calculation. Prepare a safe response to wakefulness without trying to win sleep.",reason:{id:"sleep-4-reason",label:"What do you do when being awake becomes a struggle?",kind:"text",maxLength:160,optional:!0,suggestions:["I check the clock repeatedly","I plan tomorrow from bed","I try to force sleep","No recent occasion"]},why:{id:"sleep-4-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Feeling drained is not the same as feeling sleepy. Sleepiness means you might drift off. Clinical guidance says: go to bed when sleepy, and choose a quiet alternative when sustained wakefulness becomes a struggle. Avoid clock watching. Twenty minutes is no biological deadline.","Use your existing rest experiment. If wakeful struggle appeared, arrange a safe, quiet activity and use it when needed; return when sleepy. Choose clinical guidance if getting up is unsafe or impractical. No occasion is a valid record. The controllable move is your response, not how quickly sleep arrives."],example:{title:"Daniel leaves the calculation",text:"Before wind-down, Daniel sets a book beside his living-room chair and checks the route and lamp. Later he notices sustained wakefulness and clock checking. He moves safely to the chair and reads, then returns when sleepy. He records preparation separately from the nighttime response. Sleep was still broken; he considers seeking help."}},move:{invitation:"Already prepared? Keep your response. Otherwise choose Adapt this, then Preparation, and edit this reading setup example. Check safety today.",instructions:["Preparation example: name a quiet activity and place; check the route before saving.","Keep preparation separate from nighttime use; use the response only if needed.","If movement is unsafe, pause and ask for individualized guidance before another trial."],prompts:[],suggestions:{action:["Set out print reading; check chair route","Arrange quiet audio; check safe seating","Check lamp and route to reading chair"],minimum:["Place book and check route to chair","Set audio ready and check seating","Check safe lighting and clear chair route"],cue:["After evening cleanup","After my last necessary evening task","Before settling into my rest space"],place:["Beside my living-room reading chair","At my accessible evening seat","Along the route to my reading chair"],minutes:[5,2,10],fallback:["Pause; ask for individualized guidance","Ask for help checking the safe route","Use a previously agreed accessible response"],observation:["Activity set ready and route safety checked","Whether I avoided clock checking","Response and sleep, recorded separately"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Set out print reading; check chair route",minimum:"Place book and check route to chair",minutes:5,cueHint:"After evening cleanup",placeHint:"Beside my living-room reading chair",obstacleHint:"The chair or nighttime route is unsafe or unavailable",fallbackHint:"Pause; ask for individualized guidance",observationHint:"Activity set ready and route safety checked",kind:"preparation"},stopRule:"Avoid sleepy driving. If movement is unsafe, pause this move and ask for individualized guidance.",accessibleAlternative:"Keep an actual clinician-agreed adaptation. Without one, request guidance; do not improvise an unsafe nighttime move."},result:{question:"Did you prepare the safe setup or use your chosen response?",observationPrompt:"What did you set ready, check, or use; was anything unsafe?"},judgment:{primary:{id:"sleep-4-decision",scenario:"Daniel has been wakeful and keeps checking the clock. His prepared quiet chair is safe to reach.",question:"Which response fits the plan?",options:[{id:"sleep-4-timed-checks",text:"Use twenty-minute reminders to decide when to move, then turn them off after the first attempt.",feedback:"A timer looks precise but turns perceived wakefulness into clock watching. The guidance discourages that. Daniel can notice sustained struggle and use the safe alternative without an elapsed-minute test."},{id:"sleep-4-safe-alternative",text:"Stop clock checking, use his quiet chair when struggle persists, and return when he feels sleepy.",feedback:"This follows the flexible response rather than a stopwatch. Daniel can report whether he used it and any access problem; falling asleep quickly is not the completion condition."},{id:"sleep-4-push-through",text:"Stay in bed for a planned relaxation session first, then decide by morning whether the plan worked.",feedback:"Relaxation may be comfortable. If wakeful struggle continues, use the safe alternative now; do not wait for a morning verdict to respond. Keep clock checking out of either choice."}],bestOptionId:"sleep-4-safe-alternative"}},carry:{takeaway:"Respond to wakeful struggle. Sleep arrival is not a task you can tick.",followUp:{questionId:"sleep-4-return",question:"Did you prepare the safe setup, or use it when needed, without clock watching?",observationPrompt:"Which part happened, and was anything unsafe or unavailable?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Perceived wakefulness, not a stopwatch",paragraphs:["The AASM’s older clinical guideline describes stimulus control and explicitly advises avoiding clock watching [S20]. Its approximate twenty-minute cue refers to perceived wakefulness, not a measured biological threshold. The same guideline distinguishes fatigue, a sense of low energy, from sleepiness, the tendency to fall asleep. Those distinctions explain why an exhausted person need not force a clock-based bedtime.","The NIH overview includes going to bed when sleepy, leaving when unable to sleep, and returning to sleep-related use of the bed [S06]. These are parts of a broader clinical approach. They do not establish that every difficult night comes from worry or a weak bed association. ODA’s quiet alternative is education with practical adaptations, not a complete treatment. Your record asks whether the conditional response was needed and used, allowing no occasion when the situation did not arise."]},{heading:"A safe response comes before a rigid routine",paragraphs:["A quiet alternative requires safe access. Mobility limitations, fall risk, one-room housing, care duties, and shifts can make leaving bed unsuitable. An individualized clinician plan is preferable to copying an instruction that does not fit. Safe lighting matters more than making a path extremely dim. This course does not prescribe a reduced sleep window, ban a needed safety nap, or instruct you to change medication.","NHS guidance says not to drive when sleepy and recommends care when sleep difficulties impair coping [S11]. A regular schedule should be considered alongside adequate sleep opportunity and immediate safety. If the night is poor, do not treat keeping an early alarm as permission to drive dangerously. Bring the actual difficulty to care or practical support. Preparing the quiet space is preparation; using it during a needed response is a different attempt. Neither demonstrates improved sleep by itself."]}],sourceIds:["S06","S11","S20"]}},{schemaVersion:2,revision:2,id:"sleep-5",courseId:"sleep",locale:"en",title:"Bad nights are shrinking your life?",goal:"Review your rest experiment and carry forward one workable move or make a needed care request.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bad nights still affecting your day? Use any records to choose next week’s move or ask for care now.",reason:{id:"sleep-5-reason",label:"What is sleep trouble already costing your ordinary week?",kind:"text",maxLength:160,optional:!0,suggestions:["Too sleepy to travel safely","Daily tasks are hard","I miss time with people","No known impact yet"]},why:{id:"sleep-5-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sleep trouble need not last three months before you ask for help. Difficulty coping, unhelpful habit changes, gasping, breathing pauses, or persistent daytime sleepiness can justify assessment. Living alone and unfinished notes should not delay contact.","Review records from your existing rest experiment, including an untried plan. Keep one feasible rest move or request care now. No attempt yet? Choose a first opportunity. ODA is not structured insomnia treatment. Do not prescribe yourself less time in bed or change medicines."],example:{title:"Daniel asks before another overhaul",text:"Daniel’s records show he ended optional work on three nights, yet daytime sleepiness still makes his commute unsafe. He sends his clinic an assessment request describing the impact. He asks a colleague for a ride. The clinic has not answered by evening. He records the request and chooses the next contact opening as his fallback."}},move:{invitation:"Concerning signs or impaired coping? Choose Adapt this, then Support. Edit this care example for your next opening. Otherwise keep your rest move.",instructions:["Name your clinic, actual opening date, and private contact place before saving this care example.","If unanswered, choose another contact route now; do not wait for another rest trial.","Without concerning signs, keep your named rest move or choose Practice under Adapt."],prompts:[],suggestions:{action:["Call primary care for a sleep assessment","Send my clinic an assessment request","Ask a trusted person to arrange contact"],minimum:["Make one clinic contact attempt","Send one assessment request","Make one request for contact assistance"],cue:["At primary care’s next contact opening","After lunch, while my clinic is open","When an available appointment line opens"],place:["At my kitchen table, phone ready","In a private accessible contact space","Beside my accessible messaging device"],minutes:[2,5,10],fallback:["Ask a trusted person to arrange contact","Call the public health service appointment line","Retry my clinic at its next opening"],observation:["Contact attempted; reply or no reply","Appointment offered and next access step","Assistance requested and any response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Call primary care for a sleep assessment",minimum:"Make one clinic contact attempt",minutes:2,cueHint:"At primary care’s next contact opening",placeHint:"At my kitchen table, phone ready",obstacleHint:"My clinic is unavailable or has not answered",fallbackHint:"Ask a trusted person to arrange contact",observationHint:"Contact attempted; reply or no reply",kind:"support"},stopRule:"Seek assessment for gasping or daytime sleepiness. Avoid sleepy driving; do not self-prescribe sleep restriction.",accessibleAlternative:"Use phone, text, or assisted contact. Name a reachable fallback person or public service before saving."},result:{question:"Did you carry out the next step you chose?",observationPrompt:"What move or care request happened, and what remains unresolved?"},judgment:{primary:{id:"sleep-5-decision",scenario:"Daniel’s persistent daytime sleepiness makes commuting unsafe despite rest changes. His clinic is open now; his public appointment line opens tomorrow.",question:"Which next step fits his records?",options:[{id:"sleep-5-more-records",text:"Ask his sister tonight to help arrange an appointment tomorrow, while using a safe travel alternative now.",feedback:"This protects travel and gets practical help. Because Daniel can contact the open clinic now, assistance tonight need not delay that request. He can ask his sister alongside it."},{id:"sleep-5-continue-changes",text:"Use safe transport now and call the public appointment line tomorrow for help finding an accessible clinician.",feedback:"That is a useful access route if his clinic cannot help. With the clinic open now, he can make the first assessment request today and keep tomorrow’s route as fallback."},{id:"sleep-5-contact-now",text:"Contact the clinic about daytime impairment now, keep optional notes, and arrange a safe travel alternative.",feedback:"This responds to the actual impact while preserving safety. Daniel does not need three months, a witness, or a finished diary before requesting appropriate assessment and discussing next steps."}],bestOptionId:"sleep-5-contact-now"}},carry:{takeaway:"Keep the useful move. Get care for the difficulty the move does not resolve.",followUp:{questionId:"sleep-5-return",question:"What happened with your rest move or care request, and what response or access step remains?",observationPrompt:"What was attempted, and what is still pending?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Care does not wait for a course or a diary",paragraphs:["NHS insomnia guidance includes difficulty coping and habit changes that have not helped as reasons to contact care [S11]. Three months distinguishes a persistence category; it is not an instruction to wait. Sleep can be affected by work schedules, health, medication, and other conditions. This course cannot decide which explanation applies to you. A clinician can evaluate the problem and appropriate treatment.","Breathing interruptions, gasping or choking, and excessive daytime sleepiness warrant evaluation for possible sleep apnea or another cause [S12]. Loud snoring alone is not a diagnosis. Living alone does not disqualify you from asking for assessment. You can describe your own daytime impact or nighttime observations. Bring existing records if useful, but do not delay an appointment to complete a particular number of nights. Avoid driving or dangerous work when sleepy while arranging appropriate help."]},{heading:"What structured treatment can offer",paragraphs:["ACP recommends cognitive behavioral therapy for insomnia as initial treatment for chronic insomnia [S05]. Delivery can include individual or group care, telephone or web modules, and structured self-help formats. This does not make every digital sleep product validated treatment. Medication decisions require discussion with a clinician. ODA provides habit education and a record of controllable actions, which can support a conversation without replacing care.","Your final step is consolidation, not another nightly exercise. Look across any plans and attempts: which transition was feasible, what blocked it, and what difficulty remains? If no attempt was recorded, that outcome is unknown. Choose a first feasible opportunity or support. Carry forward one useful move or a care contact into the coming week. A request with no reply is still a real contact attempt, with a next access decision. No diary, course completion, or good quiz answer proves you slept well. You may pause the experiment while seeking assessment or practical help."]}],sourceIds:["S05","S11","S12"]}}],H=[{practice:["Choose a workable wake schedule; adapt it for shifts, care duties, and adequate sleep opportunity.","Plan adequate room for your own sleep need and settling time; begin winding down, not forced sleep.","For the next seven days, jot down a short note of when you went to bed and when you got up."],reflection:"What might make it hard to keep the wake-up time you chose?",question:"How should the adult sleep recommendation be read?",options:["Everyone must sleep exactly 8 hours.","At least 7 hours is a floor you aim to reach on most nights.","If you sleep badly one night, your health will definitely suffer."],correct:1,feedback:"The recommendation is a lower limit and is about regular habits. A single bad night is not the same as a pattern that lasts for a long time."},{practice:["Pick a feasible daylight opportunity; an indoor alternative is not established as equivalent to outdoor light.","Try a chosen screen handover before rest; practical durations are guidance, and needed contact stays available.","Choose a calm, dimly lit activity to replace the screen: a book, light stretching or music."],reflection:"At what time in the evening is it hardest for you to put the screen down?",question:"For evening screens, which is a starting point that fits the official recommendations?",options:["Using screens right up until you get into bed.","Winding down with a screen and all the lights fully on.","Putting screens away at least 30 minutes before bed."],correct:2,feedback:"The CDC’s 30-minute suggestion is practical guidance, not a precise threshold. Choose a feasible screen interval and replacement while preserving essential contact."},{practice:["Choose one actual late caffeine serving to move earlier, replace, or reduce gradually; no fixed cutoff guarantees sleep.","For one day, jot down every caffeinated drink you have.","Change one relevant habit first; do not impose a universal evening exercise ban or change prescribed medicines."],reflection:"Which of your evening habits seems easiest to change?",question:"What conclusion can be drawn from the Drake 2013 experiment?",options:["A high dose of caffeine taken 6 hours before bed can still shorten sleep.","Caffeine only affects sleep if taken right before bed.","Caffeine does not affect anyone’s sleep."],correct:0,feedback:"The small study tested one high 400-mg dose, which disrupted sleep even six hours before bed. It does not establish a universally safe cutoff or predict a lower serving’s effect."},{practice:["Choose a safe quiet alternative for sustained wakefulness; seek an accessible adaptation if getting up is unsafe.","Choose a suitable quiet activity there; comfortable breathing is optional, and essential access stays available.","Prepare a workable wind-down and conditional nighttime response without clock watching; avoid driving while sleepy."],reflection:"On a night when you can’t sleep, what would you like to say to yourself?",question:"What does stimulus-control guidance suggest during sustained wakefulness, without clock watching?",options:["Try harder to force yourself to sleep.","Start scrolling on your phone in bed.","Get up, do something quiet in low light and go back when you feel sleepy."],correct:2,feedback:"Use a safe quiet alternative and return when sleepy. Approximate minutes are not a biological deadline. Adapt for access and care needs; do not drive while sleepy."},{practice:["Review any sleep difficulty and daily impact; you do not have to wait three months to request assessment.","If available, another person’s observations can help; living alone does not prevent asking for care.","Contact care when warranted. Optional notes can accompany the appointment; do not delay contact for a two-week log."],reflection:"What might you gain from talking to a professional about your sleep?",question:"For chronic insomnia, which recommended treatment can you discuss with a clinician?",options:["Start sleeping pills on your own.","See a professional and talk about options such as CBT-I.","Assume that repeating this course will be enough."],correct:1,feedback:"ACP recommends CBT-I as initial treatment for chronic insomnia, with several delivery formats. Impairment or suspected apnea warrants timely care; this course does not replace assessment or treatment."}],j=[{id:"1767443522987-a83deb358199",alt:"Classic alarm clock on a wooden floor"},{id:"1527377761-f99968ed8a7f",alt:"Sunlight falling on the floor through a window"},{id:"1743689374053-be49ca407b7c",alt:"A cup of coffee by a window"},{id:"1789930445611-3b13fd7d6de4",alt:"Person reading a book by the light of a small desk lamp"},{id:"1653656120968-accae8452c9e",alt:"Woman sitting on a sofa talking with another woman"}],M={id:"sleep",title:"Still tired tomorrow? Protect your rest tonight",subtitle:"Five lessons to end one evening drain, keep needed contact, and review what your rest experiment actually changes.",description:"Protect a realistic rest opportunity, adjust one relevant obstacle, and use your records to choose a workable next week or timely care.",scope:"Sleep-habit education for adults, not diagnosis or treatment. Seek care when regular sleep trouble affects coping, changes are not helping, or gasping, breathing interruptions, or persistent daytime sleepiness occur. Living alone and unfinished notes do not delay assessment. Avoid driving or dangerous work when sleepy. Do not change medicines or prescribe yourself sleep restriction. Adapt plans to shifts, care, disability, and contact needs. Use appropriate urgent professional or crisis support for severe distress or self-harm thoughts, and local emergency care if you cannot stay safe or face immediate danger.",outcome:"One rest move you can repeat, honest action records, and a next-week or care step for the difficulty that remains.",photo:{id:"1606796913825-2b02883605e9",alt:"Bed with white sheets next to a green plant"},lessons:u.map((e,t)=>({id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,...H[t],takeaway:e.carry.takeaway,sources:t===1?[...e.goDeeper.sourceIds,"S08"]:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:{title:`Invented example: ${e.idea.example.title}`,text:e.idea.example.text},photo:j[t]}))},Z=Object.freeze(Object.defineProperty({__proto__:null,COURSE:M,LESSONS_V2:u,SOURCES:R},Symbol.toStringTag,{value:"Module"})),U=[{id:"suggestion-S01",title:"Peerdeman et al. · 2016 · Expectation interventions for patients’ pain",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 pooled studies involving 1,256 selected patients found reduced reported pain after expectation interventions: g=.61, 95% CI .42 to .79; bias-adjusted .43, .24 to .62.",limitation:"Clinical interventions differ from a self-written phrase. High heterogeneity; reported pain is not cure of its cause. Anxiety sensitivity estimate after removing an outlier was .03, CI −.21 to .26."},{id:"suggestion-S02",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Values affirmation paired with health information showed small average differences in message acceptance, intentions and behavior across 144 outcome tests. Behavior: d=.32, 95% CI .19 to .44.",limitation:"144 tests are not necessarily distinct studies. Outcome participant counts overlap. These results do not establish effects of values writing alone, positive chanting or ODA’s short adult exercise."},{id:"suggestion-S03",title:"Kross et al. · 2014 · Distanced self-talk experiments",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven short experiments involved 585 people. Study 2 used three-minute name or non-first-person reflection before a social interaction and found better observer-rated performance.",limitation:"Mostly student and social-evaluation settings. Preinteraction anxiety did not significantly improve in Study 2; later recovery was clearer. ODA’s shorter advice-and-action adaptation is not treatment or a guaranteed effect."},{id:"suggestion-S04",title:"Hatzigeorgiadis et al. · 2011 · Self-talk and sport performance",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 studies, 62 effects and 2,741 participants found an average sport-task performance benefit: d+=.48, 95% CI .38 to .58. Task and training subgroup estimates varied.",limitation:"Some designs were uncontrolled. Moderator comparisons do not establish optimal doses or universal instructional superiority. Office-work transfer and Gallwey’s whole framework were not tested."},{id:"suggestion-S05",title:"Zhang et al. · 2025 · Self-affirmation and well-being",url:"https://hub.hku.hk/handle/10722/366517",type:"research",finding:"The institutional abstract reports 67 articles and 129 independent tests in nonclinical populations, with small average benefits in self-perception and well-being.",limitation:"Full methods, participant total, confidence intervals, exact effect metric and follow-up durations were unavailable. This does not validate every affirmation script or a named ritual."},{id:"suggestion-S06",title:"Wang, Wang & Gai · 2021 · Outcome, obstacle and response plans",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles, 24 independent effects and 15,907 participants found an average goal-attainment benefit from mental contrasting with if–then plans: g=.336, CI .229 to .443; bias-adjusted .242, .143 to .342.",limitation:"Methods and controls varied. This does not validate the assembled ODA card, positive wording as the active ingredient, or splitting fantasy at bedtime from planning next morning."},{id:"suggestion-S07",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"The abstract reports worse immediate responses for some low-self-esteem participants repeating a strongly positive statement, with limited benefits at higher self-esteem.",limitation:"Original Ns, repetition count and numerical effects were not verified. Two later studies did not reproduce the pattern. No clinical threshold or universal mismatch mechanism is established."},{id:"suggestion-S08",title:"Flynn & Bordieri · 2020 · Affirmation replication studies",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Two university analogue studies, approximately 225 and 237 participants, did not reproduce the predicted mood, state-self-esteem or trait-self-esteem moderation pattern.",limitation:"Authors’ abstract only. Numerical effects, confidence intervals and precision were unavailable. A null result establishes neither universal benefit nor universal harmlessness."},{id:"suggestion-S09",title:"Lally et al. · 2010 · Habits in everyday life",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 volunteers repeated eating, drinking or activity behaviors in recurring contexts over 84 days. Time to modeled automaticity varied substantially among 39 acceptable models.",limitation:"Observational study, not an affirmation trial. The median 66-day estimate is not a deadline; some estimates extend beyond observation. No evidence of automaticity by Friday or a permanent 21-day change."},{id:"suggestion-S10",title:"Paller, Creery & Schechtman · 2021 · Memory and sleep",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"The review discusses reactivation of previously learned material during sleep and limited simple associative sleep learning.",limitation:"Narrative review, no pooled effect. Memory processing does not establish drowsy receptivity to self-help commands, Murphy’s ritual, complex skills installed by recordings or thought-driven outcomes."},{id:"suggestion-S11",title:"Cohen et al. · 2006 · Values writing in one school",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/cohen_et_al._2006_-_reducing_the_racial_achievement_gap.pdf",type:"research",finding:"Two randomized field experiments involved 243 seventh graders at one US school. Approximately fifteen-minute values writing improved targeted course grades for Black students in that setting.",limitation:"No significant effect for White students. A later large replication was null. This does not establish universal academic gains, adult confidence or an immediate mood effect."},{id:"suggestion-S12",title:"Hanselman et al. · 2017 · Large-scale values-affirmation replication",url:"https://files.eric.ed.gov/fulltext/ED578033.pdf",type:"research",finding:"A new-cohort replication across middle schools found no significant targeted GPA benefit. Its precision could reject benefits of at least .10 standard deviations.",limitation:"School context and outcome matter. This does not show all values reflection is useless or disprove health-message findings. The linked text is an accepted manuscript."},{id:"suggestion-S13",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The institutional abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants and confidence interval were unavailable. Task rehearsal does not validate bedtime autosuggestion, a branded ritual or a universal rehearsal dose."},{id:"suggestion-S15",title:"Émile Coué · 1922 English edition · Conscious autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"The historical text prescribes twenty low-voice repetitions on waking and before sleep, counted on knots with closed eyes and without straining.",limitation:"Anecdotes and testimonials are not controlled evidence. Twenty repetitions is historical, not a proven dose. The text’s universal imagination laws and disease-cure claims are unsupported."},{id:"suggestion-S16",title:"Joseph Murphy · The Power of Your Subconscious Mind · publisher synopsis",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The synopsis establishes the book’s provenance and its promotion of belief and imagination.",limitation:"No trial evidence supplied. Exact bedtime phrase, congratulating scene and gratitude passage were unverified. Sleep-memory evidence does not validate drowsy superiority, subconscious attraction or healing."},{id:"suggestion-S17",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Study 1 used one session to identify a desired outcome, obstacle and response, add an if–then plan with usual time and place, then schedule the week.",limitation:"German undergraduate sample; the inspected outcome was scheduled hours, not completed work. No fixed minute dose or special bedtime timing was established."},{id:"suggestion-S18",title:"Louise Hay · What is mirror work?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"The author’s page describes spoken positive statements in a mirror and a 21-day program.",limitation:"Practitioner provenance, not efficacy. No controlled package study was found in the dossier search; this is a search limit. Mirror superiority and a 21-day habit deadline are unestablished."},{id:"suggestion-S19",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher edition",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/9781401938093/",type:"technique",finding:"The publisher identifies the paperback as February 2013; the ebook first appeared in 2012.",limitation:"Promotional synopsis, not controlled evidence. Exact ten-minute routine, gratitude sequence and change cue were unverified. Quantum attraction, genetic commands and healing are not established."},{id:"suggestion-S20",title:"NIMH · Help for mental illnesses",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Official guidance describes routes to qualified mental health and crisis support. Persistent distress, severe impairment and self-harm thoughts warrant appropriate help.",limitation:"ODA is not diagnosis or treatment. Use local services outside the US. Concerning physical symptoms require medical assessment; self-talk must not redefine abuse or real danger as safe."},{id:"murphy-subconscious",title:"Joseph Murphy · The Power of Your Subconscious Mind · publisher synopsis",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The synopsis establishes the book’s provenance and its promotion of belief and imagination.",limitation:"No trial evidence supplied. Exact bedtime phrase, congratulating scene and gratitude passage were unverified. Sleep-memory evidence does not validate drowsy superiority, subconscious attraction or healing."},{id:"expectation-suggestion",title:"Peerdeman et al. · 2016 · Expectation interventions for patients’ pain",url:"https://cris.maastrichtuniversity.nl/ws/files/76691125/Peters_2016_Relieving_patients_with_expectation_interventions.pdf",type:"research",finding:"27 pooled studies involving 1,256 selected patients found reduced reported pain after expectation interventions: g=.61, 95% CI .42 to .79; bias-adjusted .43, .24 to .62.",limitation:"Clinical interventions differ from a self-written phrase. High heterogeneity; reported pain is not cure of its cause. Anxiety sensitivity estimate after removing an outlier was .03, CI −.21 to .26."},{id:"positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"The abstract reports worse immediate responses for some low-self-esteem participants repeating a strongly positive statement, with limited benefits at higher self-esteem.",limitation:"Original Ns, repetition count and numerical effects were not verified. Two later studies did not reproduce the pattern. No clinical threshold or universal mismatch mechanism is established."},{id:"self-affirmation-health",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Values affirmation paired with health information showed small average differences in message acceptance, intentions and behavior across 144 outcome tests. Behavior: d=.32, 95% CI .19 to .44.",limitation:"144 tests are not necessarily distinct studies. Outcome participant counts overlap. These results do not establish effects of values writing alone, positive chanting or ODA’s short adult exercise."},{id:"distanced-self-talk",title:"Kross et al. · 2014 · Distanced self-talk experiments",url:"https://rascl.studentorg.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven short experiments involved 585 people. Study 2 used three-minute name or non-first-person reflection before a social interaction and found better observer-rated performance.",limitation:"Mostly student and social-evaluation settings. Preinteraction anxiety did not significantly improve in Study 2; later recovery was clearer. ODA’s shorter advice-and-action adaptation is not treatment or a guaranteed effect."},{id:"sport-self-talk",title:"Hatzigeorgiadis et al. · 2011 · Self-talk and sport performance",url:"https://doi.org/10.1177/1745691611413136",type:"research",finding:"32 studies, 62 effects and 2,741 participants found an average sport-task performance benefit: d+=.48, 95% CI .38 to .58. Task and training subgroup estimates varied.",limitation:"Some designs were uncontrolled. Moderator comparisons do not establish optimal doses or universal instructional superiority. Office-work transfer and Gallwey’s whole framework were not tested."},{id:"sleep-memory-reactivation",title:"Paller, Creery & Schechtman · 2021 · Memory and sleep",url:"https://faculty.wcas.northwestern.edu/paller/AnnRev2021.pdf",type:"research",finding:"The review discusses reactivation of previously learned material during sleep and limited simple associative sleep learning.",limitation:"Narrative review, no pooled effect. Memory processing does not establish drowsy receptivity to self-help commands, Murphy’s ritual, complex skills installed by recordings or thought-driven outcomes."},{id:"coue-autosuggestion",title:"Émile Coué · 1922 English edition · Conscious autosuggestion",url:"https://www.gutenberg.org/cache/epub/27203/pg27203-images.html",type:"technique",finding:"The historical text prescribes twenty low-voice repetitions on waking and before sleep, counted on knots with closed eyes and without straining.",limitation:"Anecdotes and testimonials are not controlled evidence. Twenty repetitions is historical, not a proven dose. The text’s universal imagination laws and disease-cure claims are unsupported."},{id:"hay-mirror-work",title:"Louise Hay · What is mirror work?",url:"https://www.louisehay.com/what-is-mirror-work/",type:"technique",finding:"The author’s page describes spoken positive statements in a mirror and a 21-day program.",limitation:"Practitioner provenance, not efficacy. No controlled package study was found in the dossier search; this is a search limit. Mirror superiority and a 21-day habit deadline are unestablished."}],p=[{schemaVersion:2,revision:2,id:"suggestion-1",courseId:"suggestion",locale:"en",title:"Your inner critic needs a useful job",goal:"Choose a credible instruction and use it for one real step on your task.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Called yourself useless and left the draft blank? Give that sentence a useful job.",reason:{id:"suggestion-1-reason",label:"What has the criticism cost, and what act matters now?",kind:"text",maxLength:160,optional:!0,suggestions:["A blank application; write a first fact","A delayed correction; check the date","No observed cost yet"]},why:{id:"suggestion-1-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A useful instruction names what to do, such as “Write the first fact.” A flattering verdict names who you supposedly are. Strongly positive statements have mixed evidence: an early study reported worse immediate responses for some participants; two later studies did not reproduce that pattern. Neutral wording does not diagnose you.","Choose a real task serving your direction. Replace the verdict with an instruction, then do one useful piece. Sports research does not prove office-task benefits. Record the act and whether the wording helped, pressured you or did nothing."],example:{title:"Maya’s first fact",text:"At 2:00, Maya sits with her application draft. “I’m hopeless” is familiar; “I’m brilliant” feels false. She tries “Write the first fact” and writes one usable sentence about her experience. She still doubts the application. She records the sentence and unchanged doubt, then schedules another small attempt instead of repeating praise until it feels true."}},move:{invitation:"Name your task and instruction; suggestions show Maya’s application example.",instructions:["Name the actual document, question, or item before saving.","Read the instruction once, then do the matching useful piece."],prompts:[],suggestions:{action:["Write one application sentence using “Write first fact”","Answer the application’s question about work experience"],minimum:["Save one factual work-experience sentence","Save the work-experience answer"],cue:["When lunch ends","After dinner is cleared"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Drop verdict; write one factual application sentence","Ask reviewer which work detail is needed"],observation:["The actual application sentence I saved","Whether wording helped or added pressure"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one application sentence using “Write first fact”",minimum:"Save one factual work-experience sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"The sentence turns into another judgment",fallbackHint:"Drop verdict; write one factual application sentence",observationHint:"The actual application sentence I saved"},stopRule:"Stop wording that increases distress. Choose support for persistent distress; seek care for concerning symptoms.",accessibleAlternative:"Type, dictate or use assistance; neutral task wording is enough."},result:{question:"Did you produce your chosen useful piece?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-1-decision",scenario:"Maya has two minutes and the facts for one application sentence. Praise feels false, and the draft is still blank.",question:"What fits this attempt?",options:[{id:"suggestion-1-praise",text:"Use a warmer positive sentence before deciding whether she can start writing.",feedback:"Warm language is a preference, but she already knows it feels false today. Try a neutral task instruction and make one useful piece without requiring belief in praise."},{id:"suggestion-1-fact",text:"Say “Write the first fact,” then write one usable application sentence.",feedback:"This names an act within her control and tests it immediately. The sentence may help, do nothing or add pressure; her actual output and experience can be recorded."},{id:"suggestion-1-picture",text:"Picture a successful application review, then check whether she feels ready to write.",feedback:"An image may be pleasant preparation, but it does not supply the chosen useful piece. The facts are ready; use an instruction and try the small act."}],bestOptionId:"suggestion-1-fact"}},carry:{takeaway:"Give the sentence a task. Judge it alongside what you actually do.",followUp:{questionId:"suggestion-1-return",question:"What happened with your chosen act, and did the instruction help or add pressure?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Credibility is a choice, not a cutoff",paragraphs:["Wood and colleagues’ accessible abstract reported that a strongly positive statement produced worse immediate responses for some participants with low self-esteem. That abstract does not provide enough detail to prescribe a repetition count or predict an individual response. Two later university analogue studies by Flynn and Bordieri did not reproduce the predicted pattern. The evidence therefore supports uncertainty rather than a settled rule that positive statements harm a particular kind of person. (suggestion-S07; suggestion-S08)","Your preference is still usable information. If “I am brilliant” feels wrong, you can choose “Write the first fact,” edit the wording, skip repetition or stop. A private credibility rating can guide wording, but no score here is a validated clinical threshold. ODA does not infer self-esteem from it or require encouragement. Start with the actual task so the words have a specific job."]},{heading:"Different words, different evidence",paragraphs:["Hatzigeorgiadis and colleagues pooled thirty-two self-talk studies with sixty-two effects in sport and motor tasks. Table 1 reported 2,741 participants. The average performance benefit does not establish the same benefit for application writing, relationships or anxiety. Some study designs were uncontrolled, and subgroup comparisons do not prove a universal ranking of instructional and motivational language. (suggestion-S04)","Today’s neutral instruction and small written piece are an ODA adaptation outside that sport evidence. The combined course has not been tested as a package. Record what you said, what you actually did and any pressure separately. A phrase can be credible without helping action; it can help you start without reducing doubt. Those distinctions give you a reason to keep, edit or stop it rather than treating every repetition as progress toward your chosen life."]}],sourceIds:["suggestion-S07","suggestion-S08","suggestion-S04"]}},{schemaVersion:2,revision:2,id:"suggestion-2",courseId:"suggestion",locale:"en",title:"The ritual ends where the action starts",goal:"Attach your same useful act to a cue that actually occurs.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Repeated the reminder but still left the page blank? Put the action at the cue.",reason:{id:"suggestion-2-reason",label:"If you repeated reminders, what did that give you while the task stayed undone?",kind:"text",maxLength:160,optional:!0,suggestions:["Brief reassurance; the draft stayed blank","Avoided choosing a first sentence","No prior reminder-only attempt"],help:"No prior attempt? Consider what another reminder reading would postpone."},why:{id:"suggestion-2-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Repeating a phrase and repeating an action are different experiments. A habit study tracked eating, drinking and activity at recurring cues. Automaticity developed at different rates; it did not test affirmations. Coué’s twenty repetitions are historical instructions, not a proven dose.","Check your first record. Credible words but no start? Keep the task and choose an event that occurs. “After lunch, write one application sentence” connects cue and act. Read your instruction once if useful, then do the piece. Preparing materials is preparation; writing is the task attempt."],example:{title:"Maya uses lunch",text:"Maya’s first instruction was credible, but she forgot it during a busy morning. She keeps the application task and chooses the end of lunch as her next cue. At the kitchen table she reads “Write the first fact” once and writes a usable sentence. The session stays short. She records the cue and output, without calling it an automatic habit."}},move:{invitation:"Keep your named act; suggestions show Maya’s lunch example.",instructions:["Keep the action and minimum; change a cue only when the record questions it.","For a first plan, name the useful output and actual opening before saving."],prompts:[],suggestions:{action:["After lunch, write one application work-experience sentence","After tea, answer the application’s experience question"],minimum:["Save one factual application sentence","Save the work-experience answer"],cue:["When lunch ends","When I put down my tea"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Write the experience sentence after dinner","Dictate the application sentence at lunch"],observation:["Whether cue and application sentence happened","Reading separately from useful output"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"After lunch, write one application work-experience sentence",minimum:"Save one factual application sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"The lunch cue gets crowded out",fallbackHint:"Write the experience sentence after dinner",observationHint:"Whether cue and application sentence happened"},stopRule:"Skip repetition that adds distress or wakefulness. Preserve care, rest and actual safety needs.",accessibleAlternative:"Use a written, spoken or accessible reminder; no beads or counting required."},result:{question:"Did your cue occur, and did you do the piece?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-2-decision",scenario:"Maya read a credible reminder three mornings but did not write. Her draft and experience facts are ready. Lunch reliably allows one sentence.",question:"What fits this attempt?",options:[{id:"suggestion-2-count",text:"Keep the morning cue and add more repetitions before beginning the draft.",feedback:"More repetition tests phrase reading, not the missing task start. Her records point to cue fit. Use the available lunch opportunity for one actual sentence."},{id:"suggestion-2-cue",text:"Keep credible wording, use lunch as the cue, and write one sentence.",feedback:"This changes the condition that blocked action while preserving the useful task. Record whether the cue occurred and the sentence happened; automaticity is not required."},{id:"suggestion-2-prepare",text:"Use the lunch break to perfect the reminder and arrange tomorrow’s materials.",feedback:"Preparation can serve a missing resource. Her materials and instruction are ready, so another preparation session would leave the same useful sentence undone."}],bestOptionId:"suggestion-2-cue"}},carry:{takeaway:"Cue the useful act, not only the words that precede it.",followUp:{questionId:"suggestion-2-return",question:"Did your chosen cue lead to the act or request, or only reminder reading?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"What Coué’s count can establish",paragraphs:["Coué’s 1922 English text gives historical instructions for twenty low-voice repetitions on waking and before sleep, with closed eyes and knots for counting. The text includes anecdotes, demonstrations and testimonials rather than controlled intervention evidence. The twenty count and twice-daily timing are therefore provenance, not established effective doses. Historical repetition instructions cannot tell you whether today’s wording supports your chosen task. (suggestion-S15)","You do not need to recreate the ritual to test a credible task instruction. Its universal imagination-versus-will laws and disease-cure claims do not follow from the anecdotes. Keep prescribed care and avoid using a reassuring phrase to explain new physical symptoms. The main lesson asks whether your chosen cue supports a useful act. Reading once is optional preparation; the later behavior is what serves the task."]},{heading:"Recurring context is not an instant habit",paragraphs:["Lally and colleagues followed ninety-six volunteers who chose an eating, drinking or activity behavior tied to a recurring context. They tracked repetition and automaticity for eighty-four days. Of eighty-two participants with sufficient data, thirty-nine had acceptable models; their estimated times to near-maximum automaticity varied widely. Some estimates extended beyond observation. The median sixty-six days was not a deadline for every behavior. (suggestion-S09)","This was an observational habit study, not a trial of Coué’s formula, bedtime repetition or an application-writing routine. ODA’s lunch cue and short minimum are design choices. One attempt can show that the cue occurred and the piece was possible; it cannot establish the sentence caused success or that the routine will be automatic by Friday. Keep preparation, cue occurrence and the actual task output distinct when reviewing tomorrow’s record."]}],sourceIds:["suggestion-S15","suggestion-S09"]}},{schemaVersion:2,revision:2,id:"suggestion-3",courseId:"suggestion",locale:"en",title:"Let your value face the feedback",goal:"If feedback blocks your task, connect one chosen value to an actual correction.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Protecting your confidence by avoiding the comments? Let one value guide a real correction.",reason:{id:"suggestion-3-reason",label:"Which useful comment is hardest to use, and what does postponing it cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Vague wording; the reviewer stays confused","Missing date; my application stays incomplete","I need clarification before changing the draft","No usable feedback yet"]},why:{id:"suggestion-3-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Values reflection differs from self-praise. Research pairing it with health information found small average benefits in message acceptance and later behavior. A short values note alone is not proven to improve every task or your mood.","Use this when your record shows feedback avoidance. Keep the task. An optional value, such as learning, can guide one correction. Use “Check this fact,” then correct it or request clarification. Mixed motives and inherited responsibilities count. No perfect reason, agreement with every comment or improved confidence is required."],example:{title:"Maya uses a correction",text:"At her lunch cue, Maya sees a comment that her application sentence is vague. Learning matters to her, but she wants to close the document. She uses “Add one specific example” and revises the sentence with a real task she completed. The whole draft still needs work. She records the correction rather than claiming new confidence from her value."}},move:{invitation:"Keep the named task; suggestions show Maya’s feedback correction.",instructions:["Keep your saved act and cue; identify the comment and its actual correction.","A value may help; correcting or requesting clarification supplies the act."],prompts:[],suggestions:{action:["Add one work example to the application sentence","Ask reviewer which application sentence needs detail"],minimum:["Save the application sentence with one example","Send the application-detail clarification question"],cue:["When lunch ends","When the reviewer’s comment arrives"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Add one known work fact without defending","Ask reviewer which detail needs clarification"],observation:["The corrected sentence or actual clarification question","Whether I used the relevant feedback"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Add one work example to the application sentence",minimum:"Save the application sentence with one example",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I want to defend the whole draft instead",fallbackHint:"Add one known work fact without defending",observationHint:"The corrected sentence or actual clarification question"},stopRule:"Keep boundaries around hostile or unsafe feedback; choose protection or support when needed.",accessibleAlternative:"Choose a private value, neutral instruction or assistance; values writing is optional."},result:{question:"Did you make the correction or ask your question?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-3-decision",scenario:"Maya’s safe reviewer identifies one vague sentence. She has a concrete example and values learning, but feels defensive.",question:"What fits this attempt?",options:[{id:"suggestion-3-strengths",text:"List her strengths first, then revisit the sentence when the criticism feels easier.",feedback:"Strengths reflection may be a preference, but the usable example is available now. Her value can guide one correction without making comfort an entry requirement."},{id:"suggestion-3-correct",text:"Use “Add one example” and revise the sentence with the fact she has.",feedback:"This turns learning into a concrete choice on the same task. The correction is observable evidence; it does not require improved mood or agreement with every comment."},{id:"suggestion-3-reassure",text:"Ask the reviewer to confirm her overall ability before making the specific correction.",feedback:"Reassurance could feel helpful, but overall ability is not the missing information. Use the specific comment and available fact; request clarification only when details are unclear."}],bestOptionId:"suggestion-3-correct"}},carry:{takeaway:"A value becomes useful when it guides a choice you actually make.",followUp:{questionId:"suggestion-3-return",question:"Did you make the correction or clarification request, and what is still unclear?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Values reflection has context-specific evidence",paragraphs:["Epton and colleagues combined self-affirmation tests paired with health information. They found small average effects on message acceptance, intentions and behavior. The 144 tests span outcomes and are not necessarily 144 distinct studies; their participant totals must not be summed as unique people. Values reflection in that setting is different from chanting praise or claiming excellence before looking at feedback. (suggestion-S02)","A newer review by Zhang and colleagues reported small well-being benefits across sixty-seven articles and 129 independent tests in nonclinical populations. The available institutional abstract gives a broad summary, without the full methods needed to assess the precise effect metric, participant total, confidence intervals or follow-up durations. This broadens the context beyond health messages, but does not establish a benefit from today’s brief value-and-correction exercise or a particular affirmation script. (suggestion-S05)"]},{heading:"Use a value without making a universal promise",paragraphs:["A large middle-school replication by Hanselman and colleagues found no significant targeted grade-point benefit from values affirmation in its new cohort. The reported precision could reject benefits of at least .10 standard deviations. This does not mean all values reflection is useless or disprove health-message findings; it means context, population and outcome matter. A school result cannot promise adult confidence or a general performance boost. (suggestion-S12)","ODA’s practical question is narrower: does remembering a value help you use one relevant piece of feedback on your continuing task? A brief optional note and this specific correction are adaptations. You can care about learning, responsibility to family or getting a job for several reasons at once. No motive-purity test is needed. Keep useful feedback distinct from insults or unsafe demands, and record the actual correction or help request rather than a more positive self-description."]}],sourceIds:["suggestion-S02","suggestion-S05","suggestion-S12"]}},{schemaVersion:2,revision:2,id:"suggestion-4",courseId:"suggestion",locale:"en",title:"Nervous? Give yourself clear advice.",goal:"If self-focused worry blocks participation, try name-based reflection and use your prepared line.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Know your point but keep rehearsing your nerves? Address yourself once, then use the point.",reason:{id:"suggestion-4-reason",label:"What does more self-analysis give you, and what opportunity could it cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Polished wording; miss the reviewer’s invitation","Brief reassurance; postpone the ready question","An unclear question still needs preparation","No prior missed opening"]},why:{id:"suggestion-4-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["In short social-stress experiments, people reflected using their name or “you” rather than “I.” One study found better observer-rated interaction performance, without a significant reduction in anxiety beforehand. Perspective is not a command to remove nerves.","If self-focused worry blocked your task, keep the facts matched: “I’m prepared and nervous” becomes “Maya is prepared and nervous.” Add one useful instruction, then use your line in the safe interaction. Keep an earlier instruction if it works. Name-based reflection is optional preparation; participation is the actual attempt."],example:{title:"Maya asks the reviewer",text:"Maya has a prepared question about her application, but her lunch record shows she kept analyzing how she would sound. Before a safe call, she says, “Maya is prepared and nervous. Ask about the example.” She asks her question. The reviewer needs time to answer. Maya records the participation and pending reply, not a pronoun trick that erased anxiety."}},move:{invitation:"Keep your actual act; suggestions show a reviewer question.",instructions:["Keep the named action and cue; reflection is optional preparation.","For a first interaction, name the actual question and a safe opening.","Ask or share the prepared line; you can use ordinary first-person wording."],prompts:[],suggestions:{action:["Ask reviewer which work example the application needs","Share the application sentence with the reviewer"],minimum:["Ask which work example is missing","Send the application sentence for review"],cue:["When the reviewer invites questions","When lunch ends"],place:["In the scheduled review call","In the reviewer’s message thread"],minutes:[2,1,3],fallback:["Ask “Which work example is missing?” now","Send reviewer the work-example question"],observation:["Whether I actually asked the work-example question","The response, including a pending reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask reviewer which work example the application needs",minimum:"Ask which work example is missing",minutes:2,cueHint:"When the reviewer invites questions",placeHint:"In the scheduled review call",obstacleHint:"I continue analyzing instead of asking the ready question",fallbackHint:"Ask “Which work example is missing?” now",observationHint:"Whether I actually asked the work-example question"},stopRule:"Pause unsafe interactions. Seek qualified support for persistent distress or severe impairment.",accessibleAlternative:"Use a safe written, signed or assisted line; name-based reflection is optional."},result:{question:"Did you use your prepared line in the interaction?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-4-decision",scenario:"Maya has a clear application question. Her scheduled reviewer invites it now before the call ends. She is nervous and has already reflected briefly.",question:"What fits this attempt?",options:[{id:"suggestion-4-name",text:"Rehearse privately once more to polish the wording, then ask at the reviewer’s next invitation.",feedback:"One rehearsal may polish the wording. Her question is already clear, and the call is ending. Use this safe opening; name-based reflection is optional, and a factual first-person instruction also works."},{id:"suggestion-4-analyze",text:"Explain the nervousness privately in more detail before deciding whether to participate.",feedback:"Detailed reflection can help another question, but it prolongs preparation here. Her current bottleneck is using the ready line while the safe opening is available."},{id:"suggestion-4-use",text:"Use “Maya is prepared and nervous,” then ask her actual question.",feedback:"This preserves the facts and ends preparation in participation. The laboratory evidence does not promise less anxiety beforehand; record the actual line and response."}],bestOptionId:"suggestion-4-use"}},carry:{takeaway:"Perspective should end in advice and an act, not another round of self-analysis.",followUp:{questionId:"suggestion-4-return",question:"Did the perspective prompt end in your real line or more preparation?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Change perspective without changing the facts",paragraphs:["Kross and colleagues conducted seven experiments with 585 people, mostly in student and social-evaluation settings. In Study 2, participants reflected alone for three minutes before meeting an unfamiliar person. The experimental instruction used their own name and non-first-person pronouns; the comparison used “I” and “me.” The name-based group had better observer-rated interaction performance. Preinteraction anxiety did not significantly improve; recovery afterward was clearer. (suggestion-S03)","The honest illustration keeps content matched. Compare “I’m prepared and nervous; start with the first fact” with “Maya is prepared and nervous; start with the first fact.” Comparing harsh first-person criticism with kind name-based advice would also change kindness, so it cannot isolate perspective. ODA’s brief advice-and-line version is an adaptation, not the three-minute protocol or a treatment for social anxiety."]},{heading:"Clear advice still needs an opening",paragraphs:["The short experiments do not establish a lasting benefit, a required pronoun or a universal advantage in every setting. Ordinary first-person thinking is not itself harmful. You may prefer “I can ask the question,” neutral instructions or no reflection. The continuing course experiment still concerns the useful task you chose, not speaking to yourself in a particular grammatical form. (suggestion-S03)","Save the real interaction as the act when that is your next task step. If you only prepare the line, record preparation rather than inventing participation. A missing opening can be reported as no occasion. Persistent distress, severe impairment or self-harm thoughts warrant qualified help; name-based reflection does not replace it. Protect yourself in unsafe situations and use appropriate local support. No pronoun change makes abuse safe or removes a need for care. (suggestion-S20)"]}],sourceIds:["suggestion-S03","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-5",courseId:"suggestion",locale:"en",title:"After the error, name the next move",goal:"If your task has a recurring error, test one specific cue on an actual item.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Another mistake, another verdict about yourself? Give the next attempt one concrete instruction.",reason:{id:"suggestion-5-reason",label:"After your last error, which judgment delayed the actual correction?",kind:"text",maxLength:160,optional:!0,suggestions:["“I am careless”; left the date unchanged","“This draft is hopeless”; stopped checking","No judgment delayed my correction","No prior error; I may judge myself"],help:"No prior error? Name a judgment that could delay fixing the next one."},why:{id:"suggestion-5-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sports self-talk studies found an average performance benefit across varied tasks and training methods. Instruction sometimes fit precision tasks better, but comparisons do not establish universal superiority over encouragement or the same effect in office work.","Check your task record. For a recurring detail, name its cue: “Check the date.” If needed, try an easy practice item, then one real item. Record them separately. When you do not know how to fix the error, request instruction. Stronger motivation cannot supply missing knowledge or complete the correction."],example:{title:"Maya checks the date",text:"Maya’s application draft has two inconsistent dates. At the lunch cue, she says “Check the date.” She tries one copied example as preparation, then checks and corrects one real date in her draft. A second discrepancy remains. She records the actual correction and asks for guidance on the unclear entry, without claiming the cue solved the whole draft."}},move:{invitation:"Keep your actual item and cue; suggestions show an application-date correction.",instructions:["Keep the saved item and opening; name its actual checking instruction.","For the example, use “Check the date” and correct one application entry.","If the procedure is unknown, choose Adapt to request specific instruction."],prompts:[],suggestions:{action:["Use “Check the date”; correct one application entry","Compare one application date with the original record"],minimum:["Save one corrected date in the application","Record whether the application date matches"],cue:["When lunch ends","When I reach the application’s dates section"],place:["At my kitchen table","In the application draft"],minutes:[3,2,1],fallback:["Ask reviewer how to verify the date","Check the original dated work record"],observation:["The actual date correction or instruction request","Practice item separately from real work"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “Check the date”; correct one application entry",minimum:"Save one corrected date in the application",minutes:3,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I do not know how to verify the correct date",fallbackHint:"Ask reviewer how to verify the date",observationHint:"The actual date correction or instruction request"},stopRule:"Need instruction? Choose Adapt this, then Support. For consequential tasks, get appropriate professional guidance.",accessibleAlternative:"Use a written cue, accessible example, dictation or assistance."},result:{question:"Did you correct a real item or request instruction?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-5-decision",scenario:"Maya knows how to check a date but repeatedly skips that step. One real application entry needs correction.",question:"What fits this attempt?",options:[{id:"suggestion-5-drive",text:"Use “Keep going” while completing the remaining batch to preserve momentum.",feedback:"Momentum matters, but this record identifies a skipped check. Name that detail and test it on one real entry rather than carrying the same error through the batch."},{id:"suggestion-5-detail",text:"Use “Check the date” on one real entry, then correct it.",feedback:"The cue matches the observed bottleneck and produces an actual correction. This personal trial gives feedback about fit, not proof of the cue’s causal effect."},{id:"suggestion-5-all",text:"Write a short checklist for dates, labels and formatting before returning to the application entry.",feedback:"A short checklist can prevent several omissions. This record names one skipped date check, and Maya knows the procedure. Correct that real entry first; add other checks when they address observed needs."}],bestOptionId:"suggestion-5-detail"}},carry:{takeaway:"Correct the next workable detail; ask for instruction when the skill is missing.",followUp:{questionId:"suggestion-5-return",question:"What happened with the correction or instruction request, and what detail still needs checking?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A sport average is not an office promise",paragraphs:["Hatzigeorgiadis and colleagues’ meta-analysis pooled thirty-two studies and sixty-two effects. The primary table reported 2,741 participants. The overall corrected standardized performance difference was .48, with a confidence interval from .38 to .58. Studies involved sport and motor tasks, including students and athletes; some designs lacked controlled comparisons. A pooled sport result cannot specify what will happen in your application draft or choose a checking rule for you. (suggestion-S04)","Subgroup estimates varied for fine and gross motor tasks, instructional and motivational wording, and prior training. Those are not randomized dose comparisons or a universal technique ranking. They do not predict a .48 benefit for a spreadsheet, application or conversation. Today’s one-cue, one-real-item trial is an ODA transfer experiment. Keep a favorable result modest: it shows what happened on that item, not why it happened or what every later attempt will do."]},{heading:"Instruction has to name a usable detail",paragraphs:["The cue should answer the actual problem in your record. “Check the date” names a step; “be excellent” does not explain how to correct one. An easy example can prepare the cue, but it is not completion of the real item. If a procedure is unfamiliar, a concrete request for instruction is a useful act in its own right. The sport review does not validate Gallwey’s whole framework, two literal neural selves or an unverified historical script. (suggestion-S04)","You may change the cue after observing a mismatch, retain it after a workable attempt or stop using self-talk if it adds pressure. Do not introduce several new instructions simply to create a more impressive plan. ODA’s record is a way to identify the bottleneck, not a grade on character. Persistent or severe distress warrants qualified support rather than stronger repetition. (suggestion-S20)"]}],sourceIds:["suggestion-S04","suggestion-S20"]}},{schemaVersion:2,revision:2,id:"suggestion-6",courseId:"suggestion",locale:"en",title:"Let bedtime be bedtime",goal:"If tomorrow’s obstacle is unclear, plan earlier and save the actual task attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bedtime pep talk keeping you awake? Give tomorrow a cue while you are awake.",reason:{id:"suggestion-6-reason",label:"What needs a plan, and what needs rest?",kind:"text",maxLength:160,optional:!0,suggestions:["Lunch is crowded; choose another daytime cue","The plan is ready; stop bedtime checking","I have no observed planning problem yet"]},why:{id:"suggestion-6-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sleep helps process memories; this does not establish a special window for subconscious commands. Outcome, obstacle and response planning has evidence across goals, but research does not validate bedtime fantasy followed by next-morning planning.","Address an unhandled obstacle earlier while awake. Name the desired result, obstacle and feasible response together. Keep the same useful task piece as the act. Planning is preparation; save and record the later attempt separately. Stop bedtime thinking if it increases wakefulness. No scene, gratitude feeling or repetition is required to make the plan valid."],example:{title:"Maya plans before dinner",text:"At 6:30, Maya wants tomorrow’s application sentence, but expects breakfast to be crowded. She chooses the lunch cue and a response: dictate a sentence if her table is occupied. The note is preparation. Next day the table is busy, so she dictates one usable sentence. She records the actual output. At bedtime she leaves the plan alone."}},move:{invitation:"Keep your named task; suggestions show Maya’s daytime writing example.",instructions:["Keep the saved act, minimum, and cue unless one obstacle needs a change.","Plan outcome, obstacle, and response together while awake; record the later act separately."],prompts:[],suggestions:{action:["Write one application work-experience sentence after lunch","Dictate the application work-experience sentence after lunch"],minimum:["Save one factual application sentence","Save one dictated work-experience sentence"],cue:["When lunch ends","After my morning drink"],place:["At my kitchen table","In the application draft"],minutes:[2,1,3],fallback:["Dictate the application sentence at lunch","Write the experience sentence after dinner"],observation:["Whether the table was available and fallback used","The actual application sentence after preparation"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one application work-experience sentence after lunch",minimum:"Save one factual application sentence",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"My kitchen table is occupied",fallbackHint:"Dictate the application sentence at lunch",observationHint:"Whether the table was available and fallback used"},stopRule:"Stop bedtime planning if it increases wakefulness. Preserve rest and seek appropriate help for persistent concerns.",accessibleAlternative:"Plan by typing, speaking or assistance while awake; imagery is optional."},result:{question:"Did you do the actual piece at your cue?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-6-decision",scenario:"Maya has a written lunch plan. In bed, imagining tomorrow turns into repeated anxious checking and she feels more awake.",question:"What fits this attempt?",options:[{id:"suggestion-6-finish",text:"Complete the obstacle analysis in bed so tomorrow’s plan feels fully settled.",feedback:"Completeness is tempting, but a workable plan is already written and this checking increases wakefulness. Stop now; review details earlier while awake if they need changing."},{id:"suggestion-6-stop",text:"Stop the scene, leave the written cue in place, and return to rest.",feedback:"This protects rest without discarding tomorrow’s feasible act. Sleep-memory findings do not establish a required bedtime ritual. The later task attempt gets its own record."},{id:"suggestion-6-replace",text:"Replace the scene with a repeated positive phrase until the checking quiets.",feedback:"A different ritual may continue the same wakeful effort. No repetition is required to make the plan valid. Leave the cue in place and stop planning now."}],bestOptionId:"suggestion-6-stop"}},carry:{takeaway:"Make the plan while awake. Let rest and the later act have separate records.",followUp:{questionId:"suggestion-6-return",question:"Did the obstacle response support your actual act without extending bedtime effort?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Sleep science does not certify a ritual",paragraphs:["Paller, Creery and Schechtman’s review discusses reactivation of previously learned material during sleep and limited simple associative learning. It is a narrative synthesis with no pooled effect for self-help suggestion. Memory processing does not establish an uncritically receptive subconscious before sleep, a drowsy advantage for affirmations or complex skills installed by a phrase. Those are different claims. (suggestion-S10)","Murphy’s publisher synopsis establishes book provenance and promotes belief and imagination. The publisher’s synopsis does not establish that Murphy’s bedtime ritual works. It supplies no controlled evidence for the named package and cannot validate a specific repetition script. If planning adds wakefulness, move any needed planning to an earlier daytime opportunity and leave bedtime for rest. A voluntary daytime image is still an ODA choice, not evidence of attraction, healing or a special bedtime mechanism. (suggestion-S16)"]},{heading:"Keep outcome, obstacle and response together",paragraphs:["Wang and colleagues’ meta-analysis of mental contrasting with if–then plans included twenty-one articles, twenty-four independent effects and 15,907 participants. It found an average goal-attainment benefit; publication-bias adjustment reduced the estimate. Goals, methods and comparisons varied. The result does not isolate a positive sentence as the active ingredient or validate the assembled ODA suggestion card. (suggestion-S06)","Use the contrast to answer a concrete planning problem: what outcome matters, what obstacle is likely, and what response is feasible? Work through those parts together, then save the actual task piece with its cue. A note about tomorrow is preparation today, not tomorrow’s completed work. If the obstacle requires resources, safety or assistance, choose that practical response rather than blaming belief. Moving planning earlier protects the opportunity for rest; the research did not test a bedtime-fantasy and next-morning-plan split."]}],sourceIds:["suggestion-S10","suggestion-S16","suggestion-S06"]}},{schemaVersion:2,revision:2,id:"suggestion-7",courseId:"suggestion",locale:"en",title:"Count the moves, not the card reads",goal:"Consolidate your same task records and choose the next workable instruction-and-action attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reminder read, task untouched? Review actual pieces, or plan a first trial.",reason:{id:"suggestion-7-reason",label:"What will you keep, change or stop from your records?",kind:"text",maxLength:160,optional:!0,suggestions:["Lunch worked; keep that opening","Morning was crowded; change that cue","Repetition added pressure; stop repeating","No attempt recorded; choose a first act"]},why:{id:"suggestion-7-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A credible sentence, cue and obstacle response can fit together, but this assembled card is not validated as a package. Planning research does not establish that card reading causes action.","Review your task, or choose a first trial. Separate reminder reads, preparation, actual acts and returns. Keep acceptable wording and a workable cue; change one observed bottleneck. Save the same act and minimum for the next opportunity. Later dates stay plans until reported. If wording adds pressure, simplify or stop it. No mirror, new ritual or stronger belief is required."],example:{title:"Maya’s next week",text:"On Sunday, Maya sees five reminder reads and three useful application pieces. Two missed starts used a crowded morning cue; lunch worked twice. She keeps “Write the first fact,” drops extra imagery and schedules Monday’s lunch attempt. On Monday she writes a sentence that still needs editing. She records the piece and keeps next week’s other dates as plans."}},move:{invitation:"Keep your chosen act and minimum; suggestions are application examples.",instructions:["Keep the actual act, minimum, cue, and place; change only the observed bottleneck.","With no record, name a first act and its matching minimum before saving.","Use Adapt for a support request; later dates remain plans."],prompts:[],suggestions:{action:["Use “Check the date”; correct one application entry","Compare one application date with the original record"],minimum:["Save one corrected date in the application","Record whether the application date matches"],cue:["When lunch ends","When I reach the application’s dates section"],place:["At my kitchen table","In the reviewer’s message thread"],minutes:[2,1,3],fallback:["Stop reading; verify one application date","Ask reviewer which date source to use"],observation:["Actual corrections separately from card reads","Whether the lunch opening and instruction fit"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “Check the date”; correct one application entry",minimum:"Save one corrected date in the application",minutes:2,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"I keep reading instead of checking the application date",fallbackHint:"Stop reading; verify one application date",observationHint:"Actual corrections separately from card reads"},stopRule:"For task help, choose Adapt this, then Support. Stop distressing wording; seek qualified care for persistent distress or impairment. Keep prescribed care.",accessibleAlternative:"Use a private accessible note, neutral wording or assistance; no mirror required."},result:{question:"Did you do the next piece or chosen support act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"suggestion-7-decision",scenario:"Maya read her card daily but wrote once at lunch. Mornings were crowded; the instruction still felt credible.",question:"What fits this attempt?",options:[{id:"suggestion-7-repeat",text:"Preserve the morning plan because daily card reading shows the routine is taking hold.",feedback:"Daily reading is a real process record, but it is not the chosen writing outcome. Her cue rarely led to work. Test the lunch opportunity instead."},{id:"suggestion-7-increase",text:"Add an evening reading so the credible sentence becomes easier to recall.",feedback:"Recall may matter, but the available evidence points to crowded mornings. More reading changes repetition while leaving the task cue unchanged; test the observed bottleneck first."},{id:"suggestion-7-revise",text:"Keep the credible sentence, use lunch, and schedule one actual writing piece.",feedback:"This preserves what fit and changes the cue linked to missed starts. The next piece remains a plan until reported; use tomorrow’s return to judge the new attempt."}],bestOptionId:"suggestion-7-revise"}},carry:{takeaway:"Keep useful words only with a workable act, an honest record and a next choice.",followUp:{questionId:"suggestion-7-return",question:"What happened with your chosen act or support request, and what needs to change?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"The assembled card is a design choice",paragraphs:["The course joins credible wording, one cue, an actual task piece, an obstacle response and a return record. This combination is an ODA design, not a controlled intervention package. Wang and colleagues’ review supports mental contrasting with if–then plans across varied goals, but does not establish that every card ingredient helps or that reading the card is the cause of any completed task. (suggestion-S06)","Use the card as a compact reminder of your saved plan rather than a new requirement. Review preparation separately from the useful piece. A card read can be reported honestly without counting it as writing, asking or correcting. Keep one observed bottleneck in view so the next trial answers something specific. A favorable personal record is feedback about fit, not causal proof or a guarantee that the same plan will work in every week."]},{heading:"No new ritual is needed at the finish",paragraphs:["Lally’s observational habit study concerned eating, drinking and activity behaviors repeated at recurring cues. It did not test positive phrases or guarantee a deadline for automaticity. ODA’s next-week opportunities and review interval are choices for organizing your experiment, not a tested dose or a requirement for an unbroken streak. Actual task attempts remain separate from learning completion. (suggestion-S09)","Hay’s author page describes mirror statements and a twenty-one-day program. No controlled study of that named package was located in the evidence review; this does not prove it has never been studied. Mirror delivery has no established superiority here, and twenty-one days is not a habit deadline. A private note, accessible reminder or no card can suit your preference. Finish by carrying your same useful task forward, adjusting from records and protecting safety, rest and prescribed care. (suggestion-S18)"]}],sourceIds:["suggestion-S06","suggestion-S09","suggestion-S18"]}}],N=[{id:"suggestion-1",practice:["Name one ordinary situation you would like to approach differently this week.","Compare the familiar critic sentence with a credible neutral instruction; imagery and encouragement are optional.","Try the instruction with one useful task piece; note the actual behavior and any pressure separately."],reflection:"Which sentence do you say to yourself most often, and how does it affect you?",question:"How is suggestion defined in this course?",options:["A secret command sent to the subconscious that changes everything by itself.","Repeating a chosen sentence, an image and a small action together.","A thinking technique that can replace medication or treatment."],correct:1,feedback:"The course uses an untested instruction-and-action experiment; imagery is optional. Clinical expectation studies do not validate the combined routine. Suggestion does not replace treatment or guarantee external results.",photo:{id:"1461468611824-46457c0e11fd",alt:"Woman sitting and looking out at the sea"}},{id:"suggestion-2",practice:["If you choose to explore Coué’s historical ritual, check that the wording is acceptable; counting materials are optional.","His 1922 English text described twenty quiet repetitions; this is history, not a proven dose or required bedtime practice.","If you voluntarily try wording, stop for distress or wakefulness and keep phrase reading separate from actual task action."],reflection:"How did it feel to say the formula without forcing it: soothing, strange, boring?",question:"Which of these fits the attitude Coué recommended for his formula?",options:["Saying the sentence as forcefully as possible, through gritted teeth.","Saying the sentence in a relaxed, low voice and leaving the counting to the string or beads.","Checking after every repetition whether something has changed."],correct:1,feedback:"Coué recommended relaxed repetition in his historical account. Anecdotes do not establish a universal imagination law, an effective twenty-repetition dose or disease cures. The opened English edition is from 1922.",photo:{id:"1762328490563-9b9c300fba3e",alt:"Person holding a string of beads"}},{id:"suggestion-3",practice:["Choose a positive sentence or a neutral task instruction you find acceptable.","Optionally rate credibility to guide wording, without a clinical cutoff; edit or stop if it adds distress.","Optionally reflect on an important value, then choose one concrete task action that serves it."],reflection:"Which sentence makes you think, “yes, that could be true”?",question:"With mixed findings about positive self-statements, which wording can you choose to test?",options:["Repeating the boldest sentence more often, even if you do not believe it.","Choosing a sentence you can believe that describes a process.","Never saying any positive sentence to yourself."],correct:1,feedback:"The early backfire report was not reproduced in two later studies. Neutral or process wording is a voluntary preference, not proven safer treatment. Credibility scores do not diagnose self-esteem.",photo:{id:"1616628188467-8fb29f49bbe8",alt:"Hand writing a note on white paper"}},{id:"suggestion-4",practice:["Pick a moment this week that will be hard for you, and note its time.","Before that moment, take two minutes to describe the situation to yourself, calling yourself by name.","Then say to yourself the supportive sentence you would say to a friend in the same situation."],reflection:"How did your tone change when you called yourself by name?",question:"In Kross’s 2014 experiments, which kind of self-talk was more helpful under social stress?",options:["Calling yourself by name or “you”.","Thinking about the situation at length, using only “I”.","Motivating yourself with harsh criticism."],correct:0,feedback:"Short social-stress experiments found better observer-rated performance with name or non-first-person reflection. Study 2 did not significantly reduce anxiety before interaction; recovery afterward was clearer. This is not treatment.",photo:{id:"1641907173006-6b8930ae1191",alt:"Woman looking up at the sky, lost in thought"}},{id:"suggestion-5",practice:["Choose a task this week that you find hard to learn or to do well.","Write one instructional and one motivational cue word for that task.","While doing the task, repeat the cue in a short, calm voice, and note the result without judging it."],reflection:"Which cue actually drew your attention into the task?",question:"According to the meta-analysis, when did instructional self-talk work especially well?",options:["In tasks that need fine skill and attention.","Only in very well-learned, automatic tasks.","On the first attempt only, with no practice at all."],correct:0,feedback:"In sport studies, instructional cues often fit fine or new tasks; some designs were uncontrolled. Task and training subgroup comparisons do not prove a universal ranking, optimal dose or equivalent office-work benefit.",photo:{id:"1523497804259-88c4c134ca90",alt:"Athlete getting ready to run on a track"}},{id:"suggestion-6",practice:["While awake earlier in the day, name your desired outcome and one real obstacle together.","Choose a feasible obstacle response and an actual useful task piece; optional imagery remains preparation.","Save the actual task cue and record its later attempt separately. Stop bedtime planning if it increases wakefulness."],reflection:"What did the scene you built before sleep remind you of in the morning?",question:"Which preparation keeps the suggestion claims within the evidence?",options:["Imagining the result and also adding the real obstacle and an if–then plan.","Waiting for the subconscious to attract money and health by itself during sleep.","Only imagining the good outcome and making no plan at all."],correct:0,feedback:"Outcome, obstacle and response planning has evidence across varied goals. That does not validate a special drowsy ritual or a bedtime-fantasy and next-morning-plan split. Preserve sleep; later action is separate.",photo:{id:"1757796859729-270d1e3ad4d5",alt:"Open book on a nightstand under a lit lamp"}},{id:"suggestion-7",practice:["If a card is useful, write your credible instruction and optional first-step image; use an accessible private format.","Add your actual task cue and feasible obstacle response; reading the card is not doing the task.","Choose a review date, then compare actual attempts with preparation after they occur; a week is not a validated dose."],reflection:"After seven days, what on your card would you keep exactly as it is, and what would you change?",question:"When you review your suggestion card after seven days, which approach is most useful?",options:["Blaming yourself if nothing has changed.","Looking at what worked and adjusting the sentence, the image or the plan.","Starting to say a bolder sentence more loudly."],correct:1,feedback:"Review actual task attempts separately from card reads. The combined card is untested; keep useful wording and change an observed bottleneck without requiring mirrors, stronger belief or a new ritual.",photo:{id:"1484480974693-6ca0a78fb36b",alt:"Hand writing a checklist in a notebook"}}],K={id:"suggestion",title:"Inner critic stalling you? Give it a useful job",subtitle:"Seven short lessons. Use credible words for one useful act, then revise from what actually happened.",description:"Choose one meaningful task and test a believable instruction alongside real action. Improve its cue, use feedback, address an observed obstacle and carry the same experiment into next week.",scope:"A course in self-suggestion and self-talk for adults. It is not hypnotherapy, diagnosis or treatment. Suggestion does not replace medication or any treatment you are receiving; do not stop a medication or treatment without talking to your doctor. The claims in some books that suggestion cures illness or attracts money are not supported by research. If the negative sentences inside you are very intense, or you have felt low for a long time, reach out to a mental health professional. If you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"A credible instruction tied to a useful task, an honest action record, and a next attempt shaped by evidence from your day.",photo:{id:"1779922811108-245a9403ef44",alt:"Silhouette of a person standing on a hilltop at dawn"},lessons:p.map((e,t)=>({...N[t],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"suggestion-S20",...e.id==="suggestion-3"?["suggestion-S07","suggestion-S08"]:[]])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"One continuing experiment",steps:[{label:"Cue",text:"Choose a workable opening."},{label:"Act",text:"Try the useful minimum."},{label:"Return",text:"Record and choose the next attempt."}]}}))},X=Object.freeze(Object.defineProperty({__proto__:null,COURSE:K,SOURCES:U,SUGGESTION_LESSONS_V2:p},Symbol.toStringTag,{value:"Module"})),F="state",L=[{id:"state-emotion-decisions",title:"Lerner et al. · 2015 · Emotion and decision making · Dossier ST01",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Narrative review of approximately 35 years of research: emotions can influence decisions, including carryover from unrelated situations. Effects may help or harm depending on the emotion and decision.",limitation:"No pooled estimate. Does not validate a three-part state mechanism, universal optimal mood, or one-minute reset."},{id:"state-regulation-meta",title:"Webb, Miles & Sheeran · 2012 · Emotion-regulation strategies · Dossier ST02",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"Across 306 experimental comparisons, cognitive change averaged d = 0.36, response modulation 0.16, and attentional deployment 0.00. Subcategories and emotional outcomes differed.",limitation:"Mostly experimentally elicited emotion, not treatment populations. Expression and experience differ. Does not validate named question scripts or a universally best strategy."},{id:"state-acute-exercise",title:"Reed & Ones · 2006 · Acute exercise and energetic feelings · Dossier ST03",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 studies, 450 effects, 13,101 participants: average corrected exercise-associated change in energetic positive feelings was 0.47. Control-condition change was separately reported as -0.17.",limitation:"These separately reported changes are not a randomized treatment contrast. Mostly healthy volunteers with heterogeneous responses. No proven two-minute dose or depression treatment."},{id:"state-exercise-mental-health",title:"Singh et al. · 2023 · Physical activity and distress · Dossier ST04",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"97 reviews covering 1,039 unique randomized trials and more than 128,119 participants found average symptom reductions. Median depression and anxiety effects were -0.43 and -0.42.",limitation:"77 reviews were critically low quality. Longer programs differ from brief movement. Distress -0.60 came from one review of six trials with 508 participants; another small trial was nonsignificant."},{id:"state-facial-feedback",title:"Coles, Larsen & Lench · 2019 · Facial feedback · Dossier ST05",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 studies and 286 effects: overall d = 0.20, 95% CI 0.14 to 0.26, combining emotional experience and affective judgments. Effects were small and variable.",limitation:"Published count is 138, not 136. Some judgment effects showed publication-bias signals. Does not establish smiling as a reliable distress treatment."},{id:"state-cyclic-sighing",title:"Balban et al. · 2023 · Brief respiration practices · Dossier ST09",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 randomized adults, mostly recruited from a Stanford undergraduate psychology class, practiced five minutes daily for 28 days. Modeling favored breathing for positive affect.",limitation:"Exploratory, retrospectively registered trial. Does not establish anxiety superiority, a two-breath dose, durability, or treatment efficacy."},{id:"state-affect-labeling",title:"Lieberman et al. · 2007 · Affect labeling · Dossier ST11",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 healthy adults labeled emotions on faces during brain imaging. Emotion-word versus gender-name labeling differed on an amygdala measure, with reported d = 0.79.",limitation:"Not a subjective distress-recovery outcome. Does not establish benefits of milder vocabulary, self-labeling, lasting symptom relief, or this worksheet."},{id:"state-gratitude-expressed",title:"Kirca, Malouff & Meynadier · 2023 · Expressed gratitude · Dossier ST13",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 studies and 25 randomized samples: positive wellbeing g = 0.22 against neutral controls. Against bona fide activities, g = 0.12 with a confidence interval including zero.",limitation:"Article participant totals conflict, so no exact N is taught. Does not validate a morning priming package, future-scene imagery, or superiority to credible alternatives."},{id:"state-positive-self-statements",title:"Wood et al. · 2009 · Positive self-statements · Dossier ST12",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Early university-sample experiments suggested different responses to repeated positive statements depending on self-esteem, including possible poorer responses for some participants.",limitation:"Later replication attempts did not reproduce mood, state-esteem, or moderation findings. Neither universal benefit nor universal harm is established. No evidence of incantation superiority."},{id:"state-mental-contrasting",title:"Wang, Wang & Gai · 2021 · Goal attainment · Dossier ST15",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 articles, 24 independent effects, 15,907 participants: mental contrasting with response planning showed g = 0.336, with a smaller publication-bias-adjusted estimate of 0.242.",limitation:"Heterogeneous studies and possible publication bias. Does not validate Dickens imagery, shame, rigid must language, or causal delivery-format superiority."},{id:"state-self-compassion-motivation",title:"Breines & Chen · 2012 · Improvement motivation · Dossier ST16",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Four short experiments supported compatibility of compassion and improvement motivation. After test failure, study time averaged 306.5 seconds versus 203.2 with no reminder.",limitation:"Second-test scores did not significantly differ; the self-esteem comparison was inconclusive. Does not prove sustained change, actual repair, or Dickens efficacy."},{id:"state-nhs-panic",title:"NHS · Panic disorder · Dossier ST18",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Recurrent unexpected panic warrants professional assessment. Established treatment options include cognitive behavioral therapy and medication.",limitation:"Guidance, not a coaching-effect study. ODA cannot diagnose panic or assume new chest pain, fainting, or unexplained breathing difficulty is harmless anxiety. Use appropriate medical or emergency help."},{id:"state-affirmation-replication",title:"Flynn & Bordieri · 2020 · Affirmation replication · Dossier ST20",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Two university analogue experiments failed to reproduce earlier mood, state-esteem, or trait-esteem moderation findings for positive affirmations.",limitation:"Null results do not establish equivalence or settle every statement. Two failed replication attempts leave the earlier benefits and self-esteem differences uncertain."}];function s(e){const t=e.suggestions;return{schemaVersion:2,revision:2,id:e.id,courseId:F,locale:"en",title:e.title,goal:e.goal,minutes:{learning:6,suggestedAction:t.minutes[0],review:2},direction:{hook:e.hook,reason:{id:`${e.id}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:e.reasons},why:{id:`${e.id}-why`,label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${e.id}-cost`,label:"What does the current pattern cost you?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:e.invitation,instructions:e.instructions,prompts:[],suggestions:t,suggested:{action:t.action[0],minimum:t.minimum[0],minutes:t.minutes[0],cueHint:t.cue[0],placeHint:t.place[0],obstacleHint:e.obstacle,fallbackHint:t.fallback[0],observationHint:t.observation[0]},stopRule:e.stop,accessibleAlternative:e.accessible},result:{question:e.result,observationPrompt:e.observation},judgment:{primary:e.scenario},carry:{takeaway:e.takeaway,followUp:{questionId:`${e.id}-return`,question:e.follow,observationPrompt:e.followObservation,adjustmentPrompt:"What would make the next attempt fit your life?"}},goDeeper:{sections:e.depth,sourceIds:e.sources}}}const r=[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],m=s({id:"state-1",title:"Do not let one argument write the next",goal:"Notice carried-over emotion, then make one useful request in a safe setting.",hook:"Still angry about the last conversation? Give your next request its own chance.",reason:"What is carryover costing this next conversation?",reasons:["Ask clearly at home","Protect a working relationship","Stop carrying one argument forward"],paragraphs:["A feeling can arrive before the situation it seems to explain. Irritation from a difficult shift may color a repair request at home. Research shows that emotions can carry into unrelated decisions. That does not make the feeling wrong. It asks you to check what it belongs to.","Choose one recurring transition for this course: before a call, a message, or a task you care about. Name the feeling and its likely source. Then make one useful move without demanding calm first. Keep anger that signals real harm in view. A clear request, protection, or support may matter more than changing your mood."],example:{title:"Dana's repair request",text:"At 6 p.m., Dana comes home irritated after a tense shift. A leaking tap needs attention. She notices that her landlord has not caused the argument at work. Seated at the kitchen table, she sends a clear repair request. The reply asks for a photo. She records the request and sends it, still irritated."},invitation:"Pick one useful request at your chosen transition. Notice the feeling, then use your sentence.",instructions:["Name where the feeling may have started.","Make one clear request in a safe setting."],suggestions:{action:["Send one clear repair request","Ask for one needed clarification","Make one practical support request"],minimum:["Send one request sentence","Ask one specific question","Name one support need"],when:r,cue:["Before my next necessary message","At my next safe check-in"],place:["Seated at my kitchen table","In a safe message thread"],minutes:[2,1,5],fallback:["Use a safe written message","Choose a later safe opening"],observation:["My request and the actual reply","Whether I made the request"]},obstacle:"The previous conversation is still on my mind",stop:"If there is real danger, pause and seek protection or support.",accessible:"Keep eyes open. Stay seated, notice the room, and use your usual communication method.",result:"Did you make your chosen request?",observation:"What did you request, and what reply came back?",scenario:{id:"state-1-carryover-request",scenario:"A repair-booking window closes in two minutes. After a tense shift, Dana wants a leak fixed this week. Her landlord has responded reasonably before.",question:"What gives this request a fair start?",bestOptionId:"name-and-request",options:[{id:"pause-then-request",text:"Take a five-minute pause to collect her thoughts, then send the factual request with a repair-date question.",feedback:"A defined pause can help organize a request. Here it misses the booking window, although the message is manageable now. Dana can send a factual date request while irritation remains."},{id:"describe-without-date",text:"Send a concise description of the leak now and let the landlord suggest what happens next.",feedback:"This reports the problem accurately and reaches the open window. It leaves timing unspecified, though Dana needs a repair this week. Asking for a date makes that need visible without demanding agreement."},{id:"name-and-request",text:"Notice the carried-over irritation, describe the leak, and ask clearly for a repair date.",feedback:"This separates the feeling from the evidence about this conversation. Dana makes the needed request and can record the reply. Calm and agreement are not required results."}]},takeaway:"Check where the feeling came from. Let the next request answer its own facts.",follow:"Did noticing carryover change your request, even if your mood stayed the same?",followObservation:"What changed in the request or mood? Unchanged is a valid answer for either.",depth:[{heading:"Emotions can travel between decisions",paragraphs:["Lerner and colleagues reviewed roughly 35 years of research on emotion and decision making. Their account describes incidental emotions: feelings that begin elsewhere and influence a new judgment. Emotions can help as well as hinder decisions. The useful question is whether this feeling supplies information about the present situation or reflects something that happened before it. [ST01: state-emotion-decisions]","That distinction does not ask you to dismiss anger, sadness, or worry. A repeated insult, an unresolved need, and a tiring shift are different facts. Name the current evidence before choosing your response. If you need a repair, ask for a repair. If you need protection, choose protection. This lesson uses an ordinary request to make that decision visible. It does not establish that naming the carryover changes emotion, guarantees cooperation, or solves an unsafe relationship."]},{heading:"A continuing experiment, not a mood test",paragraphs:["For this course, keep one recurring transition and one life direction. Later lessons offer a tool only when your records suggest a problem it could address. You are not collecting seven obligations. The meaningful observation is what you actually requested, started, changed, or stopped at that transition. An unchanged mood and an unanswered message can coexist with a completed request.","Webb and colleagues combined 306 experimental comparisons of emotion-regulation strategies. Changing an interpretation showed average benefits, but the strategies and outcomes varied. Some outcomes concerned expression, others experience. Hiding a feeling is not evidence that it disappeared. These laboratory comparisons do not validate a body, focus, and language triad or this short ODA exercise. [ST02: state-regulation-meta] Keep the record small and factual, then choose your next attempt from the response and your circumstances."]}],sources:["state-emotion-decisions","state-regulation-meta"]}),g=s({id:"state-2",title:"Still flat? Give the real task a chance",goal:"Test one comfortable preparation at your existing transition, then do one useful part of the task.",hook:"You moved, but the energy lift never came. Can the next small task still happen?",reason:"What useful task waits, and when would recovery serve you better?",reasons:["Start within my capacity","Make progress on my work","Leave room for recovery"],paragraphs:["A bout of aerobic exercise can increase energetic feelings on average. That differs from activity-program research on clinical symptoms. Neither establishes two minutes as a reliable mood-changing dose.","Keep your existing transition and useful task. If movement fits your capacity, test one comfortable option with music and posture unchanged. Then try the task minimum if appropriate. Rest or a nonmovement cue may fit better. Record the preparation and your actual useful task separately; doing one does not prove the other happened."],example:{title:"Marcus's first slide",text:"At 9 a.m., Marcus feels flat before drafting a briefing. He chooses a short comfortable walk, leaving his playlist off. Back at his desk, his energy feels unchanged. He writes one usable slide sentence anyway. He records both facts. The slide still needs work, and he chooses a seated start for the next trial."},invitation:"At the same transition, try one comfortable preparation if useful. Then do your task minimum.",instructions:["Choose one tool, or keep ordinary nonmovement preparation.","Do one useful task step within your capacity."],suggestions:{action:["Write one usable task sentence","Complete one small work correction","Send my chosen clear request"],minimum:["Write one usable sentence","Correct one actual item","Send one request sentence"],when:r,cue:["After optional comfortable movement","At my existing task transition"],place:["Seated at my work surface","In my accessible work space"],minutes:[2,1,5],fallback:["Use a seated nonmovement start","Rest and choose another opportunity"],observation:["The preparation and task actually done","Whether movement caused discomfort"]},obstacle:"Energy stays low after the preparation",stop:"Stop movement if uncomfortable. Choose rest or support when needed.",accessible:"Use seated movement, eyes-open attention to the room, or a nonmovement cue. No smile required.",result:"Did you do the useful task minimum?",observation:"What preparation and task step actually happened?",scenario:{id:"state-2-unchanged-energy",scenario:"After a comfortable walk, Marcus feels unchanged energy without discomfort. His slide facts are checked, and one sentence is manageable. He has three minutes left.",question:"Which next move makes the experiment useful?",bestOptionId:"task-and-record",options:[{id:"timed-seated-start",text:"Spend two minutes settling into a seated start, then write the slide sentence during the remaining minute.",feedback:"A seated start can be useful when movement causes discomfort or access requires it. Marcus reports neither here. Extra preparation consumes most of the available time without addressing an identified obstacle."},{id:"task-and-record",text:"Write the usable sentence, record unchanged energy, and consider another comfortable preparation at the next trial.",feedback:"The task can happen without the promised feeling change. Marcus learns what preparation he tried and whether he started. He can adjust later without increasing effort to force a mood lift."},{id:"check-and-draft",text:"Ask a colleague to confirm the checked slide fact, then draft a provisional sentence while awaiting their reply.",feedback:"A provisional draft and second check can resolve genuine factual uncertainty. The facts are already checked here. That adds a reply dependency where one usable sentence can be written and recorded now."}]},takeaway:"Test the preparation honestly. Judge the useful task by what you actually did.",follow:"Did the preparation help you start, cause discomfort, or point toward rest?",followObservation:"Describe help, discomfort, a recovery need, or no clear difference separately from the task outcome.",depth:[{heading:"Short-term energy and treatment are different questions",paragraphs:["Reed and Ones synthesized 158 studies involving 13,101 participants and single aerobic-exercise bouts. The review reported an average exercise-associated change of 0.47 in positive activated affect, meaning feelings such as energy and alertness. The control-condition change was reported separately. These are not a 0.47 randomized exercise-versus-control treatment effect. Individual responses and study procedures varied. [ST03: state-acute-exercise]","That result does not prove a two-minute dose, reliable energy for everyone, or treatment of depression. A separate overview of longer physical-activity programs found average symptom reductions, with many underlying reviews rated critically low quality. [ST04: state-exercise-mental-health] Your brief preparation is an optional personal trial. Match it to access, health, and capacity. If the record points toward fatigue or discomfort, changing the tool, asking for support, or protecting recovery can serve your direction better than extending the exercise."]},{heading:"Optional additions do not need to become requirements",paragraphs:["You do not need a smile, an expansive pose, or a particular song to start your task. Coles and colleagues reviewed 138 studies and 286 effects. The overall facial-feedback estimate was small, at 0.20, combining emotional experience and judgments. Effects varied, and some judgments showed publication-bias signals. This does not establish smiling as a reliable distress response. [ST05: state-facial-feedback] No forced smile belongs in your preparation.","For this continuing experiment, change one preparation at a time and keep the useful task recognizable. Leave your other conditions ordinary rather than adding a song, pose, and movement together and then guessing which worked. A personal observation can help you choose another trial; it cannot isolate a biological mechanism or establish causality. If the next task still fits your capacity, its minimum can happen without an energy lift. If recovery fits better, record that choice honestly instead of demanding a brighter feeling."]}],sources:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}),f=s({id:"state-3",title:"Too wound up? Pause without chasing calm",goal:"Choose a comfortable pause, then make your existing useful response or an appropriate support step.",hook:"Another breathing drill can wait. What reply needs room for a deliberate choice?",reason:"What would a pause support or delay?",reasons:["Reply more deliberately","Respect a stop signal","Ask for useful support"],paragraphs:["The widely reported sighing study used five minutes daily for 28 days. It did not test two breaths as an instant calm button. A gentle breathing pause is optional preparation, not the action your chosen direction needs.","Return to the same transition and response. Stay seated in a safe place. You may keep ordinary breathing and eyes open, noticing the room instead. If comfortable, try one gentle inhale, a small second inhale, and an unforced slow exhale. Stop for dizziness, tingling, breathlessness, or discomfort. Then choose the reply, rest, or support that fits. New severe physical symptoms need medical assessment, not a stress explanation."],example:{title:"Leah's delayed reply",text:"At her desk after lunch, Leah is tense about a nonurgent email. Breath focus feels uncomfortable, so she keeps her eyes open and notices the window frame. She then sends one factual clarification. Her worry remains, and the answer has not arrived. She records the outward pause and the sentence, without claiming a breathing success."},invitation:"Choose a comfortable pause before your same response. Ordinary breathing and looking outward are valid.",instructions:["Stay seated, away from driving, water, and fall risks.","After the pause, do your response minimum if appropriate."],suggestions:{action:["Send one deliberate reply sentence","Ask for one needed clarification","Make one support request"],minimum:["Send one factual sentence","Ask one clear question","Name one support need"],when:r,cue:["After an optional comfortable pause","Before my next nonurgent reply"],place:["Safely seated at my desk","In a safe private chair"],minutes:[2,1,5],fallback:["Look outward with ordinary breathing","Stop and choose a support step"],observation:["Comfort and the response actually made","Whether I respected a stop signal"]},obstacle:"Breath focus feels uncomfortable",stop:"Stop for dizziness, tingling, breathlessness, or discomfort. Resume ordinary breathing. New severe chest pain or unexplained breathing difficulty needs medical assessment.",accessible:"Keep eyes open, stay seated, look at a neutral object, and skip altered breathing.",result:"Did you make your chosen response?",observation:"What felt comfortable, and what response did you actually make?",scenario:{id:"state-3-uncomfortable-pause",scenario:"Leah stops a breathing trial and resumes ordinary breathing while seated. Light-headedness remains and is unfamiliar. Her reply is nonurgent; a colleague nearby can help.",question:"What should change now?",bestOptionId:"stop-and-support",options:[{id:"stop-and-support",text:"Stay seated with ordinary breathing, postpone the email, and ask her colleague for help obtaining medical advice.",feedback:"She has stopped appropriately. The symptom remains and is unfamiliar, so timely help takes priority over the email or another tool. Severe symptoms or immediate danger require emergency help."},{id:"stop-and-look-outward",text:"Stay seated with ordinary breathing, use the window frame as an outward anchor, then reassess before replying.",feedback:"Outward attention can replace uncomfortable breath focus. Here the unfamiliar symptom persists after stopping, so an anchor alone should not delay asking for help and appropriate medical advice."},{id:"stop-and-defer",text:"Stay seated with ordinary breathing, postpone the email until tomorrow, and check later whether the light-headedness has gone.",feedback:"Postponing a nonurgent message protects time for care. But delaying the message does not address a persistent unfamiliar symptom. Ask for appropriate help now rather than postponing that assessment too."}]},takeaway:"A safe stop is useful information. Calm is not a condition for a thoughtful response.",follow:"Was the pause comfortable, and did it support the response or call for another tool?",followObservation:"Describe comfort, any stop or support need, and the later response separately.",depth:[{heading:"What the sighing trial actually tested",paragraphs:["Balban and colleagues randomized 108 adults to brief breathing practices or mindfulness. Participants practiced for five minutes a day across 28 days. Most were recruited from a Stanford undergraduate psychology class. The study was exploratory and retrospectively registered. The modeling favored breathing for positive affect; it did not establish superiority for anxiety or a reliable result from two breaths. [ST09: state-cyclic-sighing]","The studied cyclic-sighing procedure used a slow inhale, a shorter second inhale, and a slow exhale while seated or lying down. This lesson offers a comfortable optional trial and ordinary-breathing alternatives. Those safety and access choices are ODA adaptations. Do not fill or empty your lungs to strain, hold your breath, or accelerate to force an effect. Your record can distinguish preparation, a stopped trial, and the actual reply. One does not stand in for the others."]},{heading:"Breathing does not diagnose a symptom",paragraphs:["A breathing exercise cannot tell you why a physical symptom occurred. NHS guidance recommends professional assessment for recurrent unexpected panic and describes established treatment options. The boundary for this course is straightforward: ODA is education, not diagnosis or treatment. Do not assume unfamiliar chest pain, fainting, or unexplained breathing difficulty is harmless anxiety. New severe symptoms require medical assessment; immediate danger requires emergency help. [ST18: state-nhs-panic]","You can choose a practical response without altered breathing. Keep eyes open, notice a neutral object, stay seated, or ask for support. If a pause leaves you more uncomfortable, drop it rather than calling persistence progress. There is no requirement to obtain calm before making a useful request when the setting is safe and the response is manageable. There is also no requirement to continue the request when rest, protection, or human help is the appropriate next step."]}],sources:["state-cyclic-sighing","state-nhs-panic"]}),y=s({id:"state-4",title:"Another replay? Make the question earn its place",goal:"Turn one question about your recurring situation into a useful action or an appropriate support request.",hook:"When another why adds no new information, what answer would change your next ten minutes?",reason:"What does another replay postpone in this situation?",reasons:["Clarify a real problem","Use what I learned","Stop postponing a useful request"],paragraphs:["A question is useful when its answer changes a choice. Asking why can reveal a cause, a skill gap, or who owes repair. It is not automatically harmful. Another replay without new information may leave your next move untouched.","At your existing transition, ask what needs clarification, change, or support. Give the answer a verb: send, correct, ask, rest. Research compares broad strategies, not this script. Treat it as a practical aid, use the answer if feasible, then record the behavior rather than its encouraging sound."],example:{title:"Omar's missing approver",text:"At 2 p.m., Omar reviews a stalled project request at his desk. Asking why reveals a missing budget approver, not a personal failure. He finds the named contact in the project notes and sends one clarification. No answer arrives that afternoon. He records the question, the message, and the unresolved approval instead of writing more encouraging prompts."},invitation:"Ask one useful question about the same situation. Do the smallest appropriate action its answer suggests.",instructions:["Keep investigation and accountability when they matter.","Turn the answer into one actual request or correction."],suggestions:{action:["Send one needed clarification","Correct one identified task problem","Ask for one missing resource"],minimum:["Send one clarification sentence","Fix one actual item","Name one missing resource"],when:r,cue:["After answering my useful question","At my existing task transition"],place:["At my desk or phone","In a safe message thread"],minutes:[2,1,5],fallback:["Ask for help locating the answer","Schedule a suitable response opportunity"],observation:["The answer and action actually taken","What remains unresolved"]},obstacle:"I keep analyzing without a next move",stop:"Do not replace needed protection or support with another reflection exercise.",accessible:"Answer silently or through your usual communication method. A support request can be the useful action.",result:"Did you act on the useful answer?",observation:"What did the question reveal, and what did you do?",scenario:{id:"state-4-question-to-action",scenario:"Omar confirms that his request has the required budget fields but never reached the approver. The listed approver accepts clarification messages now.",question:"What completes the useful question?",bestOptionId:"contact-approver",options:[{id:"check-budget-field",text:"Check the submitted budget fields once more before sending the clarification, so the approver gets a complete request.",feedback:"Checking required fields can prevent a wasted message. Omar has already confirmed them, and the missing step is delivery. Repeating the check adds preparation without resolving that known gap."},{id:"break-then-contact",text:"Take a five-minute break, then send the clarification while keeping frustration separate from the factual message.",feedback:"This has an endpoint and can help when a break is needed. No such need is identified here. The factual clarification is ready and addresses the missing approval directly."},{id:"contact-approver",text:"Send the listed approver a factual clarification, then record the response or the absence of one.",feedback:"This turns the identified cause into a controllable action. The reply may not arrive, and approval remains external. Omar can still record whether he made the useful request."}]},takeaway:"An answer earns its place when it changes a useful next move.",follow:"Did your question clarify something and change your action, or only sound encouraging?",followObservation:"Name what became clearer and what changed; no new information or change is valid.",depth:[{heading:"Attention findings do not validate a question set",paragraphs:["Webb and colleagues synthesized 306 experimental comparisons. Broad cognitive-change strategies showed an average effect of 0.36 on emotional outcomes. Attentional deployment averaged near zero overall, while its subcategories differed. These categories covered varied instructions and short experimentally elicited emotions. They do not prove that any named morning questions improve your state, or that asking why and concentrating on a problem are generally harmful. [ST02: state-regulation-meta]","Use the distinction to check the job of a question. Investigation can establish facts. Accountability can identify a responsible person. Planning can name a missing resource. Each may deserve time. If your answer identifies a feasible behavior, choose that behavior. If it identifies an external constraint, do not recast the constraint as an attitude problem. This ODA question-and-action pairing is an adaptation, not a tested protocol with a verified dose or promised emotional result."]},{heading:"Keep the answer connected to your experiment",paragraphs:["Your experiment already has a direction, transition, and useful response. Keep those visible. The question should improve the response rather than become a new daily ritual. For example, a clarification request can target the missing approver; a work step can target the mistaken item; a protection step can target a harmful interaction. Ask only for information relevant to the next choice.","Emotions may influence the way you interpret an answer, and they can carry over from another event. Lerner and colleagues describe both helpful and harmful effects of emotion on decisions. [ST01: state-emotion-decisions] Record the evidence you gained and the action you actually took. A useful answer may still leave the larger problem unresolved. If nothing could be acted on safely, record that constraint or choose support. Do not turn a thoughtful pause into failure, or a written question into proof of the downstream action."]}],sources:["state-regulation-meta","state-emotion-decisions"]}),w=s({id:"state-5",title:"The message hurt. Do not rewrite the facts",goal:"Separate a fact from a guessed motive, then clarify or protect yourself in the same recurring situation.",hook:"That message hurt. Before guessing their motive, check the words and choose a safe response.",reason:"What would a safer response protect or cost?",reasons:["Use feedback without self-attack","Stop accepting unfair treatment","Ask before guessing a motive"],paragraphs:["An event and an explanation differ. “The message contains an insult” is checkable evidence. “They want to ruin my career” guesses a motive. An alternative explanation must fit the facts, without calling harm harmless.","At your same transition, name one fact and what you still do not know. Then clarify, correct, set a boundary, or seek support. Milder emotion words are not automatically truer. The classic labeling study measured brain responses to faces, not relief from renaming distress. Choose accuracy over positivity."],example:{title:"Nina's documented messages",text:"At 4 p.m., Nina receives another insulting team message. In a private chair, she separates the saved words from her guess about the sender's motive. She stays angry. Instead of calling it a misunderstanding, she asks a trusted manager about a safe reporting route. The manager needs time to check. Nina records the request and protects the messages."},invitation:"Use one fact to improve your existing response. Clarify uncertainty, or choose protection when harm is documented.",instructions:["Separate observable facts from guessed motives.","Make one appropriate clarification, correction, boundary, or support request."],suggestions:{action:["Ask about a safe support route","Send one factual clarification","Correct one confirmed work error"],minimum:["Make one support request","Ask one factual question","Correct one actual item"],when:r,cue:["After checking an upsetting message","Before my next planned reply"],place:["In a safe private chair","In a trusted support channel"],minutes:[2,1,5],fallback:["Keep evidence and seek safer support","Choose another safe response opportunity"],observation:["The fact and response actually used","What evidence changed my interpretation"]},obstacle:"A positive explanation would hide real harm",stop:"Do not reframe abuse or danger as a misunderstanding. Choose protection and support.",accessible:"Name facts silently, type, sign, or ask for assistance. No body focus or milder label is required.",result:"Did you make the factual response you chose?",observation:"What evidence did you use, and what response happened?",scenario:{id:"state-5-documented-insults",scenario:"Nina has secured messages containing repeated insults. A trusted manager is available now; a reporting portal opens tomorrow. There is no immediate danger or known motive.",question:"Which next step uses the facts and available support?",bestOptionId:"facts-and-support",options:[{id:"copy-and-wait",text:"Create another protected copy of the saved insults, then wait for the reporting portal to open tomorrow.",feedback:"Preserving evidence serves protection. These messages are already secured, though, so another copy adds no identified safeguard. The available manager can clarify a safe route now without requiring contact with the sender."},{id:"facts-and-support",text:"Separate the documented insults from guessed motives, then ask a trusted person about a safe support route.",feedback:"This preserves uncertainty about motive while recognizing actual harm. Nina can seek protection without proving a hidden intention, changing her emotion label, or confronting the sender directly."},{id:"wait-safe-portal",text:"Avoid contacting the sender, wait for tomorrow's reporting portal, and use the saved messages to ask about support.",feedback:"Avoiding direct contact and using a reporting channel can be protective. Here trusted support is available sooner. Asking about the route now preserves her options; it does not force reporting or confrontation."}]},takeaway:"Change the interpretation only as far as the evidence allows. Then make the appropriate response.",follow:"What evidence supported or challenged your interpretation, and did your response fit it?",followObservation:"Name the relevant fact, remaining uncertainty, and whether your response fit the evidence.",depth:[{heading:"A brain measure is not a distress treatment",paragraphs:["Lieberman and colleagues studied 30 healthy adults labeling emotions on faces during brain imaging. The emotion-word condition differed from the gender-name condition in an amygdala measure. The study did not show that replacing furious with annoyed reduces real-life distress, that self-labeling has the same effect, or that a benefit lasts. [ST11: state-affect-labeling] Those are different interventions and outcomes.","This lesson uses a fact, feeling, and uncertainty check as an ODA aid. Its value here is to make the next choice explicit. You can use an accurate strong feeling word, choose no label, or keep the note private. A documented insult remains an insult even if you feel less angry later. A brief delayed reply may remain ambiguous even if you feel very anxious now. Use what can be checked, preserve what is unknown, and choose the response that fits your safety and direction."]},{heading:"Reappraisal can include a boundary",paragraphs:["Changing an interpretation is often called reappraisal. Webb and colleagues found average benefits across varied experimental comparisons, with clear differences between strategies and outcomes. That does not make a positive explanation universally best. The evidence does not validate the exact one-minute worksheet, and it does not justify ignoring feedback, material constraints, or harm. [ST02: state-regulation-meta]","A fair interpretation can make responsibility more specific: I missed this item, so I will correct it. It can also reduce unsupported blame: I do not know why the reply is late, so I will ask. Where harm is documented, it can support protection: I do not need to prove a motive before seeking help. Carry the same chosen experiment forward by recording which response happened and what new evidence emerged. An unanswered request stays unanswered. A safe stop stays a stop. Neither requires a more optimistic story to make the record acceptable."]}],sources:["state-affect-labeling","state-regulation-meta"]}),b=s({id:"state-6",title:"Positive words feel fake? Make one useful move",goal:"Use a credible action sentence to start your existing task without requiring gratitude or a mood change.",hook:"Your morning routine is ready. Has it bought you a real action yet?",reason:"What does extending the routine keep postponing?",reasons:["Start the action I chose","Use words I can believe","Keep preparation short"],paragraphs:["Sweeping positive statements are not a proven way to improve everyone's mood. Early benefit and backfire findings failed later replication. There is no verified evidence here that forceful delivery or incantations solve this. Choose a plain instruction you can act on.","At your same transition, try “I can send one clear request while unsure,” then send it if suitable. Optional gratitude should describe something real, not an imagined achievement. Skip it if forced. The sentence is preparation. Record the behavior separately; no convincing feeling or complete ritual is needed."],example:{title:"Aisha's first request",text:"After her first drink at 8 a.m., Aisha has two minutes before leaving. “I am unstoppable” feels false. She chooses “I can ask one clear question while unsure” and sends the request she has been delaying. She skips gratitude today. There is no reply before she leaves. She records the sent sentence, without calling uncertainty a failure."},invitation:"Keep the routine short. Use one credible sentence, then do your existing useful action.",instructions:["Choose a statement about controllable behavior.","Try the action now if suitable, or save its real cue."],suggestions:{action:["Send my chosen clear request","Write one usable task sentence","Make one practical support request"],minimum:["Send one clear sentence","Write one usable sentence","Name one support need"],when:r,cue:["After my first drink","At my existing task transition"],place:["Seated at my kitchen table","In my usual task space"],minutes:[2,1,5],fallback:["Skip the ritual and use my sentence","Choose the next realistic opening"],observation:["Whether words led to the action","What preparation delayed the action"]},obstacle:"I keep extending the preparation",stop:"Skip gratitude, imagery, or statements that increase distress. Choose ordinary support instead.",accessible:"Use ordinary breathing and eyes-open attention. Say, type, sign, or silently use the instruction.",result:"Did you do the action after your sentence?",observation:"What did you actually start, send, or change?",scenario:{id:"state-6-believable-start",scenario:"Aisha has two minutes before leaving. Her checked question is clear, courteous, and ready through a safe channel. She keeps delaying because she wants to sound confident.",question:"Which version fits this morning?",bestOptionId:"credible-and-send",options:[{id:"rehearse-and-send",text:"Rehearse the message aloud for ninety seconds, then send the checked question before leaving.",feedback:"Timed rehearsal can help an unclear or unfamiliar request. This question is already clear and checked. Rehearsing consumes most of her opening without addressing the belief that confidence must come first."},{id:"credible-and-send",text:"Use a credible instruction about asking while unsure, then send the ready question through the safe channel.",feedback:"This pairs controllable words with an available act. Aisha does not have to believe a sweeping claim, feel grateful, or lose uncertainty before making her useful request."},{id:"polish-and-send",text:"Draft a brief opening and closing for the message, then send the ready question before she leaves.",feedback:"An opening and closing can add courtesy where needed. Her ready question already communicates the request. More polishing leaves less time to send; a credible instruction addresses starting while unsure directly."}]},takeaway:"Make the words believable enough to use. Let the action supply the evidence.",follow:"Did the sentence help you act, delay the move, or make no clear difference?",followObservation:"Describe help or delay separately from the action outcome; no clear difference is valid.",depth:[{heading:"Affirmation evidence is mixed",paragraphs:["Wood and colleagues studied repeated positive self-statements in university samples. Their early findings suggested different responses depending on self-esteem, including a poorer response among some participants. Two later replication attempts by Flynn and Bordieri did not reproduce the mood, state-esteem, or moderation findings. The correct boundary is mixed evidence, not a claim that affirmations help everyone or harm everyone. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","The evidence does not establish embodied incantations as a solution. A credible instruction about one behavior is offered here as practical coaching, not a proven psychological treatment. You may use your own words, skip the statement, or choose support. Keep the task and its minimum clear enough to observe. Speaking a sentence about a future act is preparation. Sending the request, correcting the item, or asking for support is the act you can later report."]},{heading:"Appreciation has limits and no obligation",paragraphs:["Kirca and colleagues reviewed 23 studies with 25 randomized samples of expressed gratitude. Positive wellbeing showed a small average benefit against neutral controls, with an effect of 0.22. Against bona fide wellbeing activities the estimate was smaller and statistically inconclusive. [ST13: state-gratitude-expressed] That means the comparison activity matters when judging the apparent benefit.","That research does not establish a ten-minute priming package, three imagined future scenes, an optimal morning sequence, or superiority to appropriate clinical treatment. If you choose appreciation, use a real detail you welcome. Do not require a silver lining in loss or gratitude toward someone unsafe. A hoped-for future is a possibility, not a memory or an accomplished result. The practical test for your continuing experiment is whether the optional preparation supported the same useful action. Drop it if it adds delay or discomfort."]}],sources:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}),v=s({id:"state-7",title:"Stop collecting resets. Choose what earns another week",goal:"Use your actual records to keep, shrink, replace, or pause the same experiment for next week.",hook:"The routine keeps growing while the task waits. Which part helped you start, and which added delay?",reason:"What would keeping this experiment displace next week?",reasons:["Keep the useful next move","Protect needed recovery","Drop a ritual that delays me"],paragraphs:["A desired future paired with an obstacle and response plan has more direct evidence than catastrophic-cost imagery. Imagined costs are predictions, not facts. Shame and stronger vows are not required.","Review actual records at your same transition. Which preparation supported the useful response? Which caused discomfort, delay, or no clear difference? Keep one helpful version, change one problem, or pause. Make next week's minimum fit your capacity, and try an appropriate step if feasible. Rest, protection, and support can belong in the plan."],example:{title:"Evan's smaller standard",text:"On Sunday afternoon, Evan reviews his portfolio-start records at his desk. One outward pause helped him start; a long ritual delayed him twice. After poor sleep today, he skips the ritual and corrects one caption. He schedules the same small step for Tuesday. The portfolio is unfinished, but his next plan now fits the evidence."},invitation:"Use the records from your same experiment. Keep one useful version and try its feasible minimum.",instructions:["Review reported attempts; leave missing outcomes unknown.","Keep, shrink, change, or pause one version for next week."],suggestions:{action:["Repeat my useful task step","Make my next clear request","Carry out my chosen recovery step"],minimum:["Correct one useful task item","Use one request sentence","Take the recovery time I chose"],when:r,cue:["At my tested useful transition","At my next realistic opening"],place:["In my usual task space","In my chosen recovery space"],minutes:[2,1,5],fallback:["Shrink the step to fit capacity","Pause and choose a support step"],observation:["What I repeated or changed","Which obstacle actually occurred"]},obstacle:"My usual plan asks more than my capacity allows",stop:"Skip distressing cost imagery. Rest, protection, and support can be appropriate next moves.",accessible:"Review silently or with assistance. Use an eyes-open, seated, nonmovement option if a pause helps.",result:"Did you do the next minimum you chose?",observation:"What did you keep, change, or pause, and what actually happened?",scenario:{id:"state-7-capacity-review",scenario:"Evan has five usable minutes after poor sleep. His caption has a known error with its correction ready. The deadline is next week; long setup delayed his last two starts.",question:"Which next version fits the evidence?",bestOptionId:"small-caption",options:[{id:"small-caption",text:"Correct one portfolio caption, record the smaller attempt, and choose the next realistic session from his capacity.",feedback:"This preserves the purpose while changing the dose to fit today. Evan can use his records to plan another opportunity without requiring a long ritual or perfect energy."},{id:"sort-next-section",text:"Use the five minutes to sort source notes for the next section, leaving the known caption correction for Tuesday.",feedback:"Sorting notes can prepare a later section, but setup has repeatedly delayed his useful work. The current correction is ready. Completing that small unit tests a version that addresses his recorded obstacle."},{id:"defer-for-checking",text:"Save the caption correction for a rested session tomorrow, using these five minutes to schedule time for checking it.",feedback:"Deferring is appropriate when fatigue makes a task unsuitable or accuracy needs checking. Here the correction is ready and fits his usable capacity. Planning another check postpones an available meaningful unit."}]},takeaway:"Keep the purpose. Let actual attempts and current capacity shape the next version.",follow:"Did your next version fit your capacity, and which obstacle actually affected it?",followObservation:"Name what fit, what got in the way, or why recovery or another change was appropriate.",depth:[{heading:"An obstacle plan has evidence; catastrophe is optional to omit",paragraphs:["Wang and colleagues combined 24 independent effects across 21 articles involving 15,907 participants. Mental contrasting with response planning had a small-to-medium average goal-attainment effect of 0.336. A publication-bias-adjusted estimate was smaller, and study results varied. The procedure combines a feasible desired future, an obstacle, and an if-obstacle-then-response plan. It does not validate a Dickens process, shame induction, or converting every should into a must. [ST15: state-mental-contrasting]","Use an obstacle that your records or circumstances support. If it is internal, name a manageable response. If it is external, resources, a different setting, or help may be needed. An imagined future cost remains a prediction. You do not need to relive painful memories or picture escalating damage to make this plan valid. The shorter record-based approach here is an ODA adaptation, and its duration is an estimate rather than a verified optimal dose."]},{heading:"Consolidate the experiment instead of adding a ritual",paragraphs:["The course began with one transition and one useful response. Review those exact attempts before deciding what deserves another week. Distinguish a preparation tried from a task completed, and an unchanged feeling from a failed minimum. A missing report supplies no outcome. A conditional opening that never occurred can be recorded as no occasion. Let each next choice respond to what is known.","Breines and Chen found that self-compassion could coexist with improvement motivation in short experiments. After test failure, the compassion condition studied longer than a no-reminder condition; second-test performance did not significantly differ, and the self-esteem comparison was inconclusive. [ST16: state-self-compassion-motivation] That supports dropping the assumption that contempt is necessary for effort. It does not guarantee sustained behavior change. Your next version can include support, recovery, or stopping an unsuitable plan. The record and dated return keep those decisions honest, without a compulsory daily streak."]}],sources:["state-mental-contrasting","state-self-compassion-motivation"]}),E=[{id:"state-1",practiceCount:3,correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"A man crossing a quiet city street under sunlit trees"}},{id:"state-2",practiceCount:3,correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"A woman walking along a boardwalk through green plants"}},{id:"state-3",practiceCount:3,correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"A woman with her eyes closed, hugging herself gently in a forest"}},{id:"state-4",practiceCount:3,correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"A woman in a knit hat facing the low sun"}},{id:"state-5",practiceCount:3,correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"A man standing quietly in front of a bright window"}},{id:"state-6",practiceCount:3,correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"A woman sitting on green grass looking toward the morning sun"}},{id:"state-7",practiceCount:3,correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"A woman sitting on top of a rock outdoors, writing in a notebook"}}];function _(e,t){const a=E[t],n=e.judgment.primary.options.find(o=>o.id===e.judgment.primary.bestOptionId),i=e.judgment.primary.options.filter(o=>o.id!==n.id).map(o=>o.text);return i.splice(a.correct,0,n.text),{id:a.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.suggested.action,"Record the actual outcome and choose the next appropriate attempt."].slice(0,a.practiceCount),reflection:e.direction.reason.label,question:`${e.judgment.primary.scenario} ${e.judgment.primary.question}`,options:i,correct:a.correct,feedback:n.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:a.photo}}const z={id:"state",title:"Still wound up? Give your next move room",subtitle:"7 lessons. Test one useful response, with optional tools for the moment before it.",description:"Carry one real transition through comfortable preparation, accurate interpretation, action, and review. Keep what serves your life without requiring a better mood.",scope:"For adults who want everyday tools to shift mood and energy. This is education, not diagnosis or treatment, and it is not a treatment for anxiety disorders, panic disorder or depression; it does not replace therapy or medication. Stop any breathing drill at once if you feel dizzy, light-headed, tingly or short of breath, return to normal breathing and sit down; if you have a heart or lung condition or are pregnant, check with a clinician before trying energizing breathwork, and never practice it while driving or in water. If you are in crisis or have thoughts of harming yourself, contact your local emergency number (911 in the US, 112 in Türkiye and much of Europe).",outcome:"One useful response at a recurring transition, honest attempt records, and a next-week plan that fits your capacity.",photo:{id:"1500080628126-901233e80205",alt:"A woman standing on a wooden dock at golden hour, raising one hand toward the light"},lessons:[m,g,f,y,w,b,v].map(_)},ee=Object.freeze(Object.defineProperty({__proto__:null,COURSE:z,SOURCES:L,STATE_1_V2:m,STATE_2_V2:g,STATE_3_V2:f,STATE_4_V2:y,STATE_5_V2:w,STATE_6_V2:b,STATE_7_V2:v},Symbol.toStringTag,{value:"Module"})),B=[{id:"optimism-maier-seligman",title:"O01 · Maier & Seligman · 2016 · Learned helplessness at fifty",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"The review revises the learned-helplessness account: in aversive animal paradigms, prolonged stimulation produces passivity while detecting control engages protective circuitry.",limitation:"Primarily animal experiments, not a pooled human treatment review. It does not establish ordinary human freezing as a universal default or validate a control-list exercise."},{id:"optimism-malouff-schutte",title:"O03 · Malouff & Schutte · 2017 · Can interventions increase optimism?",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"Across 29 randomized studies with 3,319 participants, psychological interventions increased optimism scores on average (g = 0.41).",limitation:"Methods and follow-up varied; shorter follow-up and completer analyses yielded larger effects. The opened record did not verify the confidence interval. This does not establish permanent change or ODA effectiveness."},{id:"optimism-sweeney",title:"O02 · Sweeney, Anderson & Bailey · 1986 · Explanations and depression",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Across 104 studies with nearly 15,000 participants, depression was associated with internal, stable, global explanations of negative events.",limitation:"An association does not establish cause or make a negative explanation false. The opened abstract did not verify pooled effects or confidence intervals. A reassuring rewrite is not always accurate."},{id:"optimism-hofmann",title:"O06 · Hofmann et al. · 2012 · CBT review of meta-analyses",url:"https://doi.org/10.1007/s10608-012-9476-1",type:"research",finding:"The review identified 269 CBT meta-analyses and reviewed 106 representative ones. Support concerned treatment packages and varied by problem.",limitation:"Neither count means isolated thought-record trials or validates ODA’s worksheet. A separate erratum’s correction text was unavailable for verification."},{id:"optimism-brunwasser",title:"O05 · Brunwasser, Gillham & Kim · 2009 · Penn Resiliency Program review",url:"https://doi.org/10.1037/a0017671",type:"research",finding:"Across 17 controlled studies with 2,498 young people, the multisession program showed small depressive-symptom benefits against no intervention.",limitation:"Benefits over active controls and prevention of depressive diagnoses were not established. This youth package does not validate an isolated adult ABCDE exercise."},{id:"optimism-ellis-abc",title:"O12 · Albert Ellis Institute · ABC professional explanation",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"guidance",finding:"The professional explanation describes an event, beliefs, consequences, disputing rigid beliefs, and a new effective philosophy.",limitation:"A procedure document, not an efficacy trial. Ellis’s final step should not be silently equated with later “energization” variants. A brief ODA exercise is an adaptation."},{id:"optimism-beck-thought-record",title:"O13 · Beck Institute · Thought record worksheet",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"guidance",finding:"The clinical worksheet documents situation, thought, emotion, evidence, a balanced response, and subsequent ratings.",limitation:"A clinical procedure, not an isolated efficacy trial. ODA’s shorter adaptation is not CBT treatment, and a balanced response need not reduce distress."},{id:"optimism-reivich-mrt",title:"O14 · Reivich, Seligman & McBride · 2011 · Master resilience training",url:"https://doi.org/10.1037/a0021897",type:"guidance",finding:"The program description includes ABC, thinking-trap prompts, and worst, best, and most-likely possibilities followed by a plan.",limitation:"A ten-day trainer-course description. It does not establish standalone efficacy of these exercises or the ODA course."},{id:"optimism-landau-inquiry",title:"O11 · Landau et al. · 2021 · Facilitated inquiry-based stress reduction trial",url:"https://doi.org/10.1001/jamanetworkopen.2021.39670",type:"research",finding:"A registered randomized trial in 100 women with BRCA variants compared a 12-week facilitated inquiry program with standard care and reported benefits on some well-being outcomes.",limitation:"Weekly three-hour groups plus assisted practice are not a brief self-guided lesson. Standard care lacked matched attention. The trial does not establish CBT equivalence or applicability to abuse or trauma."},{id:"optimism-katie-instructions",title:"O15 · Byron Katie International · The Work instructions",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Practitioner instructions describe four inquiry questions, followed by turnarounds and genuine examples.",limitation:"Instructions are not scientific evidence. Turnarounds must remain optional, with no invented examples or forced self-blame. The longer facilitated trial is a different delivery."},{id:"optimism-nhs-cbt",title:"O16 · NHS · Cognitive behavioural therapy",url:"https://www.nhs.uk/tests-and-treatments/cognitive-behavioural-therapy-cbt/",type:"guidance",finding:"NHS guidance describes structured CBT treatment and routes to professional help.",limitation:"Guidance does not endorse ODA as therapy or guarantee a response. Practical protection and professional care take priority over a self-guided thinking exercise."},{id:"optimism-three-good-things",title:"O07 · Seligman et al. · 2005 · Positive psychology interventions",url:"https://doi.org/10.1037/0003-066X.60.5.410",type:"research",finding:"The original online trial used one-week exercises. Three good things meant three events plus why they happened, nightly for one week.",limitation:"577 baseline respondents became 411 follow-up completers, largely White educated volunteers. Continued practice was not randomized. This does not prove guaranteed maintenance or clinical treatment."},{id:"optimism-mongrain",title:"O08 · Mongrain & Anselmo-Matthews · 2012 · Positive exercise replication",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"The replication found happiness gains with named exercises and a positive placebo. A distinctive depression benefit was not demonstrated.",limitation:"The opened abstract did not verify participant count or numerical effects. Results provide less exercise-specific support, without proving every positive exercise useless."},{id:"optimism-nimh-support",title:"O20 · NIMH · Depression guidance",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Persistent symptoms or impaired functioning warrant professional evaluation. Crisis support is available.",limitation:"This is guidance, not an app diagnosis. There is no requirement to wait two weeks or complete the course before asking for help."}],k={schemaVersion:2,revision:2,id:"optimism-1",courseId:"optimism",locale:"en",title:"Rejected? Test one part you can influence",goal:"Choose a low-stakes setback and take one useful step within your actual influence.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"One rejection closed the road? Test an available step before deciding what comes next.",reason:{id:"optimism-1-reason-available-step",label:"Which available step have you ruled out, and what evidence supports that?",kind:"text",maxLength:160,optional:!0,suggestions:["Check a ruled-out option","Keep a justified stopping point","Try an available requirement"]},why:{id:"optimism-1-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A setback and your next available move are different things. You cannot make someone approve your work. You may be able to ask which requirement was missed, practice a skill, or seek support. Choose one part you can test rather than declaring the whole situation controllable.","Research interventions have changed optimism scores on average. That measures expectations, not proof that a rejection will reverse. This course follows one ordinary setback and one recovery action. Save the step, actually try it, and record the response, including no response. A calendar entry is preparation; asking the question is the act."],example:{title:"Maya's unanswered feedback request",text:"Maya’s draft is rejected, and she considers abandoning a project she cares about. At 12:30, in a safe team message thread, she asks, “Which requirement should I fix first?” She gets no reply that afternoon. Her record says the question was sent. She has tested a feedback request, not proved the project will be accepted."}},move:{invitation:"Choose an ordinary setback. Try one available step, then record what happened.",instructions:["Keep this same setback and direction through the course.","Choose an actual act, not only a calendar entry."],prompts:[],suggestions:{action:["Send one specific feedback question","Correct one known missed requirement","Request practical help with the setback"],minimum:["Send one clear feedback sentence","Fix one known error","Make one practical support request"],cue:["At my next safe team check-in","When I return to the rejected draft","When support is available"],place:["In a safe message thread","At my usual work surface"],fallback:["Ask someone to identify one specific requirement","Work on a known requirement","Switch an unavailable feedback channel"],observation:["Whether I sent the question","The reply or no reply","What was within my influence"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Send one specific feedback question",minimum:"Send one clear feedback sentence",minutes:2,cueHint:"At my next safe team check-in",placeHint:"In a safe message thread",obstacleHint:"I cannot identify a requirement I can change.",fallbackHint:"Ask someone to identify one specific requirement",observationHint:"Whether I sent the question"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. Stop repetitive analysis; seek support.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-1-review-window-decision",scenario:"Maya’s draft was rejected without a reason. She has ten minutes before the reviewer’s question window closes. A revision needs two hours; she wants to know whether it is worth doing.",question:"Which step best informs that decision now?",options:[{id:"optimism-1-inspect-brief",text:"Inspect the old brief for ten minutes, then revise the requirement she thinks caused the rejection.",feedback:"Checking the brief may reveal a real omission. It still leaves the reviewer’s reason unknown, and uses the closing question window. Ask now; inspect the relevant requirement afterward."},{id:"optimism-1-ask-criterion",text:"Ask which requirement was missed, then use the answer to choose one feasible corrective step.",feedback:"This uses an available information source before it closes. A reply may justify revising, seeking help, or stopping. Sending the question counts as the act; getting a reply does not."},{id:"optimism-1-send-partial-rewrite",text:"Send a ten-minute partial rewrite now to demonstrate initiative before the question window closes.",feedback:"A partial rewrite could help if it addresses the real gap. With no reason supplied, Maya would be guessing. Use this window to ask which change matters before investing in revision."}],bestOptionId:"optimism-1-ask-criterion"}},carry:{takeaway:"After a setback, test one part you can influence and record what it actually changes.",followUp:{questionId:"optimism-1-return",question:"Did you take the available step, and did it produce information, no reply, or a new constraint?",observationPrompt:"What information, no reply, or new constraint followed the step?",adjustmentPrompt:"Which next step fits what you learned?"}},goDeeper:{sections:[{heading:"The animal account was revised",paragraphs:["Maier and Seligman’s 2016 review revisits the learned-helplessness explanation using decades of animal research [O01]. In the reviewed aversive paradigms, prolonged stimulation produces passivity, while detecting control engages protective circuitry. This revised account concerns rats or dogs exposed to prolonged aversive events, not a direct experiment on an adult’s ordinary rejected draft.","It does not establish that freezing is every person’s default, that all helplessness has one mechanism, or that listing controllable tasks reverses a clinical condition. This lesson therefore starts with a practical distinction rather than assigning your reaction a brain explanation: the reviewer’s decision and the question you can send are different events.","ODA’s one-step recovery experiment is an adaptation. You may discover the available lever does little, or that the constraints require help or a different direction. Keep that result. A real attempt provides information without promising restored hope."]},{heading:"Changed expectations are not guaranteed outcomes",paragraphs:["Malouff and Schutte combined 29 randomized studies involving 3,319 participants [O03]. Psychological interventions increased optimism scores on average, with g = 0.41. Methods, delivery, and follow-up varied; shorter follow-up and completer analyses produced larger effects. This average describes study groups, not how much your expectations will change after one attempt.","The review does not show permanent personality change, better objective outcomes, or the effect of this ODA course. A feedback request tests a requirement. It cannot promise future acceptance. The answer can still help you decide whether the revision deserves your time, needs support, or no longer fits.","Your next step may be support rather than another task. NIMH guidance recommends professional evaluation for persistent symptoms or impaired functioning [O20]. You can ask for help before completing lessons and without waiting for a duration threshold. An actual help request can be a meaningful action in its own right."]}],sourceIds:["optimism-maier-seligman","optimism-malouff-schutte","optimism-nimh-support"]}},x={schemaVersion:2,revision:2,id:"optimism-2",courseId:"optimism",locale:"en",title:"One setback becoming your whole story? Get specific",goal:"Keep the true cause of your setback and try one correction without a global self-verdict.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"A rejected draft became “I cannot do this”? Keep the facts and test your next correction.",reason:{id:"optimism-2-reason",label:"What part is yours to change, and what remains uncertain?",kind:"text",maxLength:160,optional:!0,suggestions:["Own the correctable part","Keep uncertainty honest","Resume one useful correction"]},why:{id:"optimism-2-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your setback and recorded response. Explanations that treat setbacks as lasting, affecting many parts of life, and caused by something about you are associated with depression. Association does not prove causation or make every painful explanation wrong.","Ask: how long might the cause last, which part of life does it affect, and what is yours or unknown? A durable skill gap can be real. Name it without making one draft a verdict on everything. Test one correction. Keep responsibility and uncertainty rather than forcing a reassuring cause."],example:{title:"Maya's specific correction",text:"Maya learns that her rejected draft did not answer the client’s budget question. At 7:00, she replaces “I am no good at this” with a specific account: the budget section was incomplete. She adds one usable explanation and sends it for review. The reviewer still wants more detail. Her correction is real, and the overall result stays open."}},move:{invitation:"Use the same setback. Name one accurate cause, then perform the correction it suggests.",instructions:["Keep durable constraints and your own contribution if the evidence supports them.","Do one useful correction; record the actual result."],prompts:[],suggestions:{action:["Correct one known requirement","Ask what missed the brief","Practice the identified skill once"],minimum:["Fix one incomplete draft line","Send one clarifying question","Complete one real skill attempt"],cue:["When I reopen the same draft","At the next safe feedback opening","After reading the actual requirement"],place:["In the draft I am correcting","In a safe feedback channel"],fallback:["Reread the requirement; correct one supported gap","Ask when essential information is missing","Request help with the skill gap"],observation:["What I actually corrected","Which cause remained uncertain","Whether the feedback matched my explanation"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Correct one known requirement",minimum:"Fix one incomplete draft line",minutes:2,cueHint:"When I reopen the same draft",placeHint:"In the draft I am correcting",obstacleHint:"I turn one failure into a verdict about all my work.",fallbackHint:"Reread the requirement; correct one supported gap",observationHint:"What I actually corrected"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. Stop repetitive analysis; seek support.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-2-budget-gap-decision",scenario:"Maya’s reviewer names one missing budget assumption. The rest meets the brief. She has ten minutes to revise before review closes and thinks the gap proves she cannot do this work.",question:"Which response fits the evidence and deadline?",options:[{id:"optimism-2-rewrite-budget",text:"Rewrite the whole budget section now so the reviewer can judge a fully fresh version.",feedback:"A full rewrite can help when a section has several linked problems. Here one assumption is missing and time is short. Correct that gap without replacing work already accepted."},{id:"optimism-2-clarify-first",text:"Ask the reviewer to restate the missing assumption, then wait for clarification before changing the section.",feedback:"Clarification is useful when feedback is ambiguous. Here the requirement is named, and waiting risks the review window. Make the supported correction, then ask whether it meets the requirement."},{id:"optimism-2-specific-correction",text:"Keep the budget gap as true, correct one element, and leave the wider career conclusion unproven.",feedback:"This owns the supported gap and uses the short window to address it. Ask whether the correction meets the requirement. Further feedback stays evidence about this draft, not a career verdict."}],bestOptionId:"optimism-2-specific-correction"}},carry:{takeaway:"An accurate explanation can be uncomfortable and still point to a useful correction.",followUp:{questionId:"optimism-2-return",question:"Did your correction address a supported cause, and what part of the explanation is still unknown?",observationPrompt:"Which supported cause did you address, and what stayed unknown?",adjustmentPrompt:"Which gap needs correction, clarification, or support next?"}},goDeeper:{sections:[{heading:"Questions, not reassuring answers",paragraphs:["Sweeney and colleagues reviewed 104 studies with nearly 15,000 participants [O02]. Depression was associated with internal, stable, and global explanations for negative events across varied samples and tasks. These dimensions concern personal contribution, lasting causes, and broad effects; they do not require a setback to have only one cause. The association does not show which factor caused which.","This lesson uses the dimensions to inspect an explanation, not to prescribe a cheerful result. A long-term constraint may remain long-term. Your own missed requirement may remain yours to correct. Shared causes may be present, and some causes may still be unknown. Replacing every explanation with “temporary and outside me” would lose accuracy.","Bring the question back to the same course experiment. Which part can you correct, check, or get help with? A specific action is easier to test than a broad claim about ability. Keep the record of the action separate from your interpretation of its outcome."]},{heading:"A fair response still allows a real problem",paragraphs:["The Beck Institute’s thought-record procedure documents evidence, alternatives, a balanced response, and subsequent observations [O13]. It is a clinical worksheet, not proof that this short explanation exercise independently improves mood. ODA’s brief adaptation has no established isolated treatment effect. Use it to identify a supported correction, rather than requiring a reassuring explanation.","A balanced account can include unpleasant facts. The budget section may be incomplete, the deadline may be tight, or the skill may need practice. It can also include what is not known. The next behavior might be correction, a neutral question, or a request for support rather than another reassuring sentence.","NHS guidance describes CBT as structured treatment with professional routes to help [O16]. This course is education. If repeated self-guided analysis increases distress or interferes with functioning, stop the exercise and seek appropriate assistance. Safety and practical needs take priority over an optimism label."]}],sourceIds:["optimism-sweeney","optimism-beck-thought-record","optimism-nhs-cbt"]}},T={schemaVersion:2,revision:2,id:"optimism-3",courseId:"optimism",locale:"en",title:"Angry reply ready? Separate fact from verdict",goal:"Examine your same setback briefly, then send or make one constructive response you can stand behind.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"About to send the defensive reply? Keep the true fact and choose a response worth sending.",reason:{id:"optimism-3-reason",label:"Which response would serve your direction tomorrow as well as today?",kind:"text",maxLength:160,optional:!0,suggestions:["Own a specific mistake","Reply without a career verdict","Solve the practical problem"]},why:{id:"optimism-3-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A missed deadline is a fact. “I cannot do this job” is a wider belief. A documented framework separates event, belief, and the feelings or behavior that follow. Thoughts can influence your response, but do not explain every emotion.","Bring back your setback. State one neutral fact, check the belief against evidence, and choose a useful response. If the concern is true, keep it and solve that part. A fair reply can include accountability, a request, or a boundary. Act without requiring embarrassment or anger to disappear."],example:{title:"Maya's accountable reply",text:"Maya misses the revised report deadline. At 6:30, she starts a defensive reply, then separates the fact from “I cannot do this job.” She sends, “I missed today’s deadline. I can deliver the corrected section by noon tomorrow; does that fit?” Her manager accepts the time but remains frustrated. Maya records the actual agreement and her unfinished work."}},move:{invitation:"Use the same setback. Check the belief briefly, then carry out one fair response.",instructions:["Separate one observable fact from the wider verdict.","Send a useful correction, request, or boundary."],prompts:[],suggestions:{action:["Send one accountable corrective reply","Make one realistic deadline request","Complete one agreed correction"],minimum:["Send one constructive sentence","State one feasible next step","Finish one agreed useful part"],cue:["Before sending the difficult reply","At the next safe corrective discussion","When I return to the agreed task"],place:["In the safe work message thread","At my usual work surface"],fallback:["Write one fact and feasible next step; send","Ask someone to check the factual reply","Choose practical support instead"],observation:["What I actually sent or changed","The agreement or lack of agreement","What part of the concern stayed true"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Send one accountable corrective reply",minimum:"Send one constructive sentence",minutes:2,cueHint:"Before sending the difficult reply",placeHint:"In the safe work message thread",obstacleHint:"I want to defend myself before addressing the actual mistake.",fallbackHint:"Write one fact and feasible next step; send",observationHint:"What I actually sent or changed"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. Stop repetitive analysis; seek support.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-3-decision",scenario:"Maya’s manager correctly says she missed a deadline. Maya thinks, “I cannot do this job,” and wants to defend herself.",question:"What best uses a fair belief check?",options:[{id:"optimism-3-own-and-correct",text:"Name the missed deadline, leave the career verdict unproven, and agree one realistic corrective step.",feedback:"This keeps the supported fact and tests the wider conclusion. A realistic corrective response follows even if embarrassment remains. The manager’s approval is an outcome to observe, not a completion requirement."},{id:"optimism-3-past-reviews",text:"Review her favorable past feedback until the criticism feels less threatening, then decide whether to answer.",feedback:"Past feedback can challenge a global verdict, but it does not address today’s missed deadline. Waiting for relief delays the practical response. Use relevant evidence briefly, then propose a feasible correction."},{id:"optimism-3-pressure-first",text:"Explain the pressure she was under and ask for recognition of her effort before discussing a correction.",feedback:"Workload pressure may be real and may need a boundary or support. Making recognition a condition postpones the correction. Own the specific deadline gap while requesting a realistic adjustment."}],bestOptionId:"optimism-3-own-and-correct"}},carry:{takeaway:"Keep the true fact. Test the wider verdict. Act on the useful conclusion.",followUp:{questionId:"optimism-3-return",question:"Did your actual response address the true problem, even if the difficult feeling remained?",observationPrompt:"Which true problem did your response address?",adjustmentPrompt:"What still needs correction, a request, or a boundary?"}},goDeeper:{sections:[{heading:"Where the letter framework comes from",paragraphs:["The Albert Ellis Institute’s professional explanation describes the event, beliefs, and consequences, followed by disputing rigid beliefs and developing a new effective philosophy [O12]. Later resilience training variants use “energization” for a final step [O14]. Those labels are not interchangeable descriptions of a guaranteed emotional change.","These sources document procedures. They do not establish the isolated efficacy of a brief adult ABCDE exercise. ODA uses a shorter sequence: describe the fact, inspect the belief, and carry out a proportionate response. Feelings also reflect conditions, loss, health, and support; a belief map is not a complete explanation of emotion.","For your continuing experiment, use the map only when it resolves an observed problem. You do not need five letters every time you act. If the concern is valid, the useful response may be practical problem solving or support rather than disputing it away."]},{heading:"A youth package is not this single exercise",paragraphs:["Brunwasser and colleagues reviewed 17 controlled Penn Resiliency Program studies involving 2,498 young people [O05]. Against no intervention, depressive-symptom effects were small: d = 0.11 immediately, 0.21 at six to eight months, and 0.20 at twelve months. Benefits over active controls and prevention of depressive diagnoses were not established.","The program taught multiple cognitive and behavioral skills. Those findings do not validate a single adult ABCDE round or predict the effect of ODA’s response exercise. Learning the framework, saving a plan, and sending a constructive reply remain separate events. Only the reported reply is evidence of that real action.","Keep the course experiment bounded to an ordinary, safe setback. A factual missed deadline can call for correction without becoming a statement about worth. Where a plan exceeds your time or resources, revise the demand or ask for help rather than repeating the same self-disputation."]}],sourceIds:["optimism-ellis-abc","optimism-reivich-mrt","optimism-brunwasser"]}},A={schemaVersion:2,revision:2,id:"optimism-4",courseId:"optimism",locale:"en",title:"No reply yet? Check what your worry knows",goal:"Distinguish a known fact from a prediction, then check one available fact about your setback.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"No answer, and your mind has supplied a verdict? Check one fact before planning around it.",reason:{id:"optimism-4-reason",label:"What evidence would change the next step you are taking?",kind:"text",maxLength:160,optional:!0,suggestions:["Check before guessing","Keep a real concern visible","Ask for the missing fact"]},why:{id:"optimism-4-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your setback. “No reply today” is known. “They have rejected me again” is a prediction unless evidence supports it. A balanced response keeps true concerns and missing information together. It can stay uncertain or unpleasant.","A documented thought record is a clinical tool. Evidence for full treatment does not prove a short worksheet works alone. Use a bounded check: known fact, guessed meaning, available evidence, next act. Ask a neutral question or correct the supported problem. Stop if repeated analysis increases distress. A lower worry rating is not required."],example:{title:"Maya's missing reply",text:"Maya has no reply to her revised section and knows her manager is traveling. At their scheduled check-in, she asks whether the budget explanation meets the brief. The answer is “Almost; add the assumption.” She makes that correction. She had feared a broader rejection, but her record keeps the actual feedback rather than declaring all her worries unfounded."}},move:{invitation:"Check one available fact about the same setback. Act on what it supports.",instructions:["Separate what is known from what is guessed.","Ask one neutral question or correct the supported problem."],prompts:[],suggestions:{action:["Ask one neutral status question","Check the actual requirement once","Correct the confirmed problem"],minimum:["Send one fact-checking sentence","Verify one relevant requirement","Fix one supported error"],cue:["At our scheduled safe check-in","When the relevant evidence is available","Before acting on the prediction"],place:["In the safe review channel","Beside the actual requirement"],fallback:["Choose a later suitable fact check","Request practical help instead","Stop repetitive analysis and pause"],observation:["What was known before the check","What the actual answer established","Whether my plan changed with evidence"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask one neutral status question",minimum:"Send one fact-checking sentence",minutes:2,cueHint:"At our scheduled safe check-in",placeHint:"In the safe review channel",obstacleHint:"I keep analyzing an uncertainty that needs actual information.",fallbackHint:"Choose a later suitable fact check",observationHint:"What was known before the check"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. Stop repetitive analysis; seek support.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-4-deadline-check-decision",scenario:"Maya has no reply to her draft. Her traveling manager can discuss it at today’s check-in. Submission closes in thirty minutes; either a correction or a backup proposal will take twenty.",question:"Which first move best uses the remaining time?",options:[{id:"optimism-4-submit-current",text:"Submit the current draft now because travel could explain the silence and the deadline is close.",feedback:"Submitting protects the deadline, but travel does not establish that the draft meets the brief. A brief check-in can identify a correction while leaving twenty minutes to make it."},{id:"optimism-4-check-uncertainty",text:"Keep the cause uncertain, ask about the draft at the check-in, and revise from the actual answer.",feedback:"This checks the relevant uncertainty while the manager is available and time remains to act. The answer may support correction or a backup. Reduced worry is not the test."},{id:"optimism-4-backup-and-timeline",text:"Start the backup proposal and message for a decision timeline while keeping both routes open.",feedback:"A backup preserves options when feedback is unavailable. Here the manager is available now, and either route takes twenty minutes. Check the draft first so the remaining time serves the supported need."}],bestOptionId:"optimism-4-check-uncertainty"}},carry:{takeaway:"A balanced response keeps the true worry, the uncertainty, and a useful way to check.",followUp:{questionId:"optimism-4-return",question:"What did the checked fact establish, and did your next plan change with that evidence?",observationPrompt:"What did the evidence establish, including what remains unknown?",adjustmentPrompt:"Which next step should change with that evidence?"}},goDeeper:{sections:[{heading:"Treatment evidence belongs to the package",paragraphs:["Hofmann and colleagues identified 269 CBT meta-analyses and reviewed 106 representative ones [O06]. These are review counts, not 269 isolated tests of thought records. The paper summarizes treatment packages with different components and problems; it has no single pooled participant count or universal effect for this exercise.","Treatment packages combine several methods and support. Their evidence cannot identify the effect of this brief fact check by itself. Use the check to answer a practical uncertainty: what requirement matters, whether a correction is needed, or when a decision will arrive. If no new information is available, keep the uncertainty visible instead of repeating the analysis.","The Beck Institute worksheet documents a clinical procedure [O13]. It does not independently establish its isolated effect. This lesson uses an abbreviated adaptation to make one prediction inspectable, then connects that inspection to the same practical action you are already working on."]},{heading:"Ratings are observations, not targets",paragraphs:["The documented thought-record procedure includes thought and emotion ratings, evidence, a balanced response, and subsequent ratings [O13]. Those numbers can describe what changed. A required drop would instead pressure you to record the preferred answer. The balanced response should fit the evidence even when concern remains credible.","ODA does not require a thinking-trap label or a particular emotional score. “Known” and “guessed” may be enough to choose one fact check. A supported concern can call for correction, a boundary, or practical support. Another reassuring rewrite is not always the next useful move.","NHS guidance describes CBT as structured professional treatment [O16]. Self-guided analysis that increases distress or repeats without new information can be stopped. Seek appropriate help when needed. Keep the actual answer and behavior in your course record, rather than using reduced worry as proof that the real task was done."]}],sourceIds:["optimism-hofmann","optimism-beck-thought-record","optimism-nhs-cbt"]}},S={schemaVersion:2,revision:2,id:"optimism-5",courseId:"optimism",locale:"en",title:"Canceled again? Stay curious and make a request",goal:"Examine a low-stakes assumption about your same setback, then make a clear safe request or boundary.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Canceled reviews feel personal? Stay curious without dropping the request you still need.",reason:{id:"optimism-5-reason",label:"What request or boundary remains necessary after reflection?",kind:"text",maxLength:160,optional:!0,suggestions:["Ask directly instead of guessing","Protect a needed boundary","Stay curious without taking all the blame"]},why:{id:"optimism-5-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Their motives can be uncertain while your need remains real. Bring back your setback. When a safe review is canceled, “They do not care” may go beyond the facts. “I need a review time I can use” can remain true.","A longer facilitated inquiry program has randomized evidence; that does not prove four self-guided questions work as treatment. Use inquiry only if useful, then make the request or boundary. You do not have to reverse a thought into self-blame or invent examples. Exclude danger and mistreatment. Curiosity does not require contact or surrendering protection."],example:{title:"Maya's clear review request",text:"Maya’s colleague cancels their report review twice. At 8:00, she questions her assumption that he does not care, without deciding the opposite is true. She sends, “Can you review by Thursday? If not, I will use another reviewer.” He cannot commit. Maya records her request and arranges another safe review. The disappointment remains."}},move:{invitation:"For this safe uncertainty, make the request or boundary your experiment needs.",instructions:["Keep genuine needs and limits visible.","Send one clear request; agreement is not your minimum."],prompts:[],suggestions:{action:["Ask for a workable review time","State one practical review boundary","Use another safe feedback route"],minimum:["Send one clear timing request","State one limit respectfully","Request one alternative review"],cue:["After a safe review cancellation","At our next suitable check-in","When the agreed limit is reached"],place:["In the safe review message thread","Through my usual communication channel"],fallback:["Choose another safe reviewer","Use practical support instead","Pause inquiry that increases distress"],observation:["The actual request I made","The reply including no agreement","Whether the boundary still fit"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask for a workable review time",minimum:"Send one clear timing request",minutes:2,cueHint:"After a safe review cancellation",placeHint:"In the safe review message thread",obstacleHint:"Reflection is replacing a direct request I still need.",fallbackHint:"Choose another safe reviewer",observationHint:"The actual request I made"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. No forced self-blame; pause distressing inquiry.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-5-decision",scenario:"A safe colleague has canceled Maya’s review twice. His reasons are unclear, and she needs feedback this week.",question:"Which response preserves curiosity and a useful limit?",options:[{id:"optimism-5-finish-alone",text:"Finish the review alone to reduce tension, then reconsider asking the colleague on a later project.",feedback:"Working independently can fit when review is optional or you have the skill. Here Maya still needs feedback this week. Ask for a workable time or use another safe reviewer."},{id:"optimism-5-flexible-slot",text:"Offer another flexible review slot and keep the arrangement open so the colleague can choose when available.",feedback:"Flexibility can preserve cooperation, but two cancellations and this week’s deadline make an open arrangement risky. Pair a workable time with an alternative so the real feedback need remains covered."},{id:"optimism-5-request-with-limit",text:"Keep his motives open, ask for a workable review time, and name an alternative if unavailable.",feedback:"This combines uncertainty with a clear practical need. The colleague may decline, and Maya can then use the alternative. Sending the request is her action; cooperation is an outcome she does not control."}],bestOptionId:"optimism-5-request-with-limit"}},carry:{takeaway:"Question the uncertain story while keeping the real request or boundary intact.",followUp:{questionId:"optimism-5-return",question:"What did your request or boundary change, and does the same limit still serve your direction?",observationPrompt:"What changed after your request or boundary, including no reply?",adjustmentPrompt:"Does the limit still fit, or should it change?"}},goDeeper:{sections:[{heading:"The randomized trial was intensive and facilitated",paragraphs:["Landau and colleagues tested inquiry-based stress reduction in a registered randomized trial of 100 women with BRCA variants [O11]. The intervention lasted twelve weeks, with weekly three-hour groups and one hour of assisted practice, compared with standard care. It reported benefits on some well-being outcomes, but the control did not match attention.","These findings do not establish that four brief self-guided questions are treatment, that the method equals CBT, or that results apply to abuse or trauma. The population, dose, and delivery differ substantially from this ordinary report-review example. A request needs a practical reason, not a promise of clinical improvement.","ODA’s request exercise is a teaching adaptation. If reflection helps, bring it back to the actual review you need. Ask for a usable time and keep an alternative available. You can finish the request while its effect stays unknown; another person’s cooperation is not a test of your optimism."]},{heading:"Optional inquiry, without forced reversals",paragraphs:["Byron Katie’s practitioner instructions use four questions: whether a thought is true, whether you can be certain, how holding it affects your response, and what changes when you loosen it [O15]. They then describe turnarounds with genuine examples. This is a procedure source, not evidence that the isolated questions are effective treatment.","Any reversal stays optional. You do not need a fixed count of examples, and you should not invent them. A reversal that shifts responsibility for harm onto you is not a required discovery. A clear request or a boundary can remain necessary after reflection, even when another person’s motives are uncertain.","Keep inquiry to safe, ordinary frustrations. NHS guidance provides professional routes for treatment [O16]; ODA does not replace them. Danger, abuse, self-harm concerns, and serious symptoms call for protection and appropriate support. You can stop this exercise and continue with a practical response."]}],sourceIds:["optimism-landau-inquiry","optimism-katie-instructions","optimism-nhs-cbt"]}},q={schemaVersion:2,revision:2,id:"optimism-6",courseId:"optimism",locale:"en",title:"Rough week? Keep the useful step going",goal:"Consolidate your same recovery experiment using actual attempts, helpful conditions, and one feasible next opportunity.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The week stayed hard. Which useful action or support is worth repeating?",reason:{id:"optimism-6-reason",label:"What helped your direction, and what problem still needs action?",kind:"text",maxLength:160,optional:!0,suggestions:["Repeat a helpful condition","Keep the unresolved problem visible","Choose one feasible next attempt"]},why:{id:"optimism-6-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Review your same setback and action. What did you do, what helped, and what remains unresolved? A hard week can contain useful support. Choose the next opportunity from those facts without demanding a positive feeling.","The original “three good things” study used three events and their causes nightly for one week. A replication found happiness gains with a positive placebo too, weakening claims that the named exercise uniquely works. You may notice one genuine helpful event here, or none. Keep your recovery experiment without a new nightly ritual."],example:{title:"Maya's useful cause to repeat",text:"On Friday, Maya’s report still needs approval. Her record shows one useful cause: asking another reviewer produced a specific correction. At her desk, she applies that correction and books the next suitable review. She notes the help without calling the week a success. Her next experiment keeps the same report, a smaller task, and an honest return date."}},move:{invitation:"Review your same experiment. Repeat one helpful condition and choose the next feasible recovery action.",instructions:["Keep unresolved problems visible alongside genuine help.","Choose one next attempt, support step, or pause."],prompts:[],suggestions:{action:["Apply the correction my feedback revealed","Repeat my useful recovery step","Ask for the support that helped"],minimum:["Fix one supported draft element","Complete one useful recovery unit","Send one specific support request"],cue:["At my next suitable draft session","When useful feedback is available","At my chosen support opening"],place:["In my existing draft","In the safe support channel"],fallback:["Shrink the actual recovery step","Pause and choose a return date","Use another feasible support route"],observation:["What helped the actual action","What problem remained unresolved","Whether the next step fit my week"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Apply the correction my feedback revealed",minimum:"Fix one supported draft element",minutes:2,cueHint:"At my next suitable draft session",placeHint:"In my existing draft",obstacleHint:"I am adding rituals instead of improving the useful action.",fallbackHint:"Shrink the actual recovery step",observationHint:"What helped the actual action"},stopRule:"Exclude danger, abuse, self-harm, and serious symptoms. Stop repetitive analysis; seek support.",accessibleAlternative:"Use your usual communication method, practical help, or a safe boundary."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"optimism-6-correction-scope-decision",scenario:"Maya’s reviewer identified one missing assumption and confirmed the rest of her report meets the brief. She has twenty minutes for the five-minute correction before submission closes; approval remains uncertain.",question:"Which next act best uses the helpful feedback?",options:[{id:"optimism-6-repeat-helpful-cause",text:"Apply the confirmed correction, submit within the window, and record the result without predicting approval.",feedback:"This uses the specific feedback while keeping approval uncertain. The correction fits the available time and serves the same report. Record what was changed and any response, including none."},{id:"optimism-6-check-scope",text:"Request another scope check from the reviewer before revising, so she avoids overlooking a wider problem.",feedback:"Another check can help when the scope is unclear. Here the reviewer already confirmed it. Waiting could consume the submission window without resolving a new uncertainty; use the specific correction first."},{id:"optimism-6-request-extension",text:"Request a short extension so she can review the entire report before applying the correction.",feedback:"An extension can protect work when time or capacity is insufficient. Here the identified correction fits. Requesting more time adds coordination without addressing a stated obstacle; broader review can wait."}],bestOptionId:"optimism-6-repeat-helpful-cause"}},carry:{takeaway:"Carry forward a helpful cause and a feasible action. Let the week’s difficulty remain true.",followUp:{questionId:"optimism-6-return",question:"Did repeating the helpful condition support your next action, and what still needs correction, support, or stopping?",observationPrompt:"What condition helped, and what remains unresolved?",adjustmentPrompt:"Repeat that condition, change the act, get support, or stop?"}},goDeeper:{sections:[{heading:"Three events plus causes was the studied procedure",paragraphs:["Seligman and colleagues’ original online trial asked participants to record three things that went well and why each happened, nightly for one week [O07]. It began with 577 respondents, but the analysis used 411 follow-up completers, largely White, educated online volunteers. The exercises and an early-memory comparison were randomized; continued practice was not.","The original trial reported changes on happiness and depression questionnaires. It does not establish that continued practice caused later maintenance, that ten minutes is a required dose, or that gratitude treats depression. A later replication found happiness improvements with a positive placebo as well and did not demonstrate a distinctive depression benefit [O08].","You can choose the original week-long exercise separately if it fits. Noticing one good or neutral event, or pausing on a difficult night, is a humane adaptation rather than the tested procedure. This course ending instead consolidates your existing recovery action."]},{heading:"A useful next week can remain uncertain",paragraphs:["The resilience-training program description documents considering worst, best, and most-likely possibilities before making a plan [O14]. It does not establish standalone efficacy for that short exercise. Use it only if a specific uncertainty in your existing experiment needs planning, rather than adding it as another required ritual.","Realistic attention keeps both the useful condition and the remaining problem. A reviewer’s help can matter while the report remains unapproved. The helpful cause may be asking a specific question, making time available, or using support. Repeat it only when it fits the next opportunity; no feeling of gratitude is required.","Review the same factual records before next week. Keep a meaningful minimum, a recognizable cue, and a fallback you can use. Choose support, rest, a boundary, or stopping when appropriate. Future plans, reflection, and quiz answers remain separate from actual attempts. Bring back what happened, including uncertainty or no reply."]}],sourceIds:["optimism-three-good-things","optimism-mongrain","optimism-reivich-mrt"]}},Y={id:"optimism",title:"One setback taking over? Find your next useful step",subtitle:"Six lessons to examine one setback, take a proportionate recovery step, and learn from the actual result.",description:"Bring one ordinary setback back into proportion. Keep the painful facts, check uncertain interpretations, and choose a practical response that serves the life you want.",outcome:"One setback examined fairly, a recovery action you can try, and a return plan grounded in what actually happened.",scope:"For adults who tend to give up, blame themselves or expect the worst after setbacks. The course draws on Martin Seligman’s learned optimism, cognitive behavioral therapy (CBT) and Byron Katie’s The Work. It is self-help, not a treatment for depression, anxiety or any other condition, and it does not replace therapy or medication. If hopelessness persists or ordinary days become hard to get through, talk to a doctor or mental health professional. You can seek help sooner. For thoughts of suicide or an emotional crisis in the US, call or text 988; elsewhere use local crisis support. For immediate danger, use local emergency services.",photo:{id:"1465188162913-8fb5709d6d57",alt:"A woman walking along a hilltop path in golden evening light"},lessons:[{id:"optimism-1",schemaVersion:2,v2:k,title:"Rejected? Test one part you can influence",minutes:6,goal:"Choose a low-stakes setback and take one useful step within your actual influence.",reading:["A setback and your next available move are different things. You cannot make someone approve your work. You may be able to ask which requirement was missed, practice a skill, or seek support. Choose one part you can test rather than declaring the whole situation controllable.","Research interventions have changed optimism scores on average. That measures expectations, not proof that a rejection will reverse. This course follows one ordinary setback and one recovery action. Save the step, actually try it, and record the response, including no response. A calendar entry is preparation; asking the question is the act."],practice:["Choose an ordinary setback. Try one available step, then record what happened.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Which available step have you ruled out, and what evidence supports that?",question:"Maya’s draft was rejected without a reason. She has ten minutes before the reviewer’s question window closes. A revision needs two hours; she wants to know whether it is worth doing. Which step best informs that decision now?",options:["Inspect the old brief for ten minutes, then revise the requirement she thinks caused the rejection.","Ask which requirement was missed, then use the answer to choose one feasible corrective step.","Send a ten-minute partial rewrite now to demonstrate initiative before the question window closes."],correct:1,feedback:"This uses an available information source before it closes. A reply may justify revising, seeking help, or stopping. Sending the question counts as the act; getting a reply does not.",takeaway:"After a setback, test one part you can influence and record what it actually changes.",sources:["optimism-maier-seligman","optimism-malouff-schutte","optimism-nimh-support"],deeper:[{heading:"The animal account was revised",paragraphs:["Maier and Seligman’s 2016 review revisits the learned-helplessness explanation using decades of animal research [O01]. In the reviewed aversive paradigms, prolonged stimulation produces passivity, while detecting control engages protective circuitry. This revised account concerns rats or dogs exposed to prolonged aversive events, not a direct experiment on an adult’s ordinary rejected draft.","It does not establish that freezing is every person’s default, that all helplessness has one mechanism, or that listing controllable tasks reverses a clinical condition. This lesson therefore starts with a practical distinction rather than assigning your reaction a brain explanation: the reviewer’s decision and the question you can send are different events.","ODA’s one-step recovery experiment is an adaptation. You may discover the available lever does little, or that the constraints require help or a different direction. Keep that result. A real attempt provides information without promising restored hope."]},{heading:"Changed expectations are not guaranteed outcomes",paragraphs:["Malouff and Schutte combined 29 randomized studies involving 3,319 participants [O03]. Psychological interventions increased optimism scores on average, with g = 0.41. Methods, delivery, and follow-up varied; shorter follow-up and completer analyses produced larger effects. This average describes study groups, not how much your expectations will change after one attempt.","The review does not show permanent personality change, better objective outcomes, or the effect of this ODA course. A feedback request tests a requirement. It cannot promise future acceptance. The answer can still help you decide whether the revision deserves your time, needs support, or no longer fits.","Your next step may be support rather than another task. NIMH guidance recommends professional evaluation for persistent symptoms or impaired functioning [O20]. You can ask for help before completing lessons and without waiting for a duration threshold. An actual help request can be a meaningful action in its own right."]}],example:{title:"Maya's unanswered feedback request",text:"Maya’s draft is rejected, and she considers abandoning a project she cares about. At 12:30, in a safe team message thread, she asks, “Which requirement should I fix first?” She gets no reply that afternoon. Her record says the question was sent. She has tested a feedback request, not proved the project will be accepted."},photo:{id:"1527580094867-0e719f119120",alt:"A hiker crossing grey rocks in the early morning, waiting for sunrise"}},{id:"optimism-2",schemaVersion:2,v2:x,title:"One setback becoming your whole story? Get specific",minutes:6,goal:"Keep the true cause of your setback and try one correction without a global self-verdict.",reading:["Bring back your setback and recorded response. Explanations that treat setbacks as lasting, affecting many parts of life, and caused by something about you are associated with depression. Association does not prove causation or make every painful explanation wrong.","Ask: how long might the cause last, which part of life does it affect, and what is yours or unknown? A durable skill gap can be real. Name it without making one draft a verdict on everything. Test one correction. Keep responsibility and uncertainty rather than forcing a reassuring cause."],practice:["Use the same setback. Name one accurate cause, then perform the correction it suggests.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What part is yours to change, and what remains uncertain?",question:"Maya’s reviewer names one missing budget assumption. The rest meets the brief. She has ten minutes to revise before review closes and thinks the gap proves she cannot do this work. Which response fits the evidence and deadline?",options:["Rewrite the whole budget section now so the reviewer can judge a fully fresh version.","Ask the reviewer to restate the missing assumption, then wait for clarification before changing the section.","Keep the budget gap as true, correct one element, and leave the wider career conclusion unproven."],correct:2,feedback:"This owns the supported gap and uses the short window to address it. Ask whether the correction meets the requirement. Further feedback stays evidence about this draft, not a career verdict.",takeaway:"An accurate explanation can be uncomfortable and still point to a useful correction.",sources:["optimism-sweeney","optimism-beck-thought-record","optimism-nhs-cbt"],deeper:[{heading:"Questions, not reassuring answers",paragraphs:["Sweeney and colleagues reviewed 104 studies with nearly 15,000 participants [O02]. Depression was associated with internal, stable, and global explanations for negative events across varied samples and tasks. These dimensions concern personal contribution, lasting causes, and broad effects; they do not require a setback to have only one cause. The association does not show which factor caused which.","This lesson uses the dimensions to inspect an explanation, not to prescribe a cheerful result. A long-term constraint may remain long-term. Your own missed requirement may remain yours to correct. Shared causes may be present, and some causes may still be unknown. Replacing every explanation with “temporary and outside me” would lose accuracy.","Bring the question back to the same course experiment. Which part can you correct, check, or get help with? A specific action is easier to test than a broad claim about ability. Keep the record of the action separate from your interpretation of its outcome."]},{heading:"A fair response still allows a real problem",paragraphs:["The Beck Institute’s thought-record procedure documents evidence, alternatives, a balanced response, and subsequent observations [O13]. It is a clinical worksheet, not proof that this short explanation exercise independently improves mood. ODA’s brief adaptation has no established isolated treatment effect. Use it to identify a supported correction, rather than requiring a reassuring explanation.","A balanced account can include unpleasant facts. The budget section may be incomplete, the deadline may be tight, or the skill may need practice. It can also include what is not known. The next behavior might be correction, a neutral question, or a request for support rather than another reassuring sentence.","NHS guidance describes CBT as structured treatment with professional routes to help [O16]. This course is education. If repeated self-guided analysis increases distress or interferes with functioning, stop the exercise and seek appropriate assistance. Safety and practical needs take priority over an optimism label."]}],example:{title:"Maya's specific correction",text:"Maya learns that her rejected draft did not answer the client’s budget question. At 7:00, she replaces “I am no good at this” with a specific account: the budget section was incomplete. She adds one usable explanation and sends it for review. The reviewer still wants more detail. Her correction is real, and the overall result stays open."},photo:{id:"1509029032154-54ba8b3216d4",alt:"A man in glasses looking thoughtfully out of a window"}},{id:"optimism-3",schemaVersion:2,v2:T,title:"Angry reply ready? Separate fact from verdict",minutes:6,goal:"Examine your same setback briefly, then send or make one constructive response you can stand behind.",reading:["A missed deadline is a fact. “I cannot do this job” is a wider belief. A documented framework separates event, belief, and the feelings or behavior that follow. Thoughts can influence your response, but do not explain every emotion.","Bring back your setback. State one neutral fact, check the belief against evidence, and choose a useful response. If the concern is true, keep it and solve that part. A fair reply can include accountability, a request, or a boundary. Act without requiring embarrassment or anger to disappear."],practice:["Use the same setback. Check the belief briefly, then carry out one fair response.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Which response would serve your direction tomorrow as well as today?",question:"Maya’s manager correctly says she missed a deadline. Maya thinks, “I cannot do this job,” and wants to defend herself. What best uses a fair belief check?",options:["Name the missed deadline, leave the career verdict unproven, and agree one realistic corrective step.","Review her favorable past feedback until the criticism feels less threatening, then decide whether to answer.","Explain the pressure she was under and ask for recognition of her effort before discussing a correction."],correct:0,feedback:"This keeps the supported fact and tests the wider conclusion. A realistic corrective response follows even if embarrassment remains. The manager’s approval is an outcome to observe, not a completion requirement.",takeaway:"Keep the true fact. Test the wider verdict. Act on the useful conclusion.",sources:["optimism-ellis-abc","optimism-reivich-mrt","optimism-brunwasser"],deeper:[{heading:"Where the letter framework comes from",paragraphs:["The Albert Ellis Institute’s professional explanation describes the event, beliefs, and consequences, followed by disputing rigid beliefs and developing a new effective philosophy [O12]. Later resilience training variants use “energization” for a final step [O14]. Those labels are not interchangeable descriptions of a guaranteed emotional change.","These sources document procedures. They do not establish the isolated efficacy of a brief adult ABCDE exercise. ODA uses a shorter sequence: describe the fact, inspect the belief, and carry out a proportionate response. Feelings also reflect conditions, loss, health, and support; a belief map is not a complete explanation of emotion.","For your continuing experiment, use the map only when it resolves an observed problem. You do not need five letters every time you act. If the concern is valid, the useful response may be practical problem solving or support rather than disputing it away."]},{heading:"A youth package is not this single exercise",paragraphs:["Brunwasser and colleagues reviewed 17 controlled Penn Resiliency Program studies involving 2,498 young people [O05]. Against no intervention, depressive-symptom effects were small: d = 0.11 immediately, 0.21 at six to eight months, and 0.20 at twelve months. Benefits over active controls and prevention of depressive diagnoses were not established.","The program taught multiple cognitive and behavioral skills. Those findings do not validate a single adult ABCDE round or predict the effect of ODA’s response exercise. Learning the framework, saving a plan, and sending a constructive reply remain separate events. Only the reported reply is evidence of that real action.","Keep the course experiment bounded to an ordinary, safe setback. A factual missed deadline can call for correction without becoming a statement about worth. Where a plan exceeds your time or resources, revise the demand or ask for help rather than repeating the same self-disputation."]}],example:{title:"Maya's accountable reply",text:"Maya misses the revised report deadline. At 6:30, she starts a defensive reply, then separates the fact from “I cannot do this job.” She sends, “I missed today’s deadline. I can deliver the corrected section by noon tomorrow; does that fit?” Her manager accepts the time but remains frustrated. Maya records the actual agreement and her unfinished work."},photo:{id:"1643148636630-0b0fb138fc74",alt:"A person writing in a notebook with a pen"}},{id:"optimism-4",schemaVersion:2,v2:A,title:"No reply yet? Check what your worry knows",minutes:6,goal:"Distinguish a known fact from a prediction, then check one available fact about your setback.",reading:["Bring back your setback. “No reply today” is known. “They have rejected me again” is a prediction unless evidence supports it. A balanced response keeps true concerns and missing information together. It can stay uncertain or unpleasant.","A documented thought record is a clinical tool. Evidence for full treatment does not prove a short worksheet works alone. Use a bounded check: known fact, guessed meaning, available evidence, next act. Ask a neutral question or correct the supported problem. Stop if repeated analysis increases distress. A lower worry rating is not required."],practice:["Check one available fact about the same setback. Act on what it supports.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What evidence would change the next step you are taking?",question:"Maya has no reply to her draft. Her traveling manager can discuss it at today’s check-in. Submission closes in thirty minutes; either a correction or a backup proposal will take twenty. Which first move best uses the remaining time?",options:["Submit the current draft now because travel could explain the silence and the deadline is close.","Keep the cause uncertain, ask about the draft at the check-in, and revise from the actual answer.","Start the backup proposal and message for a decision timeline while keeping both routes open."],correct:1,feedback:"This checks the relevant uncertainty while the manager is available and time remains to act. The answer may support correction or a backup. Reduced worry is not the test.",takeaway:"A balanced response keeps the true worry, the uncertainty, and a useful way to check.",sources:["optimism-hofmann","optimism-beck-thought-record","optimism-nhs-cbt"],deeper:[{heading:"Treatment evidence belongs to the package",paragraphs:["Hofmann and colleagues identified 269 CBT meta-analyses and reviewed 106 representative ones [O06]. These are review counts, not 269 isolated tests of thought records. The paper summarizes treatment packages with different components and problems; it has no single pooled participant count or universal effect for this exercise.","Treatment packages combine several methods and support. Their evidence cannot identify the effect of this brief fact check by itself. Use the check to answer a practical uncertainty: what requirement matters, whether a correction is needed, or when a decision will arrive. If no new information is available, keep the uncertainty visible instead of repeating the analysis.","The Beck Institute worksheet documents a clinical procedure [O13]. It does not independently establish its isolated effect. This lesson uses an abbreviated adaptation to make one prediction inspectable, then connects that inspection to the same practical action you are already working on."]},{heading:"Ratings are observations, not targets",paragraphs:["The documented thought-record procedure includes thought and emotion ratings, evidence, a balanced response, and subsequent ratings [O13]. Those numbers can describe what changed. A required drop would instead pressure you to record the preferred answer. The balanced response should fit the evidence even when concern remains credible.","ODA does not require a thinking-trap label or a particular emotional score. “Known” and “guessed” may be enough to choose one fact check. A supported concern can call for correction, a boundary, or practical support. Another reassuring rewrite is not always the next useful move.","NHS guidance describes CBT as structured professional treatment [O16]. Self-guided analysis that increases distress or repeats without new information can be stopped. Seek appropriate help when needed. Keep the actual answer and behavior in your course record, rather than using reduced worry as proof that the real task was done."]}],example:{title:"Maya's missing reply",text:"Maya has no reply to her revised section and knows her manager is traveling. At their scheduled check-in, she asks whether the budget explanation meets the brief. The answer is “Almost; add the assumption.” She makes that correction. She had feared a broader rejection, but her record keeps the actual feedback rather than declaring all her worries unfounded."},photo:{id:"1681396059172-7532b1ef8b47",alt:"An open journal lying on a table in soft morning light"}},{id:"optimism-5",schemaVersion:2,v2:S,title:"Canceled again? Stay curious and make a request",minutes:6,goal:"Examine a low-stakes assumption about your same setback, then make a clear safe request or boundary.",reading:["Their motives can be uncertain while your need remains real. Bring back your setback. When a safe review is canceled, “They do not care” may go beyond the facts. “I need a review time I can use” can remain true.","A longer facilitated inquiry program has randomized evidence; that does not prove four self-guided questions work as treatment. Use inquiry only if useful, then make the request or boundary. You do not have to reverse a thought into self-blame or invent examples. Exclude danger and mistreatment. Curiosity does not require contact or surrendering protection."],practice:["For this safe uncertainty, make the request or boundary your experiment needs.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What request or boundary remains necessary after reflection?",question:"A safe colleague has canceled Maya’s review twice. His reasons are unclear, and she needs feedback this week. Which response preserves curiosity and a useful limit?",options:["Finish the review alone to reduce tension, then reconsider asking the colleague on a later project.","Offer another flexible review slot and keep the arrangement open so the colleague can choose when available.","Keep his motives open, ask for a workable review time, and name an alternative if unavailable."],correct:2,feedback:"This combines uncertainty with a clear practical need. The colleague may decline, and Maya can then use the alternative. Sending the request is her action; cooperation is an outcome she does not control.",takeaway:"Question the uncertain story while keeping the real request or boundary intact.",sources:["optimism-landau-inquiry","optimism-katie-instructions","optimism-nhs-cbt"],deeper:[{heading:"The randomized trial was intensive and facilitated",paragraphs:["Landau and colleagues tested inquiry-based stress reduction in a registered randomized trial of 100 women with BRCA variants [O11]. The intervention lasted twelve weeks, with weekly three-hour groups and one hour of assisted practice, compared with standard care. It reported benefits on some well-being outcomes, but the control did not match attention.","These findings do not establish that four brief self-guided questions are treatment, that the method equals CBT, or that results apply to abuse or trauma. The population, dose, and delivery differ substantially from this ordinary report-review example. A request needs a practical reason, not a promise of clinical improvement.","ODA’s request exercise is a teaching adaptation. If reflection helps, bring it back to the actual review you need. Ask for a usable time and keep an alternative available. You can finish the request while its effect stays unknown; another person’s cooperation is not a test of your optimism."]},{heading:"Optional inquiry, without forced reversals",paragraphs:["Byron Katie’s practitioner instructions use four questions: whether a thought is true, whether you can be certain, how holding it affects your response, and what changes when you loosen it [O15]. They then describe turnarounds with genuine examples. This is a procedure source, not evidence that the isolated questions are effective treatment.","Any reversal stays optional. You do not need a fixed count of examples, and you should not invent them. A reversal that shifts responsibility for harm onto you is not a required discovery. A clear request or a boundary can remain necessary after reflection, even when another person’s motives are uncertain.","Keep inquiry to safe, ordinary frustrations. NHS guidance provides professional routes for treatment [O16]; ODA does not replace them. Danger, abuse, self-harm concerns, and serious symptoms call for protection and appropriate support. You can stop this exercise and continue with a practical response."]}],example:{title:"Maya's clear review request",text:"Maya’s colleague cancels their report review twice. At 8:00, she questions her assumption that he does not care, without deciding the opposite is true. She sends, “Can you review by Thursday? If not, I will use another reviewer.” He cannot commit. Maya records her request and arranges another safe review. The disappointment remains."},photo:{id:"1503541517233-120571491cf3",alt:"A man sitting on a park bench with his eyes closed, surrounded by trees"}},{id:"optimism-6",schemaVersion:2,v2:q,title:"Rough week? Keep the useful step going",minutes:6,goal:"Consolidate your same recovery experiment using actual attempts, helpful conditions, and one feasible next opportunity.",reading:["Review your same setback and action. What did you do, what helped, and what remains unresolved? A hard week can contain useful support. Choose the next opportunity from those facts without demanding a positive feeling.","The original “three good things” study used three events and their causes nightly for one week. A replication found happiness gains with a positive placebo too, weakening claims that the named exercise uniquely works. You may notice one genuine helpful event here, or none. Keep your recovery experiment without a new nightly ritual."],practice:["Review your same experiment. Repeat one helpful condition and choose the next feasible recovery action.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What helped your direction, and what problem still needs action?",question:"Maya’s reviewer identified one missing assumption and confirmed the rest of her report meets the brief. She has twenty minutes for the five-minute correction before submission closes; approval remains uncertain. Which next act best uses the helpful feedback?",options:["Apply the confirmed correction, submit within the window, and record the result without predicting approval.","Request another scope check from the reviewer before revising, so she avoids overlooking a wider problem.","Request a short extension so she can review the entire report before applying the correction."],correct:0,feedback:"This uses the specific feedback while keeping approval uncertain. The correction fits the available time and serves the same report. Record what was changed and any response, including none.",takeaway:"Carry forward a helpful cause and a feasible action. Let the week’s difficulty remain true.",sources:["optimism-three-good-things","optimism-mongrain","optimism-reivich-mrt"],deeper:[{heading:"Three events plus causes was the studied procedure",paragraphs:["Seligman and colleagues’ original online trial asked participants to record three things that went well and why each happened, nightly for one week [O07]. It began with 577 respondents, but the analysis used 411 follow-up completers, largely White, educated online volunteers. The exercises and an early-memory comparison were randomized; continued practice was not.","The original trial reported changes on happiness and depression questionnaires. It does not establish that continued practice caused later maintenance, that ten minutes is a required dose, or that gratitude treats depression. A later replication found happiness improvements with a positive placebo as well and did not demonstrate a distinctive depression benefit [O08].","You can choose the original week-long exercise separately if it fits. Noticing one good or neutral event, or pausing on a difficult night, is a humane adaptation rather than the tested procedure. This course ending instead consolidates your existing recovery action."]},{heading:"A useful next week can remain uncertain",paragraphs:["The resilience-training program description documents considering worst, best, and most-likely possibilities before making a plan [O14]. It does not establish standalone efficacy for that short exercise. Use it only if a specific uncertainty in your existing experiment needs planning, rather than adding it as another required ritual.","Realistic attention keeps both the useful condition and the remaining problem. A reviewer’s help can matter while the report remains unapproved. The helpful cause may be asking a specific question, making time available, or using support. Repeat it only when it fits the next opportunity; no feeling of gratitude is required.","Review the same factual records before next week. Keep a meaningful minimum, a recognizable cue, and a fallback you can use. Choose support, rest, a boundary, or stopping when appropriate. Future plans, reflection, and quiz answers remain separate from actual attempts. Bring back what happened, including uncertainty or no reply."]}],example:{title:"Maya's useful cause to repeat",text:"On Friday, Maya’s report still needs approval. Her record shows one useful cause: asking another reviewer produced a specific correction. At her desk, she applies that correction and books the next suitable review. She notes the help without calling the week a success. Her next experiment keeps the same report, a smaller task, and an honest return date."},photo:{id:"1750885847789-f5748b585e3a",alt:"A woman on a balcony looking out over a city"}}]},te=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Y,OPTIMISM_1_V2:k,OPTIMISM_2_V2:x,OPTIMISM_3_V2:T,OPTIMISM_4_V2:A,OPTIMISM_5_V2:S,OPTIMISM_6_V2:q,SOURCES:B},Symbol.toStringTag,{value:"Module"})),V=[{id:"stoic-epictetus-iep",title:"S09 · Seddon · Epictetus · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epictetus’s distinction between what is and is not up to us offers philosophical guidance for directing effort toward judgments, aims, and conduct.",limitation:"History and philosophy, not psychological evidence that thoughts or conduct are fully voluntary. Disability, illness, coercion, and resources constrain action."},{id:"stoic-seneca-iep",title:"S10 · Wagoner · Seneca · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca’s philosophical account of anger distinguishes involuntary first movements from later assent.",limitation:"This is historical philosophy, not a validated complete model of emotion. It does not mean panic or trauma symptoms can be chosen away or are moral failures."},{id:"stoic-week-handbook",title:"S08 · Stoicism Today · Stoic Week 2016 handbook",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"Documents the control distinction, adversity contemplation, wider perspective, and a fair five-to-ten-minute evening review before getting into bed.",limitation:"A practitioner manual, not a trial of isolated rituals or optimal doses. No verified independent effect for control-sort, negative imagery, cosmic perspective, or evening review."},{id:"stoic-planning",title:"S03 · Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests with 8,461 participants found average goal-attainment benefits from specified situation-response plans, d = 0.65 [0.60, 0.70].",limitation:"Varied goals, designs, and comparisons; not restricted to modern preregistered randomized trials. This is not a success percentage, a guarantee, or evidence for negative visualization."},{id:"stoic-mcii",title:"S04 · Wang, Wang & Gai · 2021 · Mental contrasting with planning",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles provided 24 independent estimates from 15,907 participants. Desired outcome, present obstacle, and if–then response produced average goal-attainment g = 0.336 [0.229, 0.443].",limitation:"Meaningful heterogeneity, I² = 59.3%, and uneven quality limit precision. This does not isolate negative visualization, prove every goal feasible, or validate ODA’s brief adaptation."},{id:"stoic-thought-record",title:"S11 · NHS · Thought record · Every Mind Matters",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/",type:"guidance",finding:"Seven prompts separate situation, feelings, thought, evidence for, evidence against, a realistic alternative, and feelings afterward. A neutral conclusion can be appropriate.",limitation:"Official self-help guidance, not an isolated effect-size study. It does not require positivity or interpreting actual mistreatment as harmless."},{id:"stoic-cbt",title:"S01 · Hofmann et al. · 2012 · Review of CBT meta-analyses",url:"https://www.europsy.net/app/uploads/2017/08/Hofmann-2012-The-efficacy-of-CBT-a-review-of-meta-analyses.pdf",type:"research",finding:"The authors identified 269 meta-analyses and discussed a representative 106, with strong disorder-specific evidence for several anxiety-related conditions, anger, and stress.",limitation:"A narrative overview, without one pooled CBT effect or participant count. Treatment evidence does not transfer to a Stoic lesson or isolate a brief thought record."},{id:"stoic-kross-self-talk",title:"S05 · Kross et al. · 2014 · Self-talk as a regulatory mechanism",url:"https://rascl.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Seven studies totaling 585 participants examined non-first-person introspection. Study 1a used 60 seconds of reflection and found increased reported self-distancing.",limitation:"Convergent experiments within one research program, not seven independent clinical trials. Using a name is not a proven treatment, and the mild current-situation ODA exercise is an adaptation."},{id:"stoic-kross-distancing",title:"S06 · Murdoch et al. · 2023 · Self-distanced reflections meta-analysis",url:"https://onlinelibrary.wiley.com/doi/full/10.1002/smi.3199",type:"research",finding:"25 experiments in 17 papers, with 2,397 participants, found a modest pooled effect, g = 0.19 [0.05, 0.33], across varied outcomes.",limitation:"Predominantly young, apparently healthy adults; uncertain quality and substantial heterogeneity. Prediction interval crossed zero. Objective outcomes were nonsignificant, and cosmic or ten-year rituals were not isolated."},{id:"stoic-distancing-sleep",title:"S16 · Riddell et al. · 2023 · Stressor reflections and sleep",url:"https://onlinelibrary.wiley.com/doi/10.1002/smi.3201",type:"research",finding:"A preregistered reflection experiment did not support a sleep benefit from distancing. Sleep-quality change favored immersion; sleep-duration difference was nonsignificant.",limitation:"318 baseline participants and 257 analyzed, with 51 distanced participants excluded for first-person writing. Inconsistent table and narrative signs prevent a directional well-being claim."},{id:"stoic-training-trial",title:"S13 · Maclellan & Derakshan · 2021 · Training in high worriers",url:"https://link.springer.com/article/10.1007/s10608-020-10183-4",type:"research",finding:"45 high worriers were randomized across eight-session Stoic training, a combined training arm, and an active one-back control. The abstract reports changes in rumination and self-efficacy.",limitation:"A small study with abstract-only access here. Exact effects, confidence intervals, attrition, and registration were not verified. It does not isolate a ritual or establish treatment for diagnosed anxiety."},{id:"stoic-training-thesis",title:"S15 · King · 2025 · Modern Stoicism and mental health thesis",url:"https://pure.royalholloway.ac.uk/en/publications/modern-stoicism-and-mental-health-a-randomised-controlled-trial/",type:"research",finding:"119 nonclinical adults were allocated to two-week online Stoic training or a waitlist. The institutional abstract reports favorable complete-case changes on some mental-health measures.",limitation:"One unpublished doctoral thesis, not a peer-reviewed efficacy consensus. Completer counts, effects, intervals, and registration were unverified; waitlist comparison does not establish isolated ritual effects or psychotherapy equivalence."}],I=[{schemaVersion:2,revision:2,id:"stoic-1",courseId:"stoic",locale:"en",title:"Still checking for an answer you cannot decide?",goal:"Create one useful piece for a chosen goal while its outcome remains uncertain.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Refreshing the reply again? Give the action that could help your goal some of that attention.",reason:{id:"stoic-1-reason",label:"What useful act has checking the outcome displaced?",kind:"text",maxLength:160,optional:!0,suggestions:["Build evidence for my goal","Stop refreshing for reassurance","Ask for practical help"]},why:{id:"stoic-1-why",label:"What useful act has checking the outcome displaced?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["An outcome can matter without being yours to determine. Epictetus used this distinction to direct effort toward conduct rather than reputation or results. It is philosophy, not proof that every thought and action is completely voluntary. Health, coercion, disability, and resources can limit what you can do.","Choose one goal and one useful act for this course’s continuing experiment. Separate what you can attempt, what needs support, and what others decide. Then do your feasible part. A portfolio sentence exists even if no employer replies. Use outcomes as information; you do not have to stop caring about them."],example:{title:"Daniel’s evidence sentence",text:"At Monday lunch, Daniel has refreshed an application inbox four times. He wants useful project evidence for a job, so at his desk he writes one concrete portfolio sentence. It describes a checklist he improved and how it was used. He records the sentence. The inbox stays empty, and he still feels uncertain."}},move:{invitation:"Choose one useful act while the outcome stays uncertain.",instructions:["Sort action, needed support, and outcome without demanding total control.","Do your feasible part and record it."],prompts:[],suggestions:{action:["Write one relevant project evidence sentence","Send one appropriate clarification question","Make one practical support request"],minimum:["Produce one usable evidence sentence","Send one clear question","Make one specific support request"],cue:["When I return from lunch","At my next safe opening","Before the next project step"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use a voice note for the sentence","Choose a smaller relevant contribution","Ask for help with access"],observation:["The useful piece I produced","The question and any response","What support I requested"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one relevant project evidence sentence",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When I return from lunch",placeHint:"At my usual work surface",obstacleHint:"My available energy or resources are limited.",fallbackHint:"Use a voice note for the sentence",observationHint:"The useful piece I produced"},stopRule:"Do not practice through danger. Seek protection or support when action is constrained.",accessibleAlternative:"Use dictation, assisted communication, a safe boundary, or practical support."},result:{question:"Did you do your feasible minimum?",observationPrompt:"What did you produce or ask, and what remains undecided?"},judgment:{primary:{id:"stoic-1-decision",scenario:"Daniel has ten minutes after lunch and no urgent reply due. His application opening is clear, but a recruiter asked for specific project evidence. He has a relevant example to describe.",question:"Where should these minutes go?",options:[{id:"keep-checking",text:"Check the inbox every few minutes so a potential employer receives an immediate response.",feedback:"Being reachable may matter. Here no urgent reply is expected, and useful evidence is available to create. Choose a check time and give the sentence a turn."},{id:"write-evidence",text:"Write the relevant evidence sentence now, then check the inbox at a chosen time.",feedback:"This invests in a feasible act without promising an offer. Record the sentence, keep necessary contact access, and treat a later response as information."},{id:"revise-opening",text:"Revise the opening paragraph for ten minutes so the application presents his project more clearly.",feedback:"A clearer opening helps when the introduction is confusing. Here the opening is clear and specific evidence is missing. Produce that evidence now; revise the introduction if later feedback identifies a problem."}],bestOptionId:"write-evidence"}},carry:{takeaway:"Care about the outcome. Give your feasible part an actual attempt.",followUp:{questionId:"stoic-1-return",question:"What useful piece or request happened, and what support constraint remained?",observationPrompt:"Name the piece or request, or note why it remained unavailable.",adjustmentPrompt:"What support or cue fits the next attempt?"}},goDeeper:{sections:[{heading:"A guide to effort, with an influence middle",paragraphs:["The scholarly account of Epictetus describes judgments, aims, and conduct as up to us, contrasted with externals such as reputation [S09]. He was born enslaved in Hierapolis and later taught at Nicopolis; Arrian recorded his teachings. Those historical facts explain the tradition, not the effectiveness of a modern worksheet. The distinction can orient effort without establishing that a person always has complete voluntary control over attention, feelings, or conduct.","ODA uses an adaptation with room between total control and helplessness: what you can attempt, what you might influence with help, and what you cannot determine alone. The Stoic Week handbook documents the control distinction as a practice [S08]. It is guidance, not an isolated trial. A workplace problem might need collective action. A health problem may need assessment and care. A harmful interaction may require protection. None of these becomes a private attitude failure because another person or circumstance contributes to the outcome."]},{heading:"Make your part observable",paragraphs:["Gollwitzer and Sheeran reviewed 94 independent planning tests involving 8,461 participants [S03]. Specifying a situation and intended response improved goal attainment on average. The studies varied in goals, designs, and comparisons and were not restricted to modern preregistered randomized trials. Their standardized effect does not mean a percentage chance of success. It does not test a control-sort, prove Stoicism effective, or guarantee that a cue overrides fatigue or lack of resources.","Use that planning structure for a modest act: after lunch at your work surface, produce one usable evidence sentence. Opening a document is preparation. Rehearsing an interview answer is also preparation and should be named that way, with a later opportunity to use it. An external reply is not your completion condition. Still record relevant feedback rather than discarding it as outside your control. Your next plan should respond to available information, needed support, and the chosen life direction."]}],sourceIds:["stoic-epictetus-iep","stoic-week-handbook","stoic-planning"]}},{schemaVersion:2,revision:2,id:"stoic-2",courseId:"stoic",locale:"en",title:"Their silence is still an unanswered question",goal:"Check one interpretation, then use a grounded clarification or protective response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The reply is late. Are you acting on facts, or guessing why?",reason:{id:"stoic-2-reason",label:"What has this untested interpretation made you do?",kind:"text",maxLength:160,optional:!0,suggestions:["Clarify a real deadline","Stop acting on a guess","Protect a needed boundary"]},why:{id:"stoic-2-why",label:"What has this untested interpretation made you do?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A missed reply is a fact. “They do not respect me” is an interpretation, and it may need evidence. That does not mean the event cannot hurt. Seneca’s account of anger distinguished an involuntary first reaction from later endorsement. It was philosophy, not a complete scientific explanation of distress.","Return to the same goal and act. Check evidence for and against one story blocking it. A fair alternative can be “I do not know yet.” Then clarify a real deadline, correct a fact, or protect a boundary. Keep actual mistreatment visible. Feeling less upset is optional; the grounded response is the test."],example:{title:"Daniel checks the missing reply",text:"On Tuesday at his desk, Daniel sees two missed replies about a reference. He assumes his colleague thinks his work is weak. He cannot verify that reason, but the deadline is real. He sends one question asking whether the reference can arrive Thursday. The colleague has not answered by evening. Daniel records the question and the uncertainty."}},move:{invitation:"Check one story, then take a grounded next step.",instructions:["Name the fact and the interpretation separately.","Use one clarification, factual correction, or safe boundary."],prompts:[],suggestions:{action:["Send one factual clarification about my goal","Use one evidence-based project correction","Make one safe boundary request"],minimum:["Send one clear deadline question","Produce one corrected sentence","State one specific safe limit"],cue:["Before my next reply","At my next project check-in","When the deadline needs clarification"],place:["In a safe message thread","At my usual work surface","In an accessible private space"],minutes:[2,5],fallback:["Choose another safe clarification route","Use known facts without guessing motives","Get support before further contact"],observation:["My question and the actual reply","The fact I corrected","The limit I communicated"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Send one factual clarification about my goal",minimum:"Send one clear deadline question",minutes:2,cueHint:"Before my next reply",placeHint:"In a safe message thread",obstacleHint:"Contact is unsafe, or the other person does not reply.",fallbackHint:"Choose another safe clarification route",observationHint:"My question and the actual reply"},stopRule:"Real harm needs protection. Do not replace evidence of mistreatment with a comforting guess.",accessibleAlternative:"Use your usual communication method, a safe written response, or support instead of contact."},result:{question:"Did you use your grounded response?",observationPrompt:"What did you actually say, and what response came back?"},judgment:{primary:{id:"stoic-2-decision",scenario:"A colleague missed two promised reference replies. Daniel needs the reference Thursday. He has no evidence about the reason for the delay.",question:"Which response checks the story and addresses the deadline?",options:[{id:"comfort-guess",text:"Assume the colleague is overloaded and keep waiting so the relationship stays comfortable.",feedback:"Overload is possible, but it is still an unverified explanation. The missed commitments and deadline need a grounded question, even if the colleague’s motive remains unknown."},{id:"withdraw-work",text:"Reduce cooperation for now so the colleague notices the effect of the missing replies.",feedback:"A boundary may become necessary. With the reason unknown, withdrawing cooperation first adds another assumption. Clarify the deadline and blocker before deciding a suitable limit."},{id:"clarify-deadline",text:"Name the missed replies and ask whether Thursday is workable or another route is needed.",feedback:"This checks missing information while respecting a real pattern. A neutral alternative is not forced positivity. Record the answer, including silence, and decide what support or boundary follows."}],bestOptionId:"clarify-deadline"}},carry:{takeaway:"Check the interpretation and address the real fact. A pleasant guess is still a guess.",followUp:{questionId:"stoic-2-return",question:"Did new evidence support or challenge your interpretation, leave it unknown, or reveal harm?",observationPrompt:"What evidence changed, or is the motive still unknown?",adjustmentPrompt:"Clarify again, change the plan, or get support?"}},goDeeper:{sections:[{heading:"First reactions and tested interpretations",paragraphs:["Seneca’s account of anger separates involuntary first movements from the assent associated with full anger [S10]. It is a historical philosophical distinction, not a complete experimental model of emotion. Panic, pain, trauma symptoms, and an automatic thought are not evidence that you failed to choose correctly. Actual events, circumstances, and interpretations can all matter. Looking at one interpretation is a practical lens, not an exclusive account of why someone suffers.","The NHS thought record offers seven prompts: situation, feelings, thought, evidence for, evidence against, a realistic alternative, and feelings afterward [S11]. Evidence on both sides matters. An alternative can be neutral rather than reassuring. In the example, “The deadline has been missed and I do not know why” keeps both the problem and uncertainty visible. ODA’s short check and action simplify that guidance; they do not reproduce therapy or require the feelings afterward to improve."]},{heading:"A therapy resemblance does not transfer efficacy",paragraphs:["Hofmann and colleagues identified 269 meta-analyses and discussed a representative 106 in their review of cognitive behavioral therapy [S01]. The overview described substantial disorder-specific evidence, particularly for several anxiety-related conditions, anger, and general stress. It did not give one pooled effect or participant count for all CBT. Those findings belong to the treatments studied, not every exercise that resembles a treatment idea. Reading a philosophy lesson does not deliver clinical CBT.","A thought record is officially described self-help guidance [S11], but that source does not establish its isolated clinical effect size. Use it to separate evidence from interpretation and choose an appropriate response. Do not turn every late message into a cognitive error or reinterpret abuse as harmless. If distress is severe, persistent, or affecting daily functioning, qualified support may be the appropriate action. The record can include unchanged anger, a factual clarification, or a protective choice without treating any of them as a failed lesson."]}],sourceIds:["stoic-seneca-iep","stoic-thought-record","stoic-cbt"]}},{schemaVersion:2,revision:2,id:"stoic-3",courseId:"stoic",locale:"en",title:"When the usual interruption arrives, have a response",goal:"Use one realistic obstacle response to keep your existing useful act feasible.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your plan fits a cooperative day. What will you do when its familiar interruption appears?",reason:{id:"stoic-3-reason",label:"Which real obstacle needs a response this time?",kind:"text",maxLength:160,optional:!0,suggestions:["Restart after the usual interruption","Protect a short work slot","Ask for help with access"]},why:{id:"stoic-3-why",label:"Which real obstacle needs a response this time?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Imagining trouble and planning a response are different. Research on planning links a specific obstacle or opening to a feasible act. It does not establish that vivid negative visualization makes you resilient. The useful ingredient here is a response you could actually use, not a worse imagined scene.","Keep your experiment’s direction and act. Pick one mild, realistic friction point from your record. Write an if–then response and use it when needed. Imagery is optional. Do not relive catastrophe or trauma. If the obstacle never appears, record no occasion for that response, while recording any ordinary task attempt separately."],example:{title:"Daniel restarts after a call",text:"Before Wednesday’s portfolio slot, Daniel plans for the call that often interrupts lunch. His response is to restart with one usable evidence sentence when the call ends. The call happens at his desk. He returns, dictates the sentence, and saves it. He gets no further that afternoon, but records the response he actually used."}},move:{invitation:"Prepare one realistic response for your existing act’s friction.",instructions:["Name one likely obstacle without vivid imagery.","Use the response if needed, then record it."],prompts:[],suggestions:{action:["Use my restart response if interrupted","Ask for a workable project boundary","Use my access support if needed"],minimum:["Produce one usable evidence sentence","Make one specific boundary request","Make one specific access request"],cue:["When the usual interruption ends","Before my protected work slot","When the access barrier appears"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use dictation for the useful sentence","Choose the next feasible work opening","Ask a trusted person for assistance"],observation:["Whether interruption and restart happened","Whether I used my response","The usable piece I produced"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use my restart response if interrupted",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When the usual interruption ends",placeHint:"At my usual work surface",obstacleHint:"The response needs time or access I do not have.",fallbackHint:"Use dictation for the useful sentence",observationHint:"Whether interruption and restart happened"},stopRule:"Keep eyes open if preferred. Stop or skip if panic, dissociation, or intrusive memories arise.",accessibleAlternative:"Plan without imagery. Choose a smaller act, practical support, or a safe pause."},result:{question:"Did you use your response when needed?",observationPrompt:"Did the obstacle occur, and what did you actually do?"},judgment:{primary:{id:"stoic-3-decision",scenario:"Daniel’s lunchtime portfolio slot is often interrupted by a brief required call. Care duties fill the earlier slot. Two minutes usually remain after the call. The evidence is needed this evening.",question:"Which response fits that predictable obstacle?",options:[{id:"restart-small",text:"Take the required call, then produce one useful sentence when it ends.",feedback:"This respects the required call and the remaining time. The response is feasible and observable. Record whether the obstacle appeared and whether the restart actually happened."},{id:"same-minimum-tomorrow",text:"Use tomorrow’s two-minute portfolio slot instead, keeping lunch free after the required call.",feedback:"Moving the same small act can protect recovery when time or capacity is unavailable. Here two minutes remain and the evidence is needed tonight. Test the restart now; adapt if capacity changes."},{id:"move-before-lunch",text:"Move the portfolio slot before lunch and arrange to take the required call from there.",feedback:"Moving the slot could avoid the interruption if earlier time were free. Here care duties occupy it. Take the required call and test the useful sentence in the remaining lunch time."}],bestOptionId:"restart-small"}},carry:{takeaway:"Prepare a response you can use, not a catastrophe you can replay.",followUp:{questionId:"stoic-3-return",question:"Did the predicted obstacle happen, and was your response available?",observationPrompt:"Name the obstacle, available restart opening, and response used; untested is valid.",adjustmentPrompt:"Keep the response, shrink it, or change the setting?"}},goDeeper:{sections:[{heading:"Ancient adversity practice and modern planning",paragraphs:["The Stoic Week handbook documents adversity contemplation as a practice [S08]. It is practitioner guidance, not evidence for an isolated negative-visualization effect. Its rationale cannot be presented as a proven mechanism or permission to conduct exposure treatment alone. ODA instead offers a mild everyday obstacle, optional imagery, and a feasible response. Those changes are adaptations. You can plan entirely in words without revisiting any upsetting memory.","Stand-alone implementation intentions connect a specific situation to an intended behavior [S03]. The 2006 review covered 94 independent tests with 8,461 participants and found average goal-attainment benefits across different contexts. It did not show that scripting overrides fatigue, disability, or unavailable resources. A response might be a smaller useful task, a boundary, or support. If the obstacle is danger, address safety rather than asking how to persist. Stop an imagery exercise that brings panic, dissociation, or intrusive memories; a plan without imagery remains available."]},{heading:"The obstacle is not always inside you",paragraphs:["Wang and colleagues reviewed mental contrasting with implementation intentions [S04]. The sequence joins a feasible wish, its desired outcome, a present obstacle, and an if–then response. Across 21 articles and 24 independent estimates with 15,907 participants, average goal attainment improved modestly, g = 0.336. Studies and delivery varied, with meaningful heterogeneity and uneven quality. The findings do not establish an optimal two-minute dose, negative imagery alone, or this ODA version.","A required call, unavailable transport, care duty, or inaccessible equipment is a real condition, not merely a mindset problem. Name it accurately. Your response can be to request help, change the opportunity, or stop an unsuitable plan. Test one condition rather than adding several new rituals. Keep preparation and use separate: writing a restart plan does not prove a restart occurred. If no interruption appears, the backup was not tested. Record that uncertainty and the ordinary act on its own terms."]}],sourceIds:["stoic-week-handbook","stoic-planning","stoic-mcii"]}},{schemaVersion:2,revision:2,id:"stoic-4",courseId:"stoic",locale:"en",title:"A sharp reply is ready. Is it useful?",goal:"Use optional name-based coaching, then a factual response that serves your chosen direction.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"You have the comeback ready. What response would help the goal after these ten seconds pass?",reason:{id:"stoic-4-reason",label:"What would a factual response protect or move forward?",kind:"text",maxLength:160,optional:!0,suggestions:["Protect useful collaboration","Correct the record","Keep a clear boundary"]},why:{id:"stoic-4-why",label:"What would a factual response protect or move forward?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Using your name can create distance during brief reflection. Experiments have studied this, but wider evidence shows modest, varied effects. Calm is not guaranteed. Cosmic and ten-year viewpoints are different exercises without a specific established benefit here.","Use the tool when a heated moment blocks your direction. Optional 60-second preparation: “Daniel, which fact needs correcting, and what request would help?” Substitute your name, or skip it. Then use one factual sentence, request, or boundary. Stepping back must not erase harm. Record the response, even if anger remains."],example:{title:"Daniel returns to the facts",text:"On Thursday’s safe project call, Daniel hears that his checklist caused a delay. He wants to fire back. He asks himself by name what would help the work, then states the actual handoff date and asks which step needs changing. The colleague stays irritated. Daniel records his sentence and request rather than claiming the conflict is solved."}},move:{invitation:"Borrow distance if useful, then return to a factual act.",instructions:["If useful, coach yourself by name for 60 seconds. This is preparation.","Use one factual sentence, request, or safe boundary."],prompts:[],suggestions:{action:["Use one factual correction and request","State one clear project boundary","Ask one grounded clarification question"],minimum:["Use one factual sentence","State one specific safe limit","Send one clear question"],cue:["Before my next heated reply","When inaccurate blame is repeated","At my next safe project check-in"],place:["At my usual work surface","In a safe message thread","In the safe meeting space"],minutes:[2,5],fallback:["Use a safe written factual response","Pause contact and get support","Choose another safe opening"],observation:["The sentence I actually used","The request and actual response","Whether a boundary still needs support"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use one factual correction and request",minimum:"Use one factual sentence",minutes:2,cueHint:"Before my next heated reply",placeHint:"At my usual work surface",obstacleHint:"The interaction is unsafe or the pause increases distress.",fallbackHint:"Use a safe written factual response",observationHint:"The sentence I actually used"},stopRule:"Choose an everyday situation. Stop or skip if panic, dissociation, or intrusive memories arise.",accessibleAlternative:"Keep eyes open, skip reflection, or use an assisted factual response or support."},result:{question:"Did you use your chosen factual response?",observationPrompt:"What did you say or set, and what followed?"},judgment:{primary:{id:"stoic-4-decision",scenario:"Daniel is blamed inaccurately again on a safe call. The wrong date is delaying the next handoff, and he knows the actual date. After a brief pause, he wants the work moving and the record corrected.",question:"Which response uses distance without avoiding the issue?",options:[{id:"let-pass",text:"Let the accusation pass so the team can focus on delivery rather than this conflict.",feedback:"Keeping work moving matters. But silence leaves a relevant inaccurate fact uncorrected. State the handoff date and a next-step request, with a boundary if needed."},{id:"facts-request",text:"State the handoff date, ask what needs changing, and set a limit if blame continues.",feedback:"This returns from reflection to a relevant act. A factual correction and request protect the task without requiring calm. A boundary remains available if the pattern continues."},{id:"separate-follow-up",text:"Request a separate discussion about the repeated blame, then continue the call without correcting the date.",feedback:"A separate discussion can address a recurring pattern. Here the inaccurate date also affects the current task. Correct it briefly now, then arrange the wider discussion if needed."}],bestOptionId:"facts-request"}},carry:{takeaway:"A pause earns its place when it helps you choose a useful response.",followUp:{questionId:"stoic-4-return",question:"Did name-based preparation help, get in the way, or feel unnecessary?",observationPrompt:"What tool did you use or skip, and what factual response followed?",adjustmentPrompt:"Keep the tool, drop it, or strengthen support?"}},goDeeper:{sections:[{heading:"What name-based reflection studied",paragraphs:["Kross and colleagues reported seven studies with 585 participants [S05]. In study 1a, 56 undergraduates reflected on a recent upsetting experience for 60 seconds using their name and non-first-person pronouns instead of first-person language. Reported self-distancing increased. Later experiments examined stressful social tasks and performance. These are convergent experiments within one research program, not seven independent clinical randomized trials or evidence that using your name treats anxiety.","This lesson changes the task to a mild current situation and adds a factual action afterward. That is an ODA adaptation, not the original protocol. There is no need to retrieve a painful memory, close your eyes, or visualize yourself from space. If the wording feels strange or destabilizing, skip it. You can ask directly what the task requires, use a safe written response, or seek support. The real response is a separate act; reflecting or drafting alone is preparation."]},{heading:"Modest effects and no sleep promise",paragraphs:["Murdoch and colleagues pooled 25 experiments in 17 papers involving 2,397 adults [S06]. The overall self-distancing effect was modest, g = 0.19, with a 95% confidence interval of 0.05 to 0.33. Evidence quality was uncertain, participants were mostly young and apparently healthy, and results varied substantially. The prediction interval crossed zero. Objective outcomes in four experiments were nonsignificant. These results do not establish superiority for people with greater distress or a specific effect for cosmic or ten-year imagery.","A preregistered reflection study did not support distancing as a sleep intervention [S16]. Sleep-quality change favored immersion, sleep-duration difference was nonsignificant, and asymmetric exclusions complicated interpretation. Its well-being table and narrative had inconsistent signs, so no directional well-being claim is justified here. Choose this tool for an optional perspective shift, not better sleep or reliable emotional relief. Keep the seriousness of the issue visible and judge its practical fit by whether it helps a grounded action."]}],sourceIds:["stoic-kross-self-talk","stoic-kross-distancing","stoic-distancing-sleep"]}},{schemaVersion:2,revision:2,id:"stoic-5",courseId:"stoic",locale:"en",title:"One rough attempt is not your whole character",goal:"Review your latest attempt fairly and use one concrete correction at the next opportunity.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still replaying what went wrong? Find the one change your next attempt can actually use.",reason:{id:"stoic-5-reason",label:"What specific condition needs changing, rather than another replay?",kind:"text",maxLength:160,optional:!0,suggestions:["Learn from the actual attempt","Make one practical correction","Stop judging my whole character"]},why:{id:"stoic-5-why",label:"What specific condition needs changing, rather than another replay?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["The Stoic handbook’s evening review asks what went wrong, what went well, and what could change. It is documented guidance, not an independently proven treatment or sleep aid. Keep the review specific. “I missed the agreed date” offers a correction; “I am useless” gives no useful next step.","Use your experiment’s latest record. Keep one part that served its purpose and change one condition that did not. Then use that correction in the next act. Reviewing is learning or preparation; it does not mean the later action happened. Skip a separate nightly ritual if the existing return is enough."],example:{title:"Daniel uses the review",text:"At Friday lunch, Daniel reviews Thursday’s call at his desk. He corrected the date but omitted the supporting note. He credits the correction and chooses one change: include the evidence line in his follow-up. He sends it that afternoon. The disagreement remains. His record distinguishes reviewing from sending the actual corrected message."}},move:{invitation:"Use your latest record to choose and try one correction.",instructions:["Name one useful part and one specific mismatch.","Use one correction in the next act."],prompts:[],suggestions:{action:["Use one project correction from my review","Make one suitable repair from my record","Use the changed cue for my useful act"],minimum:["Send one corrected project sentence","Make one specific repair request","Produce one usable evidence sentence"],cue:["At my next project follow-up","At my next safe repair opening","At the revised cue I selected"],place:["In a safe message thread","At my usual work surface","In my accessible planning space"],minutes:[2,5],fallback:["Use a smaller factual correction","Choose another safe opening","Get support instead of replaying"],observation:["The correction I actually used","What the changed condition allowed","The request and actual response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use one project correction from my review",minimum:"Send one corrected project sentence",minutes:2,cueHint:"At my next project follow-up",placeHint:"In a safe message thread",obstacleHint:"The review becomes repetitive or the correction is unsafe.",fallbackHint:"Use a smaller factual correction",observationHint:"The correction I actually used"},stopRule:"Stop, shorten, or move reviews that feed rumination or disrupt sleep. Protect safety.",accessibleAlternative:"Use a brief spoken or assisted review, the saved return, or support instead of another ritual."},result:{question:"Did you use the correction you chose?",observationPrompt:"What did you change in the actual act?"},judgment:{primary:{id:"stoic-5-decision",scenario:"Daniel’s evening work slot failed twice when care duties ran late. He still wants project evidence. Lunch offers two safe minutes at his desk.",question:"What makes the review useful?",options:[{id:"same-plan",text:"Record the late care duties and repeat the evening slot to build more consistency.",feedback:"The record is honest, but the condition has repeatedly failed. Keep the direction and test the available lunch minimum instead of asking the same slot to work again."},{id:"make-up",text:"Record the missed slot and plan a longer weekend session to make up the work.",feedback:"A longer session may be useful if feasible. It does not test the recurring cue problem. Try the small available slot before adding compensatory demands."},{id:"cue-change",text:"Credit his care commitment and move one evidence sentence to the available lunch cue.",feedback:"This names a real constraint, preserves what he did, and changes one condition. The review is separate from the next attempt; record whether the lunch act actually happens."}],bestOptionId:"cue-change"}},carry:{takeaway:"Use a fair review to change one condition, then test it in the next act.",followUp:{questionId:"stoic-5-return",question:"Was your changed condition tested, and what did it enable?",observationPrompt:"Name the correction and act, or mark the condition not tested.",adjustmentPrompt:"Keep the correction, change the cue, or seek support?"}},goDeeper:{sections:[{heading:"The review is guidance, not a verdict",paragraphs:["The Stoic Week handbook describes five to ten minutes of evening review before getting into bed [S08]. The three questions ask what went wrong, what went well, and what could be different. It recommends assessing yourself fairly, as you would a friend. This is a documented practitioner procedure, not an empirically established optimal dose or a trial of the review by itself. A shortened ODA return and moving the review earlier are adaptations.","Review the chosen experiment, rather than putting every part of your character on trial. Keep an observable slip, a useful contribution, and one specific change. Do not force forgiveness, an apology, or a warm feeling. A repair is appropriate when you caused harm; protection may be appropriate when harm was done to you. If a review becomes punitive, repetitive, or disruptive to sleep, shorten, move, or stop it. The goal here is an actionable correction, not guaranteed relief or an extra nightly obligation."]},{heading:"Direct Stoic research exists, with limits",paragraphs:["Direct controlled research on Stoic training remains preliminary. Maclellan and Derakshan randomized 45 high worriers among eight-session Stoic training, combined training, and an active control [S13]. Their abstract reported changes in rumination and self-efficacy. It does not establish which component helped or whether an isolated evening review treats diagnosed anxiety. A small training study cannot tell you that repeating this review will reliably change symptoms.","King’s 2025 doctoral thesis allocated 119 nonclinical adults to two-week online Stoic training or a waitlist [S15]. Its institutional abstract reported favorable complete-case changes on some mental-health measures. An unpublished thesis with a waitlist comparison provides early evidence, rather than a peer-reviewed consensus. Neither study establishes that this brief ODA adaptation reproduces the training. Try one fair correction if it suits you, record what happens, and seek qualified help when distress persists or impairs daily functioning. The record should identify a condition actually changed and an act actually tried; a new plan alone leaves the correction untested."]}],sourceIds:["stoic-week-handbook","stoic-training-trial","stoic-training-thesis"]}},{schemaVersion:2,revision:2,id:"stoic-6",courseId:"stoic",locale:"en",title:"Busy all week. Did your priority get a turn?",goal:"Use your records to keep one useful act and one workable condition for next week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Busy week. Which recorded act served your direction?",reason:{id:"stoic-6-reason",label:"What will get less time so your priority gets a turn?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the useful minimum","Use the cue that worked","Drop unhelpful extra rituals"]},why:{id:"stoic-6-why",label:"What will get less time so your priority gets a turn?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Choosing an easy task and choosing a relevant act are different. Mental contrasting and planning research joins a feasible wish, its outcome, a real obstacle, and a specific response. Average benefits are modest and varied. The method does not guarantee success or turn every obstacle into a personal fault.","Consolidate your same experiment. Read the actual attempts, including unavailable openings and pauses. Keep the useful act and cue; change one condition if needed. Then try the next minimum. Drop tools that did not help. An outcome remains uncertain, but its feedback can still change the plan. Support or stopping remains legitimate."],example:{title:"Daniel keeps what worked",text:"At Monday lunch the next week, Daniel checks his records. Two usable sentences came from the short desk slot. Another attempt stopped when access failed. He keeps the slot, asks for the missing access, and produces one new evidence sentence. He drops extra imagery. The application is still pending, but his next plan uses the observed conditions."}},move:{invitation:"Keep the relevant act. Choose its next workable opportunity.",instructions:["Use your records to keep or change one condition.","Do the useful minimum; leave other tools optional."],prompts:[],suggestions:{action:["Repeat my useful project evidence act","Repeat my grounded clarification act","Use the support request my record suggests"],minimum:["Produce one usable evidence sentence","Send one clear question","Make one specific access request"],cue:["When I return from lunch","At my next safe project follow-up","Before my next project attempt"],place:["At my usual work surface","In a safe message thread","In my accessible planning space"],minutes:[2,5],fallback:["Use my tested smaller version","Choose the next accessible opening","Get support or stop this unsuitable plan"],observation:["The relevant piece I produced","Whether my chosen cue occurred","What the tested condition allowed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful project evidence act",minimum:"Produce one usable evidence sentence",minutes:2,cueHint:"When I return from lunch",placeHint:"At my usual work surface",obstacleHint:"The old minimum or cue no longer fits my circumstances.",fallbackHint:"Use my tested smaller version",observationHint:"The relevant piece I produced"},stopRule:"Keep safety and needed recovery ahead of persistence. Change, pause, or stop unsuitable plans.",accessibleAlternative:"Keep one accessible act, use assistance, or choose support without maintaining every course tool."},result:{question:"Did you do the next useful minimum?",observationPrompt:"What did you actually do, and what feedback remains relevant?"},judgment:{primary:{id:"stoic-6-decision",scenario:"Daniel checked which project examples meet the employer’s requirements. One relevant example still lacks an evidence sentence. His records show lunch drafts work, and he has ten minutes today.",question:"Which act most directly serves the priority?",options:[{id:"draft-relevant",text:"Produce one relevant evidence sentence at the tested lunch cue, with an accessible backup if needed.",feedback:"This keeps the relevant act and a condition supported by his records. It creates an observable piece without promising acceptance. Record the attempt and use later feedback."},{id:"advice-read",text:"Read application advice for ten minutes and choose an evidence task after reviewing more recommendations.",feedback:"Advice helps when information is missing. Here the needed example and a workable cue are known. More reading postpones producing the relevant piece this slot can hold."},{id:"check-relevance-again",text:"Review earlier evidence sentences and choose which one most closely matches the employer’s requirements.",feedback:"Checking relevance helps when requirements or fit are unclear. Daniel already checked them, and this example lacks its sentence. Use the available drafting slot; check again if the requirements change."}],bestOptionId:"draft-relevant"}},carry:{takeaway:"Keep the useful act and a workable condition. Let feedback improve what comes next.",followUp:{questionId:"stoic-6-return",question:"Did your chosen condition help, fail, stay untested, or leave you unsure?",observationPrompt:"Which condition occurred, and what act did you actually attempt?",adjustmentPrompt:"Repeat, change one condition, get support, or stop?"}},goDeeper:{sections:[{heading:"Consolidation uses relevant evidence",paragraphs:["Epictetus’s distinction is philosophical guidance for effort [S09]. It does not require ignoring the results of an action. A reply, a failed access route, or a repeated conflict can inform what you try next. You cannot determine an employer’s decision alone, but you can use appropriate feedback and seek assistance. Your record should include the act and relevant outcome without turning either into a verdict about your whole character.","Implementation-intention research supports linking a recognizable situation with an intended response across varied goals and settings [S03]. That structure is useful only when the response is feasible and relevant. “After lunch, write one usable project evidence sentence” is a concrete act. “After lunch, make the employer approve” is an external outcome. Preparing or reading advice may be suitable, but label it honestly. The final lesson consolidates one continuing experiment rather than introducing another daily ritual or treating a completed course as proof of real-world practice."]},{heading:"A wish, an obstacle, and a feasible response",paragraphs:["Wang and colleagues reviewed mental contrasting with implementation intentions [S04]. The sequence names a feasible wish, its desired outcome, a present obstacle, and a specific if–then response. Across 21 articles with 24 independent estimates and 15,907 participants, average goal attainment improved by g = 0.336, with a 95% confidence interval of 0.229 to 0.443. Heterogeneity was substantial, I² = 59.3%, and study quality varied. This is a contemporary estimate for the combined sequence, not a universal success rate.","ODA’s brief use of the sequence and weekly record review are adaptations. No universal dose or efficacy for this exact flow was established. Choose an act that addresses the actual priority, rather than easy busywork or every exercise in the course. If the obstacle is external danger, missing resources, illness, or a care demand, the response may be support, a boundary, rest, or stopping the goal. Record the next attempt separately from its plan and review. Unchanged emotion and an uncertain external outcome do not erase a reported useful act."]}],sourceIds:["stoic-epictetus-iep","stoic-planning","stoic-mcii"]}}],G=[{id:"stoic-1",practice:["Choose one goal and separate a feasible act, needed support, and external outcomes.","Name a recognizable opening and useful minimum.","Do the act, or explicitly name preparation and its later use."],correct:1,photo:{id:"1507525428034-b723cf961d3e",alt:"A calm shoreline where clear water meets the sand"}},{id:"stoic-2",practice:["Separate one fact from an unverified interpretation.","Check evidence on both sides without minimizing actual harm.","Use a grounded clarification, factual correction, or safe protective response."],correct:2,photo:{id:"1500534314209-a25ddb2bd429",alt:"Layers of hazy hills at dusk"}},{id:"stoic-3",practice:["Choose a mild realistic obstacle for your existing act; imagery is optional.","Plan one feasible response and stop if distress grows.","Use the response when needed and record whether the obstacle occurred."],correct:1,photo:{id:"1464822759023-fed622ff2c3b",alt:"Forested valleys below snowy mountains"}},{id:"stoic-4",practice:["Choose a mild everyday situation and optionally coach yourself by name for 60 seconds.","Stop or skip if panic, dissociation, or intrusive memories arise.","Use one factual sentence, request, or safe boundary and record it."],correct:0,photo:{id:"1506905925346-21bda4d32df4",alt:"Mountain ridges seen from above a sea of clouds"}},{id:"stoic-5",practice:["Review one actual attempt, naming a useful part and a specific mismatch.","Choose one correction; shorten, move, or stop a punitive or sleep-disrupting review.","Use the correction in a real act and record it separately from reviewing."],correct:1,photo:{id:"1475924156734-496f6cac6ec1",alt:"Waves on a rocky shore at dusk"}},{id:"stoic-6",practice:["Compare actual attempts for your existing goal and act.","Keep the useful minimum and change at most one condition.","Try the next relevant act, record it, and leave extra tools optional."],correct:2,photo:{id:"1502082553048-f009c37129b9",alt:"A single tree standing in an open landscape"}}],$={id:"stoic",title:"Checking again? Give your next useful act a turn",subtitle:"6 lessons to act under uncertainty, check your interpretations, and carry one workable experiment into next week.",description:"Choose one goal that uncertainty is crowding out. Use Stoic distinctions and optional psychological tools to make a grounded act, review it, and adapt.",scope:"For adults who want steadier responses to stress, setbacks and uncertainty. Stoicism here does not mean suppressing emotions or putting on a brave face; feelings are welcome, and the practice is about what you do next. This is education and self-practice, not therapy, and it is not a substitute for treatment. If you live with anxiety, depression, trauma or intrusive worry, some exercises, especially imagining setbacks, may not suit you; please work with a qualified professional. If you are in crisis or thinking about harming yourself, contact your local emergency number now.",outcome:"One goal-linked experiment with actual acts, honest reviews, and a next-week plan that includes support and boundaries.",photo:{id:"1439066615861-d1af74d74000",alt:"A wooden pier on a still mountain lake"},lessons:I.map((e,t)=>{const a=G[t],n=e.judgment.primary,c=n.options.find(o=>o.id===n.bestOptionId),i=n.options.filter(o=>o.id!==n.bestOptionId).map(o=>o.text);return i.splice(a.correct,0,c.text),{...a,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:i,feedback:c.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})},ae=Object.freeze(Object.defineProperty({__proto__:null,COURSE:$,SOURCES:V,STOIC_LESSONS_V2:I},Symbol.toStringTag,{value:"Module"}));export{X as a,ee as b,ae as c,te as o,Q as p,Z as s,J as t};
